def normalize_identity_scope(
    value: Any,
    *,
    default: str = IDENTITY_SCOPE_INTERACTION,
) -> str:
    """
    Normalize an interaction-identity scope.
    """

    normalized = _normalize_scoring_name(value)

    if not normalized:
        return default

    if normalized in IDENTITY_SCOPES:
        return normalized

    return _IDENTITY_SCOPE_ALIASES.get(
        normalized,
        default,
    )


def normalize_identity_orientation(
    value: Any,
    *,
    default: str = IDENTITY_ORIENTATION_AUTO,
) -> str:
    """
    Normalize interaction-pair orientation behavior.
    """

    normalized = _normalize_scoring_name(value)

    if not normalized:
        return default

    if normalized in IDENTITY_ORIENTATIONS:
        return normalized

    return _IDENTITY_ORIENTATION_ALIASES.get(
        normalized,
        default,
    )


def normalize_duplicate_selection_mode(
    value: Any,
    *,
    default: str = DUPLICATE_SELECTION_FIRST,
) -> str:
    """
    Normalize duplicate representative-selection behavior.
    """

    normalized = _normalize_scoring_name(value)

    if not normalized:
        return default

    if normalized in DUPLICATE_SELECTION_MODES:
        return normalized

    return _DUPLICATE_SELECTION_ALIASES.get(
        normalized,
        default,
    )


def normalize_deduplication_status(
    value: Any,
    *,
    default: str = DEDUPLICATION_STATUS_UNIQUE,
) -> str:
    """
    Normalize a deduplication record status.
    """

    normalized = _normalize_scoring_name(value)

    if not normalized:
        return default

    if normalized in DEDUPLICATION_STATUSES:
        return normalized

    return _DEDUPLICATION_STATUS_ALIASES.get(
        normalized,
        default,
    )


# -----------------------------------------------------------------------------
# 7.3. Identity and deduplication exceptions
# -----------------------------------------------------------------------------

class InteractionIdentityError(ScoringError):
    """
    Base exception for interaction-identity failures.
    """


class MissingInteractionIdentityError(InteractionIdentityError):
    """
    Raised when a required identity cannot be constructed.
    """


class InvalidDeduplicationConfigurationError(InteractionIdentityError):
    """
    Raised when deduplication configuration is invalid.
    """


class DuplicateResolutionError(InteractionIdentityError):
    """
    Raised when duplicate resolution cannot be completed.
    """


# -----------------------------------------------------------------------------
# 7.4. InteractionIdentityKey
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class InteractionIdentityKey:
    """
    Immutable canonical identity for one interaction.

    The key can include interaction type, atom pair, residue pair, pose,
    model and selected geometric buckets. Its exact content depends on the
    deduplication configuration used to build it.

    Parameters
    ----------
    interaction_type
        Canonical interaction type.
    interaction_family
        Canonical interaction family.
    atom_pair
        Canonical atom-identifier pair.
    residue_pair
        Canonical residue-identifier pair.
    pose_id
        Optional pose identifier.
    model_id
        Optional model identifier.
    geometry_key
        Quantized geometry identity.
    orientation
        Ordered or unordered pair semantics.
    custom_parts
        Additional deterministic key components.
    """

    interaction_type: str = SCORE_TYPE_UNKNOWN
    interaction_family: str = SCORE_FAMILY_UNKNOWN

    atom_pair: Optional[Tuple[str, str]] = None
    residue_pair: Optional[Tuple[str, str]] = None

    pose_id: str = ""
    model_id: str = ""

    geometry_key: Tuple[str, ...] = field(
        default_factory=tuple
    )
    orientation: str = IDENTITY_ORIENTATION_AUTO
    custom_parts: Tuple[str, ...] = field(
        default_factory=tuple
    )

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize all identity components.
        """

        interaction_type = normalize_interaction_type(
            self.interaction_type,
            preserve_unknown=True,
        )

        interaction_family = canonical_interaction_family(
            self.interaction_family
            or interaction_type
        )

        orientation = normalize_identity_orientation(
            self.orientation
        )

        atom_pair = _normalize_identifier_pair(
            self.atom_pair,
            field_name="InteractionIdentityKey.atom_pair",
        )

        residue_pair = _normalize_identifier_pair(
            self.residue_pair,
            field_name="InteractionIdentityKey.residue_pair",
        )

        if orientation == IDENTITY_ORIENTATION_UNORDERED:
            if atom_pair is not None:
                atom_pair = tuple(sorted(atom_pair))

            if residue_pair is not None:
                residue_pair = tuple(sorted(residue_pair))

        geometry_key = tuple(
            _coerce_identifier(part)
            for part in self.geometry_key
            if _coerce_identifier(part)
        )

        custom_parts = tuple(
            _coerce_identifier(part)
            for part in self.custom_parts
            if _coerce_identifier(part)
        )

        object.__setattr__(
            self,
            "interaction_type",
            interaction_type,
        )
        object.__setattr__(
            self,
            "interaction_family",
            interaction_family,
        )
        object.__setattr__(
            self,
            "atom_pair",
            atom_pair,
        )
        object.__setattr__(
            self,
            "residue_pair",
            residue_pair,
        )
        object.__setattr__(
            self,
            "pose_id",
            _coerce_identifier(self.pose_id),
        )
        object.__setattr__(
            self,
            "model_id",
            _coerce_identifier(self.model_id),
        )
        object.__setattr__(
            self,
            "geometry_key",
            geometry_key,
        )
        object.__setattr__(
            self,
            "orientation",
            orientation,
        )
        object.__setattr__(
            self,
            "custom_parts",
            custom_parts,
        )
        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(self.metadata),
        )

    @property
    def has_atom_identity(self) -> bool:
        """Return whether an atom pair is part of the identity."""

        return self.atom_pair is not None

    @property
    def has_residue_identity(self) -> bool:
        """Return whether a residue pair is part of the identity."""

        return self.residue_pair is not None

    @property
    def is_empty(self) -> bool:
        """
        Return whether the key contains no structural identity.
        """

        return not any(
            (
                self.atom_pair,
                self.residue_pair,
                self.pose_id,
                self.model_id,
                self.geometry_key,
                self.custom_parts,
            )
        )

    @property
    def parts(self) -> Tuple[Any, ...]:
        """
        Return the immutable identity tuple.
        """

        return (
            self.interaction_type,
            self.interaction_family,
            self.atom_pair,
            self.residue_pair,
            self.pose_id,
            self.model_id,
            self.geometry_key,
            self.custom_parts,
        )

    @property
    def string(self) -> str:
        """
        Return a stable human-readable identity string.
        """

        parts: List[str] = [
            self.interaction_type,
        ]

        if self.atom_pair is not None:
            parts.append(
                "atoms="
                + "|".join(self.atom_pair)
            )

        if self.residue_pair is not None:
            parts.append(
                "residues="
                + "|".join(self.residue_pair)
            )

        if self.pose_id:
            parts.append(
                f"pose={self.pose_id}"
            )

        if self.model_id:
            parts.append(
                f"model={self.model_id}"
            )

        if self.geometry_key:
            parts.append(
                "geometry="
                + "|".join(self.geometry_key)
            )

        if self.custom_parts:
            parts.append(
                "custom="
                + "|".join(self.custom_parts)
            )

        return "::".join(parts)

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
    ) -> Dict[str, Any]:
        """
        Return a mutable dictionary representation.
        """

        result: Dict[str, Any] = {
            "interaction_type": self.interaction_type,
            "interaction_family": self.interaction_family,
            "atom_pair": (
                None
                if self.atom_pair is None
                else list(self.atom_pair)
            ),
            "residue_pair": (
                None
                if self.residue_pair is None
                else list(self.residue_pair)
            ),
            "pose_id": self.pose_id,
            "model_id": self.model_id,
            "geometry_key": list(self.geometry_key),
            "orientation": self.orientation,
            "custom_parts": list(self.custom_parts),
            "string": self.string,
            "is_empty": bool(self.is_empty),
        }

        if include_metadata:
            result["metadata"] = dict(self.metadata)

        return result

    def __str__(self) -> str:
        """Return the stable identity string."""

        return self.string

    def __hash__(self) -> int:
        """
        Return a stable identity hash.
        """

        return hash(self.parts)


# -----------------------------------------------------------------------------
# 7.5. Deduplication configuration
# -----------------------------------------------------------------------------

IdentityKeyFunction = Callable[
    [Any],
    Union[
        InteractionIdentityKey,
        Sequence[Any],
        str,
    ],
]


@dataclass(frozen=True, slots=True)
class DeduplicationConfig:
    """
    Immutable interaction-deduplication configuration.

    Parameters
    ----------
    mode
        Canonical deduplication mode defined in Section 2.
    identity_scope
        Preferred identity scope.
    orientation
        Ordered, unordered or automatically inferred pair orientation.
    selection_mode
        Rule used to choose a representative from duplicate groups.
    include_interaction_type
        Include canonical interaction type in the key.
    include_interaction_family
        Include canonical interaction family in the key.
    include_atom_pair
        Include atom identifiers when available.
    include_residue_pair
        Include residue identifiers when available.
    include_pose_id
        Restrict duplicate identity to the same pose.
    include_model_id
        Restrict duplicate identity to the same model.
    include_geometry
        Include quantized geometry in the identity.
    allow_residue_fallback
        Use residue identity when atom identity is unavailable.
    allow_identifier_fallback
        Use the explicit interaction ID when structural identity is missing.
    require_identity
        Raise when no usable identity can be constructed.
    retain_duplicate_records
        Preserve full duplicate audit records.
    mark_duplicate_scores
        Convert duplicate InteractionScore objects to duplicate status.
    custom_key
        Optional custom deterministic identity function.
    """

    mode: str = DEDUPLICATION_MODE_ATOM_PAIR
    identity_scope: str = IDENTITY_SCOPE_INTERACTION
    orientation: str = IDENTITY_ORIENTATION_AUTO
    selection_mode: str = DUPLICATE_SELECTION_FIRST

    include_interaction_type: bool = True
    include_interaction_family: bool = False

    include_atom_pair: bool = True
    include_residue_pair: bool = False

    include_pose_id: bool = True
    include_model_id: bool = True
    include_geometry: bool = False

    allow_residue_fallback: bool = True
    allow_identifier_fallback: bool = True
    require_identity: bool = False

    retain_duplicate_records: bool = True
    mark_duplicate_scores: bool = True

    distance_tolerance: float = (
        DEFAULT_DEDUPLICATION_DISTANCE_TOLERANCE
    )
    angle_tolerance: float = (
        DEFAULT_DEDUPLICATION_ANGLE_TOLERANCE
    )
    offset_tolerance: float = (
        DEFAULT_DEDUPLICATION_OFFSET_TOLERANCE
    )
    planarity_tolerance: float = (
        DEFAULT_DEDUPLICATION_PLANARITY_TOLERANCE
    )
    overlap_tolerance: float = (
        DEFAULT_DEDUPLICATION_OVERLAP_TOLERANCE
    )

    custom_key: Optional[IdentityKeyFunction] = field(
        default=None,
        compare=False,
        hash=False,
        repr=False,
    )

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Validate deduplication configuration.
        """

        mode = normalize_deduplication_mode(
            self.mode
        )

        identity_scope = normalize_identity_scope(
            self.identity_scope
        )

        orientation = normalize_identity_orientation(
            self.orientation
        )

        selection_mode = normalize_duplicate_selection_mode(
            self.selection_mode
        )

        tolerances = {
            "distance_tolerance": self.distance_tolerance,
            "angle_tolerance": self.angle_tolerance,
            "offset_tolerance": self.offset_tolerance,
            "planarity_tolerance": self.planarity_tolerance,
            "overlap_tolerance": self.overlap_tolerance,
        }

        normalized_tolerances: Dict[str, float] = {}

        for name, value in tolerances.items():
            normalized = _coerce_finite_score_value(
                value,
                name=f"DeduplicationConfig.{name}",
            )

            if normalized <= 0.0:
                raise InvalidDeduplicationConfigurationError(
                    f"{name} must be greater than zero."
                )

            normalized_tolerances[name] = float(
                normalized
            )

        if (
            self.custom_key is not None
            and not callable(self.custom_key)
        ):
            raise InvalidDeduplicationConfigurationError(
                "custom_key must be callable or None."
            )

        if not any(
            (
                self.include_atom_pair,
                self.include_residue_pair,
                self.include_geometry,
                self.allow_identifier_fallback,
                self.custom_key is not None,
            )
        ):
            raise InvalidDeduplicationConfigurationError(
                "DeduplicationConfig must enable at least one "
                "identity source."
            )

        object.__setattr__(
            self,
            "mode",
            mode,
        )
        object.__setattr__(
            self,
            "identity_scope",
            identity_scope,
        )
        object.__setattr__(
            self,
            "orientation",
            orientation,
        )
        object.__setattr__(
            self,
            "selection_mode",
            selection_mode,
        )

        for name, value in normalized_tolerances.items():
            object.__setattr__(
                self,
                name,
                value,
            )

        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(self.metadata),
        )

    def with_updates(
        self,
        **changes: Any,
    ) -> "DeduplicationConfig":
        """
        Return a validated configuration copy.
        """

        return replace(
            self,
            **changes,
        )

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
    ) -> Dict[str, Any]:
        """
        Return a mutable dictionary representation.
        """

        result: Dict[str, Any] = {
            "mode": self.mode,
            "identity_scope": self.identity_scope,
            "orientation": self.orientation,
            "selection_mode": self.selection_mode,
            "include_interaction_type": bool(
                self.include_interaction_type
            ),
            "include_interaction_family": bool(
                self.include_interaction_family
            ),
            "include_atom_pair": bool(self.include_atom_pair),
            "include_residue_pair": bool(
                self.include_residue_pair
            ),
            "include_pose_id": bool(self.include_pose_id),
            "include_model_id": bool(self.include_model_id),
            "include_geometry": bool(self.include_geometry),
            "allow_residue_fallback": bool(
                self.allow_residue_fallback
            ),
            "allow_identifier_fallback": bool(
                self.allow_identifier_fallback
            ),
            "require_identity": bool(self.require_identity),
            "retain_duplicate_records": bool(
                self.retain_duplicate_records
            ),
            "mark_duplicate_scores": bool(
                self.mark_duplicate_scores
            ),
            "distance_tolerance": float(
                self.distance_tolerance
            ),
            "angle_tolerance": float(
                self.angle_tolerance
            ),
            "offset_tolerance": float(
                self.offset_tolerance
            ),
            "planarity_tolerance": float(
                self.planarity_tolerance
            ),
            "overlap_tolerance": float(
                self.overlap_tolerance
            ),
            "has_custom_key": self.custom_key is not None,
        }

        if include_metadata:
            result["metadata"] = dict(self.metadata)

        return result


DEFAULT_DEDUPLICATION_CONFIG: Final[
    DeduplicationConfig
] = DeduplicationConfig()


# -----------------------------------------------------------------------------
# 7.6. Geometry quantization
# -----------------------------------------------------------------------------

def _quantize_identity_value(
    value: Optional[Number],
    tolerance: Number,
    *,
    label: str,
) -> Optional[str]:
    """
    Quantize a geometry value into a stable identity bucket.
    """

    if value is None:
        return None

    numeric_value = _coerce_finite_score_value(
        value,
        name=label,
    )

    numeric_tolerance = _coerce_finite_score_value(
        tolerance,
        name=f"{label} tolerance",
    )

    if numeric_tolerance <= 0.0:
        raise InvalidDeduplicationConfigurationError(
            f"{label} tolerance must be greater than zero."
        )

    bucket = round(
        numeric_value / numeric_tolerance
    )

    return f"{label}:{bucket}"


def build_geometry_identity_key(
    source: Any,
    *,
    config: DeduplicationConfig = DEFAULT_DEDUPLICATION_CONFIG,
) -> Tuple[str, ...]:
    """
    Build quantized geometry identity components.
    """

    if isinstance(source, ExtractedInteractionData):
        distance = source.distance
        angle = source.angle
        offset = source.offset
        planarity = source.planarity
        overlap = source.overlap
    else:
        distance = extract_interaction_distance(source)
        angle = extract_interaction_angle(source)
        offset = extract_interaction_offset(source)
        planarity = extract_interaction_planarity(source)
        overlap = extract_interaction_overlap(source)

    quantized = (
        _quantize_identity_value(
            distance,
            config.distance_tolerance,
            label="distance",
        ),
        _quantize_identity_value(
            angle,
            config.angle_tolerance,
            label="angle",
        ),
        _quantize_identity_value(
            offset,
            config.offset_tolerance,
            label="offset",
        ),
        _quantize_identity_value(
            planarity,
            config.planarity_tolerance,
            label="planarity",
        ),
        _quantize_identity_value(
            overlap,
            config.overlap_tolerance,
            label="overlap",
        ),
    )

    return tuple(
        item
        for item in quantized
        if item is not None
    )


def geometry_values_are_equivalent(
    first: Optional[Number],
    second: Optional[Number],
    *,
    tolerance: Number,
    missing_matches_missing: bool = True,
) -> bool:
    """
    Return whether two optional geometry values are equivalent.
    """

    if first is None or second is None:
        return (
            missing_matches_missing
            and first is None
            and second is None
        )

    first_value = _coerce_finite_score_value(
        first,
        name="first geometry value",
    )
    second_value = _coerce_finite_score_value(
        second,
        name="second geometry value",
    )
    tolerance_value = _coerce_finite_score_value(
        tolerance,
        name="geometry tolerance",
    )

    return abs(
        first_value - second_value
    ) <= tolerance_value


# -----------------------------------------------------------------------------
# 7.7. Pair orientation
# -----------------------------------------------------------------------------

_DIRECTIONAL_INTERACTION_TYPES: Final[FrozenSet[str]] = frozenset(
    {
        SCORE_TYPE_HYDROGEN_BOND,
    }
)


_SYMMETRIC_INTERACTION_TYPES: Final[FrozenSet[str]] = frozenset(
    {
        SCORE_TYPE_HYDROPHOBIC,
        SCORE_TYPE_PI_STACKING,
        SCORE_TYPE_T_SHAPED,
        SCORE_TYPE_SALT_BRIDGE,
        SCORE_TYPE_CLASH,
        SCORE_TYPE_CONTACT,
    }
)


def interaction_identity_orientation(
    interaction_type: Any,
    *,
    configured_orientation: Any = IDENTITY_ORIENTATION_AUTO,
) -> str:
    """
    Resolve pair orientation for an interaction type.

    Hydrogen bonds remain directional because donor and acceptor roles are
    not interchangeable. Symmetric contact types use unordered pairs.
    """

    orientation = normalize_identity_orientation(
        configured_orientation
    )

    if orientation != IDENTITY_ORIENTATION_AUTO:
        return orientation

    canonical_type = normalize_interaction_type(
        interaction_type,
        preserve_unknown=True,
    )

    if canonical_type in _DIRECTIONAL_INTERACTION_TYPES:
        return IDENTITY_ORIENTATION_ORDERED

    if canonical_type in _SYMMETRIC_INTERACTION_TYPES:
        return IDENTITY_ORIENTATION_UNORDERED

    return IDENTITY_ORIENTATION_UNORDERED


def normalize_identity_pair(
    pair: Optional[Sequence[Any]],
    *,
    orientation: str,
    field_name: str,
) -> Optional[Tuple[str, str]]:
    """
    Normalize an identity pair according to orientation semantics.
    """

    normalized_pair = _normalize_identifier_pair(
        pair,
        field_name=field_name,
    )

    if normalized_pair is None:
        return None

    resolved_orientation = normalize_identity_orientation(
        orientation,
        default=IDENTITY_ORIENTATION_UNORDERED,
    )

    if resolved_orientation == IDENTITY_ORIENTATION_UNORDERED:
        return tuple(sorted(normalized_pair))

    return normalized_pair


# -----------------------------------------------------------------------------
# 7.8. Source-value helpers
# -----------------------------------------------------------------------------

def _identity_source_data(
    source: Any,
) -> ExtractedInteractionData:
    """
    Convert a supported source to canonical extracted interaction data.
    """

    if isinstance(source, ExtractedInteractionData):
        return source

    if isinstance(source, InteractionRecognitionResult):
        if source.interaction is None:
            raise MissingInteractionIdentityError(
                "Recognition result has no interaction reference."
            )

        extracted = extract_interaction_data(
            source.interaction,
            preserve_reference=True,
        )

        return apply_recognition_to_extracted_data(
            extracted,
            source,
        )

    return extract_interaction_data(
        source,
        preserve_reference=True,
    )


def _normalize_custom_identity_parts(
    value: Union[
        InteractionIdentityKey,
        Sequence[Any],
        str,
    ],
) -> Union[
    InteractionIdentityKey,
    Tuple[str, ...],
]:
    """
    Normalize the output of a custom identity function.
    """

    if isinstance(value, InteractionIdentityKey):
        return value

    if isinstance(value, str):
        normalized = _coerce_identifier(value)

        if not normalized:
            raise MissingInteractionIdentityError(
                "Custom identity string cannot be empty."
            )

        return (normalized,)

    if isinstance(value, Sequence):
        parts = tuple(
            _coerce_identifier(part)
            for part in value
            if _coerce_identifier(part)
        )

        if not parts:
            raise MissingInteractionIdentityError(
                "Custom identity sequence cannot be empty."
            )

        return parts

    raise MissingInteractionIdentityError(
        "Custom identity function returned an unsupported value."
    )


# -----------------------------------------------------------------------------
# 7.9. Identity-key construction
# -----------------------------------------------------------------------------

def build_interaction_identity_key(
    source: Any,
    *,
    config: DeduplicationConfig = DEFAULT_DEDUPLICATION_CONFIG,
) -> InteractionIdentityKey:
    """
    Build a canonical identity key for an interaction-like object.
    """

    if not isinstance(config, DeduplicationConfig):
        raise InvalidDeduplicationConfigurationError(
            "config must be a DeduplicationConfig instance."
        )

    if config.custom_key is not None:
        custom_value = config.custom_key(source)
        normalized_custom = _normalize_custom_identity_parts(
            custom_value
        )

        if isinstance(
            normalized_custom,
            InteractionIdentityKey,
        ):
            return normalized_custom

        data = _identity_source_data(source)

        orientation = interaction_identity_orientation(
            data.interaction_type,
            configured_orientation=config.orientation,
        )

        return InteractionIdentityKey(
            interaction_type=(
                data.interaction_type
                if config.include_interaction_type
                else SCORE_TYPE_UNKNOWN
            ),
            interaction_family=(
                data.interaction_family
                if config.include_interaction_family
                else SCORE_FAMILY_UNKNOWN
            ),
            pose_id=(
                data.pose_id
                if config.include_pose_id
                else ""
            ),
            model_id=(
                data.model_id
                if config.include_model_id
                else ""
            ),
            orientation=orientation,
            custom_parts=normalized_custom,
            metadata={
                "identity_source": DUPLICATE_REASON_CUSTOM_KEY,
            },
        )

    data = _identity_source_data(source)

    orientation = interaction_identity_orientation(
        data.interaction_type,
        configured_orientation=config.orientation,
    )

    atom_pair: Optional[Tuple[str, str]] = None
    residue_pair: Optional[Tuple[str, str]] = None
    custom_parts: Tuple[str, ...] = ()

    if config.mode == DEDUPLICATION_MODE_NONE:
        custom_parts = (
            data.interaction_id,
        )

    elif config.mode == DEDUPLICATION_MODE_INTERACTION_ID:
        custom_parts = (
            data.interaction_id,
        )

    elif config.mode == DEDUPLICATION_MODE_RESIDUE_PAIR:
        residue_pair = normalize_identity_pair(
            data.residue_pair,
            orientation=orientation,
            field_name="residue_pair",
        )

    elif config.mode == DEDUPLICATION_MODE_ATOM_PAIR:
        atom_pair = normalize_identity_pair(
            data.atom_pair,
            orientation=orientation,
            field_name="atom_pair",
        )

        if (
            atom_pair is None
            and config.allow_residue_fallback
        ):
            residue_pair = normalize_identity_pair(
                data.residue_pair,
                orientation=orientation,
                field_name="residue_pair",
            )

    else:
        if config.include_atom_pair:
            atom_pair = normalize_identity_pair(
                data.atom_pair,
                orientation=orientation,
                field_name="atom_pair",
            )

        if config.include_residue_pair:
            residue_pair = normalize_identity_pair(
                data.residue_pair,
                orientation=orientation,
                field_name="residue_pair",
            )

        if (
            atom_pair is None
            and residue_pair is None
            and config.allow_residue_fallback
        ):
            residue_pair = normalize_identity_pair(
                data.residue_pair,
                orientation=orientation,
                field_name="residue_pair",
            )

    if (
        atom_pair is None
        and residue_pair is None
        and not custom_parts
        and config.allow_identifier_fallback
    ):
        custom_parts = (
            data.interaction_id,
        )

    geometry_key = (
        build_geometry_identity_key(
            data,
            config=config,
        )
        if config.include_geometry
        else ()
    )

    key = InteractionIdentityKey(
        interaction_type=(
            data.interaction_type
            if config.include_interaction_type
            else SCORE_TYPE_UNKNOWN
        ),
        interaction_family=(
            data.interaction_family
            if config.include_interaction_family
            else SCORE_FAMILY_UNKNOWN
        ),
        atom_pair=atom_pair,
        residue_pair=residue_pair,
        pose_id=(
            data.pose_id
            if config.include_pose_id
            else ""
        ),
        model_id=(
            data.model_id
            if config.include_model_id
            else ""
        ),
        geometry_key=geometry_key,
        orientation=orientation,
        custom_parts=custom_parts,
        metadata={
            "interaction_id": data.interaction_id,
            "deduplication_mode": config.mode,
        },
    )

    if key.is_empty and config.require_identity:
        raise MissingInteractionIdentityError(
            f"Could not build identity for interaction "
            f"{data.interaction_id!r}."
        )

    return key


def interaction_identity_string(
    source: Any,
    *,
    config: DeduplicationConfig = DEFAULT_DEDUPLICATION_CONFIG,
) -> str:
    """
    Return the canonical identity string of an interaction.
    """

    return build_interaction_identity_key(
        source,
        config=config,
    ).string


def interactions_share_identity(
    first: Any,
    second: Any,
    *,
    config: DeduplicationConfig = DEFAULT_DEDUPLICATION_CONFIG,
) -> bool:
    """
    Return whether two interactions share the same canonical identity.
    """

    return (
        build_interaction_identity_key(
            first,
            config=config,
        )
        ==
        build_interaction_identity_key(
            second,
            config=config,
        )
    )


# -----------------------------------------------------------------------------
# 7.10. Duplicate quality and representative selection
# -----------------------------------------------------------------------------

_GEOMETRY_QUALITY_RANK: Final[Mapping[str, int]] = MappingProxyType(
    {
        GEOMETRY_IDEAL: 4,
        GEOMETRY_GOOD: 3,
        GEOMETRY_ACCEPTABLE: 2,
        GEOMETRY_POOR: 1,
        GEOMETRY_UNKNOWN: 0,
    }
)


_RECOGNITION_CONFIDENCE_RANK: Final[Mapping[str, int]] = MappingProxyType(
    {
        RECOGNITION_CONFIDENCE_CERTAIN: 4,
        RECOGNITION_CONFIDENCE_HIGH: 3,
        RECOGNITION_CONFIDENCE_MEDIUM: 2,
        RECOGNITION_CONFIDENCE_LOW: 1,
        RECOGNITION_CONFIDENCE_NONE: 0,
    }
)


def interaction_completeness_score(
    source: Any,
) -> int:
    """
    Return a simple completeness score for representative selection.
    """

    if isinstance(source, InteractionScore):
        values = (
            source.interaction_id,
            source.interaction_type,
            source.interaction_family,
            source.atom_pair,
            source.residue_pair,
            source.pose_id,
            source.model_id,
            source.components,
            source.metadata,
        )

    elif isinstance(source, ExtractedInteractionData):
        values = (
            source.interaction_id,
            source.interaction_type,
            source.interaction_family,
            source.atom_pair,
            source.residue_pair,
            source.pose_id,
            source.model_id,
            source.geometry,
            source.metadata,
        )

    elif isinstance(source, InteractionRecognitionResult):
        values = (
            source.interaction_type,
            source.interaction_family,
            source.explicit_type,
            source.explicit_family,
            source.candidates,
            source.reason,
            source.metadata,
        )

    else:
        data = _identity_source_data(source)

        values = (
            data.interaction_id,
            data.interaction_type,
            data.interaction_family,
            data.atom_pair,
            data.residue_pair,
            data.pose_id,
            data.model_id,
            data.geometry,
            data.metadata,
        )

    return sum(
        1
        for value in values
        if value not in (
            None,
            "",
            (),
            {},
            _EMPTY_METADATA,
        )
    )


def interaction_geometry_rank(
    source: Any,
) -> int:
    """
    Return a geometry-quality rank for duplicate selection.
    """

    if isinstance(source, InteractionScore):
        quality = source.geometry_quality

    elif isinstance(source, ExtractedInteractionData):
        quality = source.geometry_quality

    else:
        quality = extract_geometry_quality(source)

    canonical_quality = normalize_geometry_quality(
        quality
    )

    return _GEOMETRY_QUALITY_RANK.get(
        canonical_quality,
        0,
    )


def interaction_recognition_confidence_rank(
    source: Any,
) -> int:
    """
    Return a recognition-confidence rank.
    """

    if isinstance(
        source,
        InteractionRecognitionResult,
    ):
        confidence = source.confidence

    elif isinstance(source, ExtractedInteractionData):
        recognition_metadata = source.metadata.get(
            "recognition",
            {},
        )

        if isinstance(
            recognition_metadata,
            Mapping,
        ):
            confidence = recognition_metadata.get(
                "confidence",
                RECOGNITION_CONFIDENCE_NONE,
            )
        else:
            confidence = RECOGNITION_CONFIDENCE_NONE

    else:
        confidence = RECOGNITION_CONFIDENCE_NONE

    canonical_confidence = normalize_recognition_confidence(
        confidence
    )

    return _RECOGNITION_CONFIDENCE_RANK.get(
        canonical_confidence,
        0,
    )


def interaction_selection_score(
    source: Any,
    *,
    selection_mode: str,
    index: int,
) -> Tuple[Any, ...]:
    """
    Return a deterministic representative-selection key.

    Larger tuples are preferred.
    """

    mode = normalize_duplicate_selection_mode(
        selection_mode
    )

    if isinstance(source, InteractionScore):
        final_score = float(source.final_score)
        accepted = bool(source.accepted)
    else:
        final_score = 0.0
        accepted = bool(
            getattr(source, "accepted", True)
        )

    geometry_rank = interaction_geometry_rank(
        source
    )
    confidence_rank = (
        interaction_recognition_confidence_rank(
            source
        )
    )
    completeness = interaction_completeness_score(
        source
    )

    if mode == DUPLICATE_SELECTION_LAST:
        return (
            index,
        )

    if mode == DUPLICATE_SELECTION_BEST_SCORE:
        return (
            int(accepted),
            final_score,
            geometry_rank,
            confidence_rank,
            completeness,
            -index,
        )

    if mode == DUPLICATE_SELECTION_BEST_GEOMETRY:
        return (
            int(accepted),
            geometry_rank,
            confidence_rank,
            completeness,
            final_score,
            -index,
        )

    if mode == DUPLICATE_SELECTION_BEST_CONFIDENCE:
        return (
            int(accepted),
            confidence_rank,
            geometry_rank,
            completeness,
            final_score,
            -index,
        )

    if mode == DUPLICATE_SELECTION_MOST_COMPLETE:
        return (
            int(accepted),
            completeness,
            confidence_rank,
            geometry_rank,
            final_score,
            -index,
        )

    return (
        -index,
    )


def select_duplicate_representative(
    items: Sequence[Any],
    *,
    selection_mode: str = DUPLICATE_SELECTION_FIRST,
) -> Tuple[int, Any]:
    """
    Select the representative item from one duplicate group.

    Returns
    -------
    tuple
        ``(index, item)`` where index is relative to the supplied sequence.
    """

    if not items:
        raise DuplicateResolutionError(
            "Cannot select a representative from an empty group."
        )

    mode = normalize_duplicate_selection_mode(
        selection_mode
    )

    ranked = [
        (
            interaction_selection_score(
                item,
                selection_mode=mode,
                index=index,
            ),
            index,
            item,
        )
        for index, item in enumerate(items)
    ]

    ranked.sort(
        key=lambda entry: entry[0],
        reverse=True,
    )

    _, selected_index, selected_item = ranked[0]

    return selected_index, selected_item


# -----------------------------------------------------------------------------
# 7.11. DeduplicationRecord
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class DeduplicationRecord:
    """
    Immutable audit record for one input interaction.
    """

    input_index: int
    interaction_id: str
    identity: InteractionIdentityKey

    status: str = DEDUPLICATION_STATUS_UNIQUE
    representative_id: str = ""
    representative_index: Optional[int] = None

    group_size: int = 1
    reason: str = DUPLICATE_REASON_UNKNOWN

    source: Any = field(
        default=None,
        compare=False,
        hash=False,
        repr=False,
    )
    representative: Any = field(
        default=None,
        compare=False,
        hash=False,
        repr=False,
    )

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize the audit record.
        """

        if isinstance(self.input_index, bool):
            raise InteractionIdentityError(
                "DeduplicationRecord.input_index must be an integer."
            )

        try:
            input_index = int(self.input_index)
        except (
            TypeError,
            ValueError,
            OverflowError,
        ) as exc:
            raise InteractionIdentityError(
                "DeduplicationRecord.input_index must be an integer."
            ) from exc

        if input_index < 0:
            raise InteractionIdentityError(
                "DeduplicationRecord.input_index cannot be negative."
            )

        if not isinstance(
            self.identity,
            InteractionIdentityKey,
        ):
            raise InteractionIdentityError(
                "DeduplicationRecord.identity must be an "
                "InteractionIdentityKey."
            )

        if isinstance(self.group_size, bool):
            raise InteractionIdentityError(
                "DeduplicationRecord.group_size must be an integer."
            )

        try:
            group_size = int(self.group_size)
        except (
            TypeError,
            ValueError,
            OverflowError,
        ) as exc:
            raise InteractionIdentityError(
                "DeduplicationRecord.group_size must be an integer."
            ) from exc

        if group_size < 1:
            raise InteractionIdentityError(
                "DeduplicationRecord.group_size must be at least 1."
            )

        representative_index = self.representative_index

        if representative_index is not None:
            if isinstance(representative_index, bool):
                raise InteractionIdentityError(
                    "representative_index must be an integer or None."
                )

            representative_index = int(
                representative_index
            )

        reason = _normalize_scoring_name(
            self.reason
        )

        if reason not in DUPLICATE_REASONS:
            reason = DUPLICATE_REASON_UNKNOWN

        object.__setattr__(
            self,
            "input_index",
            input_index,
        )
        object.__setattr__(
            self,
            "interaction_id",
            _coerce_identifier(
                self.interaction_id
            ),
        )
        object.__setattr__(
            self,
            "status",
            normalize_deduplication_status(
                self.status
            ),
        )
        object.__setattr__(
            self,
            "representative_id",
            _coerce_identifier(
                self.representative_id
            ),
        )
        object.__setattr__(
            self,
            "representative_index",
            representative_index,
        )
        object.__setattr__(
            self,
            "group_size",
            group_size,
        )
        object.__setattr__(
            self,
            "reason",
            reason,
        )
        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(self.metadata),
        )

    @property
    def is_duplicate(self) -> bool:
        """
        Return whether this record represents a removed duplicate.
        """

        return self.status in {
            DEDUPLICATION_STATUS_DUPLICATE,
            DEDUPLICATION_STATUS_REPLACED,
        }

    @property
    def is_representative(self) -> bool:
        """
        Return whether this record is the selected representative.
        """

        return self.status in {
            DEDUPLICATION_STATUS_UNIQUE,
            DEDUPLICATION_STATUS_REPRESENTATIVE,
        }

    def without_references(
        self,
    ) -> "DeduplicationRecord":
        """
        Return a copy without source-object references.
        """

        return replace(
            self,
            source=None,
            representative=None,
        )

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
        include_references: bool = False,
    ) -> Dict[str, Any]:
        """
        Return a mutable dictionary representation.
        """

        result: Dict[str, Any] = {
            "input_index": int(self.input_index),
            "interaction_id": self.interaction_id,
            "identity": self.identity.to_dict(
                include_metadata=include_metadata,
            ),
            "status": self.status,
            "representative_id": self.representative_id,
            "representative_index": self.representative_index,
            "group_size": int(self.group_size),
            "reason": self.reason,
            "is_duplicate": bool(self.is_duplicate),
            "is_representative": bool(
                self.is_representative
            ),
        }

        if include_metadata:
            result["metadata"] = dict(self.metadata)

        if include_references:
            result["source"] = self.source
            result["representative"] = self.representative

        return result

    def __hash__(self) -> int:
        """
        Return a stable hash excluding arbitrary object references.
        """

        return hash(
            (
                self.input_index,
                self.interaction_id,
                self.identity,
                self.status,
                self.representative_id,
                self.representative_index,
                self.group_size,
                self.reason,
            )
        )


# -----------------------------------------------------------------------------
# 7.12. DeduplicationResult
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class DeduplicationResult:
    """
    Immutable result of deduplicating an interaction collection.
    """

    unique: Tuple[Any, ...] = field(
        default_factory=tuple
    )
    duplicates: Tuple[Any, ...] = field(
        default_factory=tuple
    )
    records: Tuple[DeduplicationRecord, ...] = field(
        default_factory=tuple
    )

    input_count: Optional[int] = None
    unique_count: Optional[int] = None
    duplicate_count: Optional[int] = None
    duplicate_group_count: Optional[int] = None

    config: DeduplicationConfig = (
        DEFAULT_DEDUPLICATION_CONFIG
    )

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize deduplication aggregates.
        """

        if not isinstance(
            self.config,
            DeduplicationConfig,
        ):
            raise InteractionIdentityError(
                "DeduplicationResult.config must be a "
                "DeduplicationConfig instance."
            )

        unique = tuple(self.unique)
        duplicates = tuple(self.duplicates)

        normalized_records: List[
            DeduplicationRecord
        ] = []

        for record in self.records:
            if not isinstance(
                record,
                DeduplicationRecord,
            ):
                raise InteractionIdentityError(
                    "DeduplicationResult.records must contain only "
                    "DeduplicationRecord instances."
                )

            normalized_records.append(record)

        input_count = (
            len(unique) + len(duplicates)
            if self.input_count is None
            else int(self.input_count)
        )

        unique_count = (
            len(unique)
            if self.unique_count is None
            else int(self.unique_count)
        )

        duplicate_count = (
            len(duplicates)
            if self.duplicate_count is None
            else int(self.duplicate_count)
        )

        duplicate_group_count = (
            len(
                {
                    record.identity
                    for record in normalized_records
                    if record.group_size > 1
                }
            )
            if self.duplicate_group_count is None
            else int(self.duplicate_group_count)
        )

        if input_count != unique_count + duplicate_count:
            raise InteractionIdentityError(
                "DeduplicationResult counts are inconsistent."
            )

        object.__setattr__(
            self,
            "unique",
            unique,
        )
        object.__setattr__(
            self,
            "duplicates",
            duplicates,
        )
        object.__setattr__(
            self,
            "records",
            tuple(normalized_records),
        )
        object.__setattr__(
            self,
            "input_count",
            input_count,
        )
        object.__setattr__(
            self,
            "unique_count",
            unique_count,
        )
        object.__setattr__(
            self,
            "duplicate_count",
            duplicate_count,
        )
        object.__setattr__(
            self,
            "duplicate_group_count",
            duplicate_group_count,
        )
        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(self.metadata),
        )

    @property
    def removed_fraction(self) -> float:
        """
        Return the fraction of inputs removed as duplicates.
        """

        if self.input_count == 0:
            return 0.0

        return float(
            self.duplicate_count
            / self.input_count
        )

    @property
    def has_duplicates(self) -> bool:
        """Return whether duplicate items were found."""

        return self.duplicate_count > 0

    @property
    def identities(self) -> Tuple[InteractionIdentityKey, ...]:
        """
        Return representative identities in deterministic order.
        """

        return tuple(
            record.identity
            for record in self.records
            if record.is_representative
        )

    def records_for_identity(
        self,
        identity: InteractionIdentityKey,
    ) -> Tuple[DeduplicationRecord, ...]:
        """
        Return all audit records associated with an identity.
        """

        if not isinstance(
            identity,
            InteractionIdentityKey,
        ):
            raise InteractionIdentityError(
                "identity must be an InteractionIdentityKey."
            )

        return tuple(
            record
            for record in self.records
            if record.identity == identity
        )

    def record_for_input_index(
        self,
        input_index: int,
    ) -> Optional[DeduplicationRecord]:
        """
        Return a record by original input index.
        """

        normalized_index = int(input_index)

        for record in self.records:
            if record.input_index == normalized_index:
                return record

        return None

    def without_references(
        self,
    ) -> "DeduplicationResult":
        """
        Return a result without record object references.
        """

        return replace(
            self,
            records=tuple(
                record.without_references()
                for record in self.records
            ),
        )

    def to_dict(
        self,
        *,
        include_items: bool = False,
        include_records: bool = True,
        include_metadata: bool = True,
    ) -> Dict[str, Any]:
        """
        Return a mutable dictionary representation.
        """

        result: Dict[str, Any] = {
            "input_count": int(self.input_count),
            "unique_count": int(self.unique_count),
            "duplicate_count": int(
                self.duplicate_count
            ),
            "duplicate_group_count": int(
                self.duplicate_group_count
            ),
            "removed_fraction": float(
                self.removed_fraction
            ),
            "has_duplicates": bool(
                self.has_duplicates
            ),
            "config": self.config.to_dict(
                include_metadata=include_metadata,
            ),
        }

        if include_items:
            result["unique"] = list(self.unique)
            result["duplicates"] = list(
                self.duplicates
            )

        if include_records:
            result["records"] = [
                record.to_dict(
                    include_metadata=include_metadata,
                    include_references=False,
                )
                for record in self.records
            ]

        if include_metadata:
            result["metadata"] = dict(self.metadata)

        return result

    def __len__(self) -> int:
        """Return the number of retained interactions."""

        return self.unique_count

    def __bool__(self) -> bool:
        """Return whether any unique interaction remains."""

        return self.unique_count > 0


# -----------------------------------------------------------------------------
# 7.13. Duplicate-reason inference
# -----------------------------------------------------------------------------

def infer_duplicate_reason(
    identity: InteractionIdentityKey,
    *,
    config: DeduplicationConfig,
) -> str:
    """
    Infer the reason used to group an identity.
    """

    if config.custom_key is not None:
        return DUPLICATE_REASON_CUSTOM_KEY

    if config.mode == DEDUPLICATION_MODE_INTERACTION_ID:
        return DUPLICATE_REASON_INTERACTION_ID

    if (
        identity.atom_pair is not None
        and identity.residue_pair is not None
        and identity.geometry_key
    ):
        return DUPLICATE_REASON_EXACT_IDENTITY

    if identity.atom_pair is not None:
        return DUPLICATE_REASON_ATOM_PAIR

    if identity.residue_pair is not None:
        return DUPLICATE_REASON_RESIDUE_PAIR

    if identity.geometry_key:
        return DUPLICATE_REASON_GEOMETRY

    if identity.custom_parts:
        return DUPLICATE_REASON_INTERACTION_ID

    return DUPLICATE_REASON_UNKNOWN


# -----------------------------------------------------------------------------
# 7.14. Interaction identifiers for audit records
# -----------------------------------------------------------------------------

def identity_interaction_id(
    source: Any,
    *,
    index: int,
) -> str:
    """
    Return an interaction identifier suitable for audit records.
    """

    if isinstance(source, InteractionScore):
        return source.interaction_id

    if isinstance(source, ExtractedInteractionData):
        return source.interaction_id

    if isinstance(source, InteractionRecognitionResult):
        if source.interaction is not None:
            return extract_interaction_identifier(
                source.interaction,
                index=index + 1,
            )

        return (
            f"{DEFAULT_INTERACTION_ID_PREFIX}_{index + 1}"
        )

    return extract_interaction_identifier(
        source,
        index=index + 1,
    )


# -----------------------------------------------------------------------------
# 7.15. Duplicate-score marking
# -----------------------------------------------------------------------------

def mark_interaction_score_as_duplicate(
    score: InteractionScore,
    *,
    representative_id: str,
    duplicate_reason: str,
    identity: InteractionIdentityKey,
) -> InteractionScore:
    """
    Return an InteractionScore marked as a non-contributing duplicate.
    """

    validate_interaction_score(
        score,
        validate_consistency=False,
    )

    metadata = dict(score.metadata)
    metadata["deduplication"] = {
        "status": DEDUPLICATION_STATUS_DUPLICATE,
        "representative_id": representative_id,
        "reason": duplicate_reason,
        "identity": identity.to_dict(
            include_metadata=False,
        ),
    }

    return create_duplicate_interaction_score(
        interaction_id=score.interaction_id,
        interaction_type=score.interaction_type,
        representative_id=representative_id,
        reason=duplicate_reason,
        source=score.source,
        atom_pair=score.atom_pair,
        residue_pair=score.residue_pair,
        pose_id=score.pose_id,
        model_id=score.model_id,
        interaction=score.interaction,
        metadata=metadata,
    )


# -----------------------------------------------------------------------------
# 7.16. Deduplication execution
# -----------------------------------------------------------------------------

def deduplicate_interactions(
    source: Any,
    *,
    config: DeduplicationConfig = DEFAULT_DEDUPLICATION_CONFIG,
) -> DeduplicationResult:
    """
    Deduplicate a heterogeneous interaction collection.

    Input order is preserved for unique representatives. Duplicate selection
    is deterministic and based on ``selection_mode``.
    """

    if not isinstance(config, DeduplicationConfig):
        raise InvalidDeduplicationConfigurationError(
            "config must be a DeduplicationConfig instance."
        )

    items = tuple(
        iter_interaction_objects(source)
    )

    if config.mode == DEDUPLICATION_MODE_NONE:
        records = tuple(
            DeduplicationRecord(
                input_index=index,
                interaction_id=identity_interaction_id(
                    item,
                    index=index,
                ),
                identity=build_interaction_identity_key(
                    item,
                    config=config,
                ),
                status=DEDUPLICATION_STATUS_UNIQUE,
                representative_id=identity_interaction_id(
                    item,
                    index=index,
                ),
                representative_index=index,
                group_size=1,
                reason=DUPLICATE_REASON_UNKNOWN,
                source=item,
                representative=item,
            )
            for index, item in enumerate(items)
        )

        return DeduplicationResult(
            unique=items,
            duplicates=(),
            records=records,
            config=config,
            metadata={
                "deduplication_disabled": True,
            },
        )

    grouped: Dict[
        InteractionIdentityKey,
        List[Tuple[int, Any]],
    ] = {}

    for index, item in enumerate(items):
        identity = build_interaction_identity_key(
            item,
            config=config,
        )

        grouped.setdefault(
            identity,
            [],
        ).append(
            (
                index,
                item,
            )
        )

    representative_by_identity: Dict[
        InteractionIdentityKey,
        Tuple[int, Any],
    ] = {}

    for identity, indexed_items in grouped.items():
        relative_index, selected = (
            select_duplicate_representative(
                tuple(
                    item
                    for _, item in indexed_items
                ),
                selection_mode=config.selection_mode,
            )
        )

        selected_input_index = indexed_items[
            relative_index
        ][0]

        representative_by_identity[
            identity
        ] = (
            selected_input_index,
            selected,
        )

    unique_indexed: List[Tuple[int, Any]] = []
    duplicate_indexed: List[Tuple[int, Any]] = []
    records: List[DeduplicationRecord] = []

    for identity, indexed_items in grouped.items():
        representative_index, representative = (
            representative_by_identity[identity]
        )

        representative_id = identity_interaction_id(
            representative,
            index=representative_index,
        )

        group_size = len(indexed_items)
        duplicate_reason = infer_duplicate_reason(
            identity,
            config=config,
        )

        for input_index, item in indexed_items:
            interaction_id = identity_interaction_id(
                item,
                index=input_index,
            )

            if input_index == representative_index:
                status = (
                    DEDUPLICATION_STATUS_UNIQUE
                    if group_size == 1
                    else DEDUPLICATION_STATUS_REPRESENTATIVE
                )

                unique_indexed.append(
                    (
                        input_index,
                        item,
                    )
                )

            else:
                status = DEDUPLICATION_STATUS_DUPLICATE

                duplicate_item = item

                if (
                    config.mark_duplicate_scores
                    and isinstance(
                        item,
                        InteractionScore,
                    )
                ):
                    duplicate_item = (
                        mark_interaction_score_as_duplicate(
                            item,
                            representative_id=representative_id,
                            duplicate_reason=duplicate_reason,
                            identity=identity,
                        )
                    )

                duplicate_indexed.append(
                    (
                        input_index,
                        duplicate_item,
                    )
                )

            if config.retain_duplicate_records:
                records.append(
                    DeduplicationRecord(
                        input_index=input_index,
                        interaction_id=interaction_id,
                        identity=identity,
                        status=status,
                        representative_id=representative_id,
                        representative_index=(
                            representative_index
                        ),
                        group_size=group_size,
                        reason=duplicate_reason,
                        source=item,
                        representative=representative,
                        metadata={
                            "selection_mode": (
                                config.selection_mode
                            ),
                        },
                    )
                )

    unique_indexed.sort(
        key=lambda entry: entry[0]
    )
    duplicate_indexed.sort(
        key=lambda entry: entry[0]
    )
    records.sort(
        key=lambda record: record.input_index
    )

    return DeduplicationResult(
        unique=tuple(
            item
            for _, item in unique_indexed
        ),
        duplicates=tuple(
            item
            for _, item in duplicate_indexed
        ),
        records=tuple(records),
        config=config,
        metadata={
            "identity_count": len(grouped),
        },
    )


def deduplicate_interaction_scores(
    scores: Iterable[InteractionScore],
    *,
    config: DeduplicationConfig = DEFAULT_DEDUPLICATION_CONFIG,
) -> DeduplicationResult:
    """
    Deduplicate InteractionScore objects.
    """

    normalized_scores = tuple(
        validate_interaction_score(
            score,
            validate_consistency=False,
        )
        for score in scores
    )

    result = deduplicate_interactions(
        normalized_scores,
        config=config,
    )

    for item in result.unique:
        if not isinstance(item, InteractionScore):
            raise DuplicateResolutionError(
                "Unexpected non-InteractionScore representative."
            )

    for item in result.duplicates:
        if not isinstance(item, InteractionScore):
            raise DuplicateResolutionError(
                "Unexpected non-InteractionScore duplicate."
            )

    return result


def deduplicate_extracted_interactions(
    interactions: Iterable[ExtractedInteractionData],
    *,
    config: DeduplicationConfig = DEFAULT_DEDUPLICATION_CONFIG,
) -> DeduplicationResult:
    """
    Deduplicate canonical extracted interactions.
    """

    normalized = tuple(
        validate_extracted_interaction_data(
            interaction
        )
        for interaction in interactions
    )

    return deduplicate_interactions(
        normalized,
        config=config,
    )


def deduplicate_recognition_results(
    results: Iterable[InteractionRecognitionResult],
    *,
    config: DeduplicationConfig = DEFAULT_DEDUPLICATION_CONFIG,
) -> DeduplicationResult:
    """
    Deduplicate interaction-recognition results.
    """

    normalized = tuple(
        validate_interaction_recognition_result(
            result,
            validate_candidates=False,
        )
        for result in results
    )

    return deduplicate_interactions(
        normalized,
        config=config,
    )


# -----------------------------------------------------------------------------
# 7.17. Grouping without removal
# -----------------------------------------------------------------------------

def group_interactions_by_identity(
    source: Any,
    *,
    config: DeduplicationConfig = DEFAULT_DEDUPLICATION_CONFIG,
) -> Mapping[
    InteractionIdentityKey,
    Tuple[Any, ...],
]:
    """
    Group interactions by canonical identity without removing duplicates.
    """

    grouped: Dict[
        InteractionIdentityKey,
        List[Any],
    ] = {}

    for item in iter_interaction_objects(source):
        identity = build_interaction_identity_key(
            item,
            config=config,
        )

        grouped.setdefault(
            identity,
            [],
        ).append(item)

    ordered = {
        identity: tuple(grouped[identity])
        for identity in sorted(
            grouped,
            key=lambda item: item.string,
        )
    }

    return MappingProxyType(ordered)


def duplicate_interaction_groups(
    source: Any,
    *,
    config: DeduplicationConfig = DEFAULT_DEDUPLICATION_CONFIG,
) -> Mapping[
    InteractionIdentityKey,
    Tuple[Any, ...],
]:
    """
    Return only groups containing more than one interaction.
    """

    grouped = group_interactions_by_identity(
        source,
        config=config,
    )

    return MappingProxyType(
        {
            identity: items
            for identity, items in grouped.items()
            if len(items) > 1
        }
    )


def count_duplicate_groups(
    source: Any,
    *,
    config: DeduplicationConfig = DEFAULT_DEDUPLICATION_CONFIG,
) -> int:
    """
    Return the number of duplicate identity groups.
    """

    return len(
        duplicate_interaction_groups(
            source,
            config=config,
        )
    )


# -----------------------------------------------------------------------------
# 7.18. Deduplication of pose results
# -----------------------------------------------------------------------------

def deduplicate_pose_score(
    pose: PoseScore,
    *,
    config: DeduplicationConfig = DEFAULT_DEDUPLICATION_CONFIG,
    rebuild_residues: bool = True,
) -> Tuple[PoseScore, DeduplicationResult]:
    """
    Deduplicate interactions stored in a PoseScore.

    The pose score is rebuilt from retained interactions so no duplicate
    contribution remains in the aggregate score.
    """

    validate_pose_score(
        pose,
        validate_consistency=False,
    )

    result = deduplicate_interaction_scores(
        pose.interactions,
        config=config,
    )

    unique_interactions = tuple(
        item
        for item in result.unique
        if isinstance(item, InteractionScore)
    )

    residues = (
        build_residue_scores(
            unique_interactions,
            pose_id=pose.pose_id,
            model_id=pose.model_id,
            include_unassigned=False,
        )
        if rebuild_residues
        else pose.residues
    )

    metadata = dict(pose.metadata)
    metadata["deduplication"] = {
        "input_count": result.input_count,
        "unique_count": result.unique_count,
        "duplicate_count": result.duplicate_count,
        "duplicate_group_count": (
            result.duplicate_group_count
        ),
        "mode": config.mode,
    }

    rebuilt_pose = create_pose_score(
        pose_id=pose.pose_id,
        interactions=unique_interactions,
        residues=residues,
        model_id=pose.model_id,
        ligand_id=pose.ligand_id,
        pose_index=pose.pose_index,
        docking_affinity=pose.docking_affinity,
        docking_affinity_unit=(
            pose.docking_affinity_unit
        ),
        penalty_score=pose.penalty_score,
        bonus_score=pose.bonus_score,
        diversity_bonus=pose.diversity_bonus,
        normalized_score=pose.normalized_score,
        ranking_score=None,
        status=pose.status,
        accepted=pose.accepted,
        rejection_reason=pose.rejection_reason,
        metadata=metadata,
    )

    return rebuilt_pose, result


def deduplicate_multipose_result(
    result: MultiPoseScoreResult,
    *,
    config: DeduplicationConfig = DEFAULT_DEDUPLICATION_CONFIG,
    rebuild_residues: bool = True,
) -> Tuple[
    MultiPoseScoreResult,
    Mapping[str, DeduplicationResult],
]:
    """
    Deduplicate every pose in a multipose result.
    """

    validate_multipose_score_result(
        result,
        validate_consistency=False,
    )

    rebuilt_poses: List[PoseScore] = []
    pose_results: Dict[str, DeduplicationResult] = {}

    for pose in result.poses:
        rebuilt_pose, deduplication_result = (
            deduplicate_pose_score(
                pose,
                config=config,
                rebuild_residues=rebuild_residues,
            )
        )

        rebuilt_poses.append(rebuilt_pose)
        pose_results[pose.pose_id] = (
            deduplication_result
        )

    metadata = dict(result.metadata)
    metadata["deduplication"] = {
        "mode": config.mode,
        "pose_count": len(rebuilt_poses),
        "total_duplicates": sum(
            pose_result.duplicate_count
            for pose_result in pose_results.values()
        ),
    }

    rebuilt_result = create_multipose_score_result(
        result_id=result.result_id,
        poses=rebuilt_poses,
        score_direction=result.score_direction,
        status=result.status,
        ligand_id=result.ligand_id,
        model_id=result.model_id,
        consensus_pose_id=(
            result.consensus_pose_id
        ),
        consensus_score=result.consensus_score,
        explanations=result.explanations,
        metadata=metadata,
    )

    return (
        rebuilt_result,
        MappingProxyType(pose_results),
    )


# -----------------------------------------------------------------------------
# 7.19. Validation
# -----------------------------------------------------------------------------

def validate_interaction_identity_key(
    identity: InteractionIdentityKey,
    *,
    allow_empty: bool = True,
) -> InteractionIdentityKey:
    """
    Validate and return an interaction identity.
    """

    if not isinstance(
        identity,
        InteractionIdentityKey,
    ):
        raise InteractionIdentityError(
            "Expected an InteractionIdentityKey instance."
        )

    if identity.is_empty and not allow_empty:
        raise MissingInteractionIdentityError(
            "Interaction identity is empty."
        )

    return identity


def validate_deduplication_record(
    record: DeduplicationRecord,
) -> DeduplicationRecord:
    """
    Validate and return a deduplication record.
    """

    if not isinstance(
        record,
        DeduplicationRecord,
    ):
        raise InteractionIdentityError(
            "Expected a DeduplicationRecord instance."
        )

    validate_interaction_identity_key(
        record.identity,
        allow_empty=True,
    )

    return record


def validate_deduplication_result(
    result: DeduplicationResult,
    *,
    validate_records: bool = True,
) -> DeduplicationResult:
    """
    Validate and return a deduplication result.
    """

    if not isinstance(
        result,
        DeduplicationResult,
    ):
        raise InteractionIdentityError(
            "Expected a DeduplicationResult instance."
        )

    if (
        result.input_count
        != result.unique_count
        + result.duplicate_count
    ):
        raise InteractionIdentityError(
            "Deduplication counts are inconsistent."
        )

    if validate_records:
        for record in result.records:
            validate_deduplication_record(record)

        if (
            result.records
            and len(result.records)
            != result.input_count
        ):
            raise InteractionIdentityError(
                "The number of deduplication records does not match "
                "the input count."
            )

    return result


# -----------------------------------------------------------------------------
# 7.20. Explainability
# -----------------------------------------------------------------------------

def explain_deduplication_result(
    result: DeduplicationResult,
    *,
    include_groups: bool = True,
) -> ScoreExplanation:
    """
    Create a structured explanation for a deduplication result.
    """

    validate_deduplication_result(
        result,
        validate_records=False,
    )

    if result.duplicate_count > 0:
        severity = EXPLANATION_SEVERITY_WARNING
    else:
        severity = EXPLANATION_SEVERITY_SUCCESS

    message = (
        f"Deduplication evaluated {result.input_count} interaction(s), "
        f"retained {result.unique_count}, and removed "
        f"{result.duplicate_count} duplicate(s) across "
        f"{result.duplicate_group_count} duplicate group(s)."
    )

    children: List[ScoreExplanation] = []

    if include_groups:
        grouped_records: Dict[
            InteractionIdentityKey,
            List[DeduplicationRecord],
        ] = {}

        for record in result.records:
            if record.group_size <= 1:
                continue

            grouped_records.setdefault(
                record.identity,
                [],
            ).append(record)

        for group_index, identity in enumerate(
            sorted(
                grouped_records,
                key=lambda item: item.string,
            ),
            start=1,
        ):
            records = grouped_records[identity]

            representative = next(
                (
                    record
                    for record in records
                    if record.is_representative
                ),
                records[0],
            )

            children.append(
                ScoreExplanation(
                    explanation_id=(
                        f"deduplication:group:{group_index}"
                    ),
                    title=(
                        f"Duplicate group {group_index}"
                    ),
                    message=(
                        f"{len(records)} interaction(s) shared identity "
                        f"'{identity.string}'. Interaction "
                        f"'{representative.representative_id}' was "
                        "retained as representative."
                    ),
                    scope=EXPLANATION_SCOPE_INTERACTION,
                    severity=EXPLANATION_SEVERITY_WARNING,
                    level=EXPLANATION_LEVEL_DETAILED,
                    value=float(len(records)),
                    entity_id=(
                        representative.representative_id
                    ),
                    interaction_type=(
                        identity.interaction_type
                    ),
                    tags=(
                        "deduplication",
                        "duplicate_group",
                        representative.reason,
                    ),
                    metadata={
                        "identity": identity.to_dict(
                            include_metadata=False,
                        ),
                    },
                )
            )

    return ScoreExplanation(
        explanation_id="deduplication:summary",
        title="Interaction deduplication",
        message=message,
        scope=EXPLANATION_SCOPE_GENERAL,
        severity=severity,
        level=EXPLANATION_LEVEL_STANDARD,
        value=float(result.unique_count),
        reference_value=float(result.input_count),
        tags=(
            "deduplication",
            result.config.mode,
        ),
        children=tuple(children),
        metadata={
            "duplicate_count": result.duplicate_count,
            "duplicate_group_count": (
                result.duplicate_group_count
            ),
            "removed_fraction": result.removed_fraction,
        },
    )


# -----------------------------------------------------------------------------
# 7.21. Section consistency validation
# -----------------------------------------------------------------------------

def _validate_section_7_identity_and_deduplication() -> None:
    """
    Validate identity and deduplication utilities at module import.
    """

    first = ExtractedInteractionData(
        interaction_id="hbond_1",
        interaction_type="hydrogen_bond",
        interaction_family="hydrogen_bond",
        atom_pair=(
            "A:10:N",
            "L:1:O",
        ),
        residue_pair=(
            "A:10:LYS",
            "L:1:LIG",
        ),
        pose_id="pose_1",
        model_id="model_1",
        distance=2.8,
        angle=165.0,
    )

    second = ExtractedInteractionData(
        interaction_id="hbond_2",
        interaction_type="hbond",
        interaction_family="hydrogen_bond",
        atom_pair=(
            "A:10:N",
            "L:1:O",
        ),
        residue_pair=(
            "A:10:LYS",
            "L:1:LIG",
        ),
        pose_id="pose_1",
        model_id="model_1",
        distance=2.82,
        angle=164.0,
    )

    third = ExtractedInteractionData(
        interaction_id="hbond_3",
        interaction_type="hydrogen_bond",
        interaction_family="hydrogen_bond",
        atom_pair=(
            "A:11:N",
            "L:1:O",
        ),
        residue_pair=(
            "A:11:ARG",
            "L:1:LIG",
        ),
        pose_id="pose_1",
        model_id="model_1",
        distance=2.9,
        angle=160.0,
    )

    identity_config = DeduplicationConfig(
        mode=DEDUPLICATION_MODE_ATOM_PAIR,
        include_pose_id=True,
        include_model_id=True,
        include_geometry=False,
        selection_mode=DUPLICATE_SELECTION_FIRST,
    )

    first_identity = build_interaction_identity_key(
        first,
        config=identity_config,
    )
    second_identity = build_interaction_identity_key(
        second,
        config=identity_config,
    )
    third_identity = build_interaction_identity_key(
        third,
        config=identity_config,
    )

    if first_identity != second_identity:
        raise RuntimeError(
            "Equivalent interaction identity validation failed."
        )

    if first_identity == third_identity:
        raise RuntimeError(
            "Distinct interaction identity validation failed."
        )

    result = deduplicate_extracted_interactions(
        (
            first,
            second,
            third,
        ),
        config=identity_config,
    )

    if result.input_count != 3:
        raise RuntimeError(
            "Deduplication input-count validation failed."
        )

    if result.unique_count != 2:
        raise RuntimeError(
            "Deduplication unique-count validation failed."
        )

    if result.duplicate_count != 1:
        raise RuntimeError(
            "Deduplication duplicate-count validation failed."
        )

    if result.duplicate_group_count != 1:
        raise RuntimeError(
            "Duplicate-group count validation failed."
        )

    explanation = explain_deduplication_result(
        result
    )

    if explanation.scope != EXPLANATION_SCOPE_GENERAL:
        raise RuntimeError(
            "Deduplication explanation validation failed."
        )

    validate_deduplication_result(result)


_validate_section_7_identity_and_deduplication()


