    normalized = _normalize_scoring_name(value)

    if not normalized:
        return default

    if normalized in ADJUSTMENT_OPERATIONS:
        return normalized

    return _ADJUSTMENT_OPERATION_ALIASES.get(
        normalized,
        default,
    )


