# -----------------------------------------------------------------------------
# 12.3. Exceptions
# -----------------------------------------------------------------------------

class ScoreAdjustmentError(ScoringError):
    """
    Base exception for penalties and score corrections.
    """


class InvalidScoreAdjustmentError(ScoreAdjustmentError):
    """
    Raised when an adjustment is invalid.
    """


class ScoreAdjustmentExecutionError(ScoreAdjustmentError):
    """
    Raised when an adjustment callback fails.
    """


class DuplicateScoreAdjustmentError(ScoreAdjustmentError):
    """
    Raised when the same adjustment is applied more than once.
    """


class ScoreLimitError(ScoreAdjustmentError):
    """
    Raised when a score violates configured limits.
    """


# -----------------------------------------------------------------------------
# 12.4. Adjustment callback protocol
# -----------------------------------------------------------------------------

@runtime_checkable
class ScoreAdjustmentCallable(Protocol):
    """
    Protocol implemented by penalty and correction callbacks.
    """

    def __call__(
        self,
        score: InteractionScore,
        context: "ScoreAdjustmentContext",
    ) -> Any:
        """
        Evaluate one InteractionScore.
        """


# -----------------------------------------------------------------------------
# 12.5. ScoreAdjustmentContext
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class ScoreAdjustmentContext:
    """
    Immutable context supplied to adjustment rules.
    """

    interaction_id: str
    interaction_type: str
    interaction_family: str

    raw_score: float
    penalty_score: float
    bonus_score: float
    final_score: float

    strength: str = STRENGTH_UNKNOWN
    classification: str = CLASSIFICATION_UNKNOWN
    geometry_quality: str = GEOMETRY_UNKNOWN
    polarity: str = POLARITY_UNKNOWN

    distance: Optional[float] = None
    angle: Optional[float] = None
    offset: Optional[float] = None
    planarity: Optional[float] = None
    overlap: Optional[float] = None

    duplicate_count: int = 1
    missing_geometry_metric_count: int = 0

    interaction: Any = field(
        default=None,
        compare=False,
        hash=False,
        repr=False,
    )

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize adjustment-context fields.
        """

        numeric_fields = (
            "raw_score",
            "penalty_score",
            "bonus_score",
            "final_score",
        )

        for field_name in numeric_fields:
            object.__setattr__(
                self,
                field_name,
                float(
                    _coerce_finite_score_value(
                        getattr(self, field_name),
                        name=f"ScoreAdjustmentContext.{field_name}",
                    )
                ),
            )

        for field_name in (
            "distance",
            "angle",
            "offset",
            "planarity",
            "overlap",
        ):
            value = getattr(self, field_name)

            object.__setattr__(
                self,
                field_name,
                (
                    None
                    if value is None
                    else float(
                        _coerce_finite_score_value(
                            value,
                            name=(
                                "ScoreAdjustmentContext."
                                f"{field_name}"
                            ),
                        )
                    )
                ),
            )

        object.__setattr__(
            self,
            "interaction_id",
            _coerce_identifier(
                self.interaction_id
            ),
        )
        object.__setattr__(
            self,
            "interaction_type",
            normalize_interaction_type(
                self.interaction_type,
                preserve_unknown=True,
            ),
        )
        object.__setattr__(
            self,
            "interaction_family",
            canonical_interaction_family(
                self.interaction_family
                or self.interaction_type
            ),
        )
        object.__setattr__(
            self,
            "strength",
            normalize_interaction_strength(
                self.strength
            ),
        )
        object.__setattr__(
            self,
            "classification",
            normalize_interaction_classification(
                self.classification
            ),
        )
        object.__setattr__(
            self,
            "geometry_quality",
            normalize_geometry_quality(
                self.geometry_quality
            ),
        )
        object.__setattr__(
            self,
            "polarity",
            normalize_score_polarity(
                self.polarity
            ),
        )
        object.__setattr__(
            self,
            "duplicate_count",
            max(
                1,
                int(self.duplicate_count),
            ),
        )
        object.__setattr__(
            self,
            "missing_geometry_metric_count",
            max(
                0,
                int(
                    self.missing_geometry_metric_count
                ),
            ),
        )
        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(
                self.metadata
            ),
        )

    @classmethod
    def from_interaction_score(
        cls,
        score: InteractionScore,
    ) -> "ScoreAdjustmentContext":
        """
        Build an adjustment context from an InteractionScore.
        """

        validate_interaction_score(
            score,
            validate_consistency=False,
        )

        interaction = score.interaction
        metadata = dict(score.metadata)

        duplicate_count = int(
            metadata.get(
                "duplicate_count",
                1,
            )
        )

        geometry_resolution = metadata.get(
            "geometry_resolution",
            {},
        )

        missing_geometry_metric_count = 0

        if isinstance(
            geometry_resolution,
            Mapping,
        ):
            evaluations = geometry_resolution.get(
                "evaluations",
                (),
            )

            if isinstance(
                evaluations,
                Sequence,
            ):
                missing_geometry_metric_count = sum(
                    1
                    for evaluation in evaluations
                    if (
                        isinstance(
                            evaluation,
                            Mapping,
                        )
                        and evaluation.get(
                            "score"
                        ) is None
                    )
                )

        return cls(
            interaction_id=score.interaction_id,
            interaction_type=score.interaction_type,
            interaction_family=score.interaction_family,
            raw_score=score.raw_score,
            penalty_score=score.penalty_score,
            bonus_score=score.bonus_score,
            final_score=score.final_score,
            strength=score.strength,
            classification=score.classification,
            geometry_quality=score.geometry_quality,
            polarity=score.polarity,
            distance=extract_interaction_distance(
                interaction
            ),
            angle=extract_interaction_angle(
                interaction
            ),
            offset=extract_interaction_offset(
                interaction
            ),
            planarity=extract_interaction_planarity(
                interaction
            ),
            overlap=extract_interaction_overlap(
                interaction
            ),
            duplicate_count=duplicate_count,
            missing_geometry_metric_count=(
                missing_geometry_metric_count
            ),
            interaction=interaction,
            metadata=metadata,
        )


# -----------------------------------------------------------------------------
# 12.6. ScoreAdjustment
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class ScoreAdjustment:
    """
    Immutable score adjustment.

    Operations are applied to the current score in rule order.
    """

    adjustment_id: str
    kind: str
    category: str
    operation: str
    value: float

    source: str = ADJUSTMENT_SOURCE_UNKNOWN
    status: str = ADJUSTMENT_STATUS_APPLIED
    stage: str = ADJUSTMENT_STAGE_FINAL

    reason: str = ""
    rule_name: str = ""

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize and validate the adjustment.
        """

        adjustment_id = _coerce_identifier(
            self.adjustment_id
        )

        if not adjustment_id:
            raise InvalidScoreAdjustmentError(
                "ScoreAdjustment.adjustment_id cannot be empty."
            )

        kind = normalize_adjustment_kind(
            self.kind
        )
        operation = normalize_adjustment_operation(
            self.operation
        )

        if kind == ADJUSTMENT_KIND_PENALTY:
            category = normalize_penalty_category(
                self.category
            )
        elif kind in {
            ADJUSTMENT_KIND_CORRECTION,
            ADJUSTMENT_KIND_CAP,
            ADJUSTMENT_KIND_FLOOR,
            ADJUSTMENT_KIND_REPLACEMENT,
        }:
            category = normalize_correction_category(
                self.category
            )
        else:
            category = _normalize_scoring_name(
                self.category
            ) or CORRECTION_CATEGORY_CUSTOM

        value = float(
            _coerce_finite_score_value(
                self.value,
                name="ScoreAdjustment.value",
            )
        )

        if (
            operation
            in {
                ADJUSTMENT_OPERATION_SUBTRACT,
                ADJUSTMENT_OPERATION_ADD,
            }
            and kind
            in {
                ADJUSTMENT_KIND_PENALTY,
                ADJUSTMENT_KIND_BONUS,
            }
            and value < 0.0
        ):
            raise InvalidScoreAdjustmentError(
                "Penalty and bonus magnitudes cannot be negative."
            )

        if (
            operation
            == ADJUSTMENT_OPERATION_MULTIPLY
            and value < 0.0
        ):
            raise InvalidScoreAdjustmentError(
                "Correction multipliers cannot be negative."
            )

        object.__setattr__(
            self,
            "adjustment_id",
            adjustment_id,
        )
        object.__setattr__(
            self,
            "kind",
            kind,
        )
        object.__setattr__(
            self,
            "category",
            category,
        )
        object.__setattr__(
            self,
            "operation",
            operation,
        )
        object.__setattr__(
            self,
            "value",
            value,
        )
        object.__setattr__(
            self,
            "source",
            normalize_adjustment_source(
                self.source
            ),
        )
        object.__setattr__(
            self,
            "status",
            normalize_adjustment_status(
                self.status
            ),
        )
        object.__setattr__(
            self,
            "stage",
            normalize_adjustment_stage(
                self.stage
            ),
        )
        object.__setattr__(
            self,
            "reason",
            _coerce_optional_text(
                self.reason
            ),
        )
        object.__setattr__(
            self,
            "rule_name",
            _coerce_identifier(
                self.rule_name
            ),
        )
        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(
                self.metadata
            ),
        )

    @property
    def neutral(self) -> bool:
        """
        Return whether the adjustment leaves the score unchanged.
        """

        if self.operation in {
            ADJUSTMENT_OPERATION_ADD,
            ADJUSTMENT_OPERATION_SUBTRACT,
        }:
            return (
                abs(self.value)
                <= SCORE_COMPARISON_TOLERANCE
            )

        if self.operation == ADJUSTMENT_OPERATION_MULTIPLY:
            return (
                abs(
                    self.value - 1.0
                )
                <= SCORE_COMPARISON_TOLERANCE
            )

        return False

    def apply(
        self,
        score: Number,
    ) -> float:
        """
        Apply the adjustment to a score.
        """

        numeric_score = float(
            _coerce_finite_score_value(
                score,
                name="adjustment input score",
            )
        )

        if self.operation == ADJUSTMENT_OPERATION_SUBTRACT:
            return float(
                numeric_score - self.value
            )

        if self.operation == ADJUSTMENT_OPERATION_ADD:
            return float(
                numeric_score + self.value
            )

        if self.operation == ADJUSTMENT_OPERATION_MULTIPLY:
            return float(
                numeric_score * self.value
            )

        if self.operation == ADJUSTMENT_OPERATION_MINIMUM:
            return float(
                min(
                    numeric_score,
                    self.value,
                )
            )

        if self.operation == ADJUSTMENT_OPERATION_MAXIMUM:
            return float(
                max(
                    numeric_score,
                    self.value,
                )
            )

        return float(self.value)

    def delta(
        self,
        score: Number,
    ) -> float:
        """
        Return the score change produced by the adjustment.
        """

        numeric_score = float(
            _coerce_finite_score_value(
                score,
                name="adjustment input score",
            )
        )

        return float(
            self.apply(numeric_score)
            - numeric_score
        )

    def to_component(
        self,
    ) -> ScoreComponent:
        """
        Convert the adjustment to a ScoreComponent.
        """

        if self.kind == ADJUSTMENT_KIND_PENALTY:
            return make_penalty_component(
                value=abs(self.value),
                name=self.category,
                source=self.source,
                description=self.reason,
                metadata={
                    "adjustment_id": self.adjustment_id,
                    "operation": self.operation,
                    "rule_name": self.rule_name,
                    "stage": self.stage,
                },
            )

        if self.kind == ADJUSTMENT_KIND_BONUS:
            return make_bonus_component(
                value=abs(self.value),
                name=self.category,
                source=self.source,
                description=self.reason,
                metadata={
                    "adjustment_id": self.adjustment_id,
                    "operation": self.operation,
                    "rule_name": self.rule_name,
                    "stage": self.stage,
                },
            )

        return ScoreComponent(
            component_type=f"score_{self.kind}",
            name=self.category,
            value=self.value,
            operation=self.operation,
            source=self.source,
            description=self.reason,
            metadata={
                "adjustment_id": self.adjustment_id,
                "rule_name": self.rule_name,
                "stage": self.stage,
            },
        )

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
    ) -> Dict[str, Any]:
        """
        Return a mutable dictionary representation.
        """

        result: Dict[str, Any] = {
            "adjustment_id": self.adjustment_id,
            "kind": self.kind,
            "category": self.category,
            "operation": self.operation,
            "value": float(self.value),
            "source": self.source,
            "status": self.status,
            "stage": self.stage,
            "reason": self.reason,
            "rule_name": self.rule_name,
            "neutral": bool(self.neutral),
        }

        if include_metadata:
            result["metadata"] = dict(
                self.metadata
            )

        return result


# -----------------------------------------------------------------------------
# 12.7. ScoreAdjustmentRule
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class ScoreAdjustmentRule:
    """
    Immutable rule that produces penalties or corrections.
    """

    name: str

    evaluator: ScoreAdjustmentCallable = field(
        compare=False,
        hash=False,
        repr=False,
    )

    interaction_families: FrozenSet[str] = field(
        default_factory=frozenset
    )
    interaction_types: FrozenSet[str] = field(
        default_factory=frozenset
    )

    priority: int = 0
    stage: str = ADJUSTMENT_STAGE_FINAL

    enabled: bool = True
    stop_after_match: bool = False

    description: str = ""

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize and validate the adjustment rule.
        """

        name = _coerce_identifier(
            self.name
        )

        if not name:
            raise InvalidScoreAdjustmentError(
                "ScoreAdjustmentRule.name cannot be empty."
            )

        if not callable(self.evaluator):
            raise InvalidScoreAdjustmentError(
                "ScoreAdjustmentRule.evaluator must be callable."
            )

        families = frozenset(
            canonical_interaction_family(
                family
            )
            for family in self.interaction_families
        )

        interaction_types = frozenset(
            normalize_interaction_type(
                interaction_type,
                preserve_unknown=True,
            )
            for interaction_type
            in self.interaction_types
        )

        object.__setattr__(
            self,
            "name",
            name,
        )
        object.__setattr__(
            self,
            "interaction_families",
            families,
        )
        object.__setattr__(
            self,
            "interaction_types",
            interaction_types,
        )
        object.__setattr__(
            self,
            "priority",
            int(self.priority),
        )
        object.__setattr__(
            self,
            "stage",
            normalize_adjustment_stage(
                self.stage
            ),
        )
        object.__setattr__(
            self,
            "enabled",
            bool(self.enabled),
        )
        object.__setattr__(
            self,
            "stop_after_match",
            bool(self.stop_after_match),
        )
        object.__setattr__(
            self,
            "description",
            _coerce_optional_text(
                self.description
            ),
        )
        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(
                self.metadata
            ),
        )

    def supports(
        self,
        context: ScoreAdjustmentContext,
    ) -> bool:
        """
        Return whether the rule supports the supplied context.
        """

        if not self.enabled:
            return False

        if (
            self.interaction_families
            and context.interaction_family
            not in self.interaction_families
        ):
            return False

        if (
            self.interaction_types
            and context.interaction_type
            not in self.interaction_types
        ):
            return False

        return True

    def evaluate(
        self,
        score: InteractionScore,
        context: ScoreAdjustmentContext,
    ) -> Tuple[ScoreAdjustment, ...]:
        """
        Evaluate the rule and normalize its results.
        """

        if not self.supports(context):
            return ()

        try:
            raw_result = self.evaluator(
                score,
                context,
            )
        except Exception as exc:
            raise ScoreAdjustmentExecutionError(
                f"Score adjustment rule {self.name!r} failed."
            ) from exc

        return coerce_score_adjustments(
            raw_result,
            rule=self,
        )


# -----------------------------------------------------------------------------
# 12.8. ScoreAdjustmentProfile
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class ScoreAdjustmentProfile:
    """
    Immutable penalty and correction configuration.
    """

    rules: Tuple[ScoreAdjustmentRule, ...] = field(
        default_factory=tuple
    )

    poor_geometry_penalty: float = (
        DEFAULT_POOR_GEOMETRY_PENALTY
    )
    unknown_geometry_penalty: float = (
        DEFAULT_UNKNOWN_GEOMETRY_PENALTY
    )
    unknown_strength_penalty: float = (
        DEFAULT_UNKNOWN_STRENGTH_PENALTY
    )
    unknown_classification_penalty: float = (
        DEFAULT_UNKNOWN_CLASSIFICATION_PENALTY
    )
    incomplete_geometry_penalty: float = (
        DEFAULT_INCOMPLETE_GEOMETRY_PENALTY
    )

    severe_clash_penalty: float = (
        DEFAULT_SEVERE_CLASH_PENALTY
    )
    moderate_clash_penalty: float = (
        DEFAULT_MODERATE_CLASH_PENALTY
    )

    duplicate_score_retention: float = (
        DEFAULT_DUPLICATE_SCORE_RETENTION
    )

    maximum_absolute_score: Optional[float] = (
        DEFAULT_MAXIMUM_ABSOLUTE_INTERACTION_SCORE
    )

    prevent_duplicate_adjustments: bool = True
    strict: bool = False

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize and validate the profile.
        """

        normalized_rules: List[
            ScoreAdjustmentRule
        ] = []

        for rule in self.rules:
            if not isinstance(
                rule,
                ScoreAdjustmentRule,
            ):
                raise InvalidScoreAdjustmentError(
                    "ScoreAdjustmentProfile.rules must contain only "
                    "ScoreAdjustmentRule instances."
                )

            normalized_rules.append(rule)

        normalized_rules.sort(
            key=lambda rule: (
                _adjustment_stage_order(
                    rule.stage
                ),
                -rule.priority,
                rule.name,
            )
        )

        nonnegative_fields = (
            "poor_geometry_penalty",
            "unknown_geometry_penalty",
            "unknown_strength_penalty",
            "unknown_classification_penalty",
            "incomplete_geometry_penalty",
            "severe_clash_penalty",
            "moderate_clash_penalty",
        )

        for field_name in nonnegative_fields:
            value = float(
                _coerce_finite_score_value(
                    getattr(self, field_name),
                    name=(
                        "ScoreAdjustmentProfile."
                        f"{field_name}"
                    ),
                )
            )

            if value < 0.0:
                raise InvalidScoreAdjustmentError(
                    f"{field_name} cannot be negative."
                )

            object.__setattr__(
                self,
                field_name,
                value,
            )

        duplicate_retention = float(
            _coerce_finite_score_value(
                self.duplicate_score_retention,
                name="duplicate_score_retention",
            )
        )

        if not 0.0 <= duplicate_retention <= 1.0:
            raise InvalidScoreAdjustmentError(
                "duplicate_score_retention must be between 0.0 and 1.0."
            )

        maximum_absolute_score = (
            None
            if self.maximum_absolute_score is None
            else float(
                _coerce_finite_score_value(
                    self.maximum_absolute_score,
                    name="maximum_absolute_score",
                )
            )
        )

        if (
            maximum_absolute_score is not None
            and maximum_absolute_score <= 0.0
        ):
            raise InvalidScoreAdjustmentError(
                "maximum_absolute_score must be positive or None."
            )

        object.__setattr__(
            self,
            "rules",
            tuple(normalized_rules),
        )
        object.__setattr__(
            self,
            "duplicate_score_retention",
            duplicate_retention,
        )
        object.__setattr__(
            self,
            "maximum_absolute_score",
            maximum_absolute_score,
        )
        object.__setattr__(
            self,
            "prevent_duplicate_adjustments",
            bool(
                self.prevent_duplicate_adjustments
            ),
        )
        object.__setattr__(
            self,
            "strict",
            bool(self.strict),
        )
        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(
                self.metadata
            ),
        )

    def with_updates(
        self,
        **changes: Any,
    ) -> "ScoreAdjustmentProfile":
        """
        Return a validated profile copy.
        """

        return replace(
            self,
            **changes,
        )

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
    ) -> Dict[str, Any]:
        """
        Return a mutable dictionary representation.
        """

        result: Dict[str, Any] = {
            "rules": [
                {
                    "name": rule.name,
                    "interaction_families": sorted(
                        rule.interaction_families
                    ),
                    "interaction_types": sorted(
                        rule.interaction_types
                    ),
                    "priority": rule.priority,
                    "stage": rule.stage,
                    "enabled": rule.enabled,
                    "stop_after_match": (
                        rule.stop_after_match
                    ),
                    "description": rule.description,
                    "metadata": (
                        dict(rule.metadata)
                        if include_metadata
                        else {}
                    ),
                }
                for rule in self.rules
            ],
            "poor_geometry_penalty": float(
                self.poor_geometry_penalty
            ),
            "unknown_geometry_penalty": float(
                self.unknown_geometry_penalty
            ),
            "unknown_strength_penalty": float(
                self.unknown_strength_penalty
            ),
            "unknown_classification_penalty": float(
                self.unknown_classification_penalty
            ),
            "incomplete_geometry_penalty": float(
                self.incomplete_geometry_penalty
            ),
            "severe_clash_penalty": float(
                self.severe_clash_penalty
            ),
            "moderate_clash_penalty": float(
                self.moderate_clash_penalty
            ),
            "duplicate_score_retention": float(
                self.duplicate_score_retention
            ),
            "maximum_absolute_score": (
                self.maximum_absolute_score
            ),
            "prevent_duplicate_adjustments": bool(
                self.prevent_duplicate_adjustments
            ),
            "strict": bool(self.strict),
        }

        if include_metadata:
            result["metadata"] = dict(
                self.metadata
            )

        return result


def _adjustment_stage_order(
    stage: str,
) -> int:
    """
    Return deterministic stage order.
    """

    normalized = normalize_adjustment_stage(
        stage
    )

    return {
        ADJUSTMENT_STAGE_PRE_FINAL: 0,
        ADJUSTMENT_STAGE_FINAL: 1,
        ADJUSTMENT_STAGE_POST_FINAL: 2,
    }[normalized]


# -----------------------------------------------------------------------------
# 12.9. Adjustment coercion
# -----------------------------------------------------------------------------

def coerce_score_adjustment(
    value: Any,
    *,
    rule: Optional[ScoreAdjustmentRule] = None,
    index: int = 0,
) -> ScoreAdjustment:
    """
    Convert a callback result item into ScoreAdjustment.
    """

    if isinstance(value, ScoreAdjustment):
        return value

    rule_name = (
        ""
        if rule is None
        else rule.name
    )
    default_stage = (
        ADJUSTMENT_STAGE_FINAL
        if rule is None
        else rule.stage
    )

    if isinstance(value, Number):
        numeric_value = float(
            _coerce_finite_score_value(
                value,
                name="score adjustment value",
            )
        )

        return ScoreAdjustment(
            adjustment_id=(
                f"{rule_name or 'adjustment'}:{index}"
            ),
            kind=(
                ADJUSTMENT_KIND_PENALTY
                if numeric_value >= 0.0
                else ADJUSTMENT_KIND_BONUS
            ),
            category=PENALTY_CATEGORY_CUSTOM,
            operation=(
                ADJUSTMENT_OPERATION_SUBTRACT
                if numeric_value >= 0.0
                else ADJUSTMENT_OPERATION_ADD
            ),
            value=abs(numeric_value),
            source=ADJUSTMENT_SOURCE_RULE,
            status=ADJUSTMENT_STATUS_APPLIED,
            stage=default_stage,
            rule_name=rule_name,
        )

    if isinstance(value, Mapping):
        kind = normalize_adjustment_kind(
            value.get(
                "kind",
                ADJUSTMENT_KIND_CORRECTION,
            )
        )

        default_operation = (
            ADJUSTMENT_OPERATION_SUBTRACT
            if kind == ADJUSTMENT_KIND_PENALTY
            else ADJUSTMENT_OPERATION_ADD
        )

        return ScoreAdjustment(
            adjustment_id=value.get(
                "adjustment_id",
                f"{rule_name or 'adjustment'}:{index}",
            ),
            kind=kind,
            category=value.get(
                "category",
                (
                    PENALTY_CATEGORY_CUSTOM
                    if kind == ADJUSTMENT_KIND_PENALTY
                    else CORRECTION_CATEGORY_CUSTOM
                ),
            ),
            operation=value.get(
                "operation",
                default_operation,
            ),
            value=value.get(
                "value",
                0.0,
            ),
            source=value.get(
                "source",
                ADJUSTMENT_SOURCE_RULE,
            ),
            status=value.get(
                "status",
                ADJUSTMENT_STATUS_APPLIED,
            ),
            stage=value.get(
                "stage",
                default_stage,
            ),
            reason=value.get(
                "reason",
                (
                    ""
                    if rule is None
                    else rule.description
                ),
            ),
            rule_name=value.get(
                "rule_name",
                rule_name,
            ),
            metadata=value.get(
                "metadata",
                {},
            ),
        )

    raise InvalidScoreAdjustmentError(
        "Adjustment callbacks must return a ScoreAdjustment, "
        "number, mapping, iterable of supported values or None."
    )


def coerce_score_adjustments(
    value: Any,
    *,
    rule: Optional[ScoreAdjustmentRule] = None,
) -> Tuple[ScoreAdjustment, ...]:
    """
    Convert a callback result to a tuple of ScoreAdjustment objects.
    """

    if value is None:
        return ()

    if isinstance(
        value,
        (
            ScoreAdjustment,
            Number,
            Mapping,
        ),
    ):
        return (
            coerce_score_adjustment(
                value,
                rule=rule,
                index=0,
            ),
        )

    if isinstance(
        value,
        Iterable,
    ) and not isinstance(
        value,
        (
            str,
            bytes,
            bytearray,
        ),
    ):
        return tuple(
            coerce_score_adjustment(
                item,
                rule=rule,
                index=index,
            )
            for index, item
            in enumerate(value)
        )

    raise InvalidScoreAdjustmentError(
        "Unsupported score-adjustment result."
    )


# -----------------------------------------------------------------------------
# 12.10. Built-in penalty evaluators
# -----------------------------------------------------------------------------

def _poor_geometry_penalty_rule(
    score: InteractionScore,
    context: ScoreAdjustmentContext,
) -> Tuple[ScoreAdjustment, ...]:
    """
    Penalize poor or unknown geometry quality.
    """

    profile = context.metadata.get(
        "_adjustment_profile"
    )

    if not isinstance(
        profile,
        ScoreAdjustmentProfile,
    ):
        return ()

    adjustments: List[ScoreAdjustment] = []

    if context.geometry_quality == GEOMETRY_POOR:
        adjustments.append(
            ScoreAdjustment(
                adjustment_id="geometry:poor",
                kind=ADJUSTMENT_KIND_PENALTY,
                category=PENALTY_CATEGORY_GEOMETRY,
                operation=ADJUSTMENT_OPERATION_SUBTRACT,
                value=profile.poor_geometry_penalty,
                source=ADJUSTMENT_SOURCE_PROFILE,
                reason=(
                    "The interaction has poor geometric quality."
                ),
                rule_name="poor_geometry_penalty",
            )
        )

    elif context.geometry_quality == GEOMETRY_UNKNOWN:
        adjustments.append(
            ScoreAdjustment(
                adjustment_id="geometry:unknown",
                kind=ADJUSTMENT_KIND_PENALTY,
                category=PENALTY_CATEGORY_UNCERTAINTY,
                operation=ADJUSTMENT_OPERATION_SUBTRACT,
                value=profile.unknown_geometry_penalty,
                source=ADJUSTMENT_SOURCE_PROFILE,
                reason=(
                    "Geometry quality could not be resolved."
                ),
                rule_name="poor_geometry_penalty",
            )
        )

    if context.missing_geometry_metric_count > 0:
        adjustments.append(
            ScoreAdjustment(
                adjustment_id="geometry:incomplete",
                kind=ADJUSTMENT_KIND_PENALTY,
                category=(
                    PENALTY_CATEGORY_INCOMPLETE_DATA
                ),
                operation=ADJUSTMENT_OPERATION_SUBTRACT,
                value=(
                    profile.incomplete_geometry_penalty
                    * context.missing_geometry_metric_count
                ),
                source=ADJUSTMENT_SOURCE_PROFILE,
                reason=(
                    "One or more configured geometry metrics "
                    "were unavailable."
                ),
                rule_name="poor_geometry_penalty",
                metadata={
                    "missing_metric_count": (
                        context.missing_geometry_metric_count
                    ),
                },
            )
        )

    return tuple(adjustments)


def _unknown_classification_penalty_rule(
    score: InteractionScore,
    context: ScoreAdjustmentContext,
) -> Tuple[ScoreAdjustment, ...]:
    """
    Penalize unresolved strength or classification.
    """

    profile = context.metadata.get(
        "_adjustment_profile"
    )

    if not isinstance(
        profile,
        ScoreAdjustmentProfile,
    ):
        return ()

    adjustments: List[ScoreAdjustment] = []

    if context.strength == STRENGTH_UNKNOWN:
        adjustments.append(
            ScoreAdjustment(
                adjustment_id="strength:unknown",
                kind=ADJUSTMENT_KIND_PENALTY,
                category=PENALTY_CATEGORY_UNCERTAINTY,
                operation=ADJUSTMENT_OPERATION_SUBTRACT,
                value=profile.unknown_strength_penalty,
                source=ADJUSTMENT_SOURCE_PROFILE,
                reason=(
                    "Interaction strength was not classified."
                ),
                rule_name="unknown_classification_penalty",
            )
        )

    if context.classification == CLASSIFICATION_UNKNOWN:
        adjustments.append(
            ScoreAdjustment(
                adjustment_id="classification:unknown",
                kind=ADJUSTMENT_KIND_PENALTY,
                category=PENALTY_CATEGORY_CLASSIFICATION,
                operation=ADJUSTMENT_OPERATION_SUBTRACT,
                value=(
                    profile.unknown_classification_penalty
                ),
                source=ADJUSTMENT_SOURCE_PROFILE,
                reason=(
                    "Interaction classification was not resolved."
                ),
                rule_name="unknown_classification_penalty",
            )
        )

    return tuple(adjustments)


def _steric_penalty_rule(
    score: InteractionScore,
    context: ScoreAdjustmentContext,
) -> Tuple[ScoreAdjustment, ...]:
    """
    Apply additional penalties to severe atomic clashes.
    """

    profile = context.metadata.get(
        "_adjustment_profile"
    )

    if not isinstance(
        profile,
        ScoreAdjustmentProfile,
    ):
        return ()

    if (
        context.interaction_type != SCORE_TYPE_CLASH
        and context.interaction_family
        != SCORE_FAMILY_STERIC
    ):
        return ()

    if context.distance is None:
        return ()

    if context.distance < 2.0:
        return (
            ScoreAdjustment(
                adjustment_id="steric:severe",
                kind=ADJUSTMENT_KIND_PENALTY,
                category=PENALTY_CATEGORY_STERIC,
                operation=ADJUSTMENT_OPERATION_SUBTRACT,
                value=profile.severe_clash_penalty,
                source=ADJUSTMENT_SOURCE_PROFILE,
                reason=(
                    "A severe short-range steric clash was detected."
                ),
                rule_name="steric_penalty",
            ),
        )

    if context.distance < 2.5:
        return (
            ScoreAdjustment(
                adjustment_id="steric:moderate",
                kind=ADJUSTMENT_KIND_PENALTY,
                category=PENALTY_CATEGORY_STERIC,
                operation=ADJUSTMENT_OPERATION_SUBTRACT,
                value=profile.moderate_clash_penalty,
                source=ADJUSTMENT_SOURCE_PROFILE,
                reason=(
                    "A moderate steric clash was detected."
                ),
                rule_name="steric_penalty",
            ),
        )

    return ()


def _duplicate_retention_rule(
    score: InteractionScore,
    context: ScoreAdjustmentContext,
) -> Tuple[ScoreAdjustment, ...]:
    """
    Reduce retained contributions from duplicate interactions.
    """

    profile = context.metadata.get(
        "_adjustment_profile"
    )

    if not isinstance(
        profile,
        ScoreAdjustmentProfile,
    ):
        return ()

    if context.duplicate_count <= 1:
        return ()

    retention = float(
        profile.duplicate_score_retention
    )

    return (
        ScoreAdjustment(
            adjustment_id="duplicate:retention",
            kind=ADJUSTMENT_KIND_CORRECTION,
            category=CORRECTION_CATEGORY_DUPLICATE,
            operation=ADJUSTMENT_OPERATION_MULTIPLY,
            value=retention,
            source=ADJUSTMENT_SOURCE_PROFILE,
            reason=(
                "The interaction was marked as a duplicate and "
                "only a fraction of its score was retained."
            ),
            rule_name="duplicate_retention",
            metadata={
                "duplicate_count": (
                    context.duplicate_count
                ),
                "retention": retention,
            },
        ),
    )


def _score_limit_rule(
    score: InteractionScore,
    context: ScoreAdjustmentContext,
) -> Tuple[ScoreAdjustment, ...]:
    """
    Limit extreme absolute interaction scores.
    """

    profile = context.metadata.get(
        "_adjustment_profile"
    )

    if not isinstance(
        profile,
        ScoreAdjustmentProfile,
    ):
        return ()

    maximum = profile.maximum_absolute_score

    if maximum is None:
        return ()

    if context.final_score > maximum:
        return (
            ScoreAdjustment(
                adjustment_id="score:upper_cap",
                kind=ADJUSTMENT_KIND_CAP,
                category=CORRECTION_CATEGORY_SCORE_CAP,
                operation=ADJUSTMENT_OPERATION_MINIMUM,
                value=maximum,
                source=ADJUSTMENT_SOURCE_PROFILE,
                stage=ADJUSTMENT_STAGE_POST_FINAL,
                reason=(
                    "The interaction score exceeded the configured "
                    "maximum."
                ),
                rule_name="score_limit",
            ),
        )

    if context.final_score < -maximum:
        return (
            ScoreAdjustment(
                adjustment_id="score:lower_floor",
                kind=ADJUSTMENT_KIND_FLOOR,
                category=CORRECTION_CATEGORY_SCORE_FLOOR,
                operation=ADJUSTMENT_OPERATION_MAXIMUM,
                value=-maximum,
                source=ADJUSTMENT_SOURCE_PROFILE,
                stage=ADJUSTMENT_STAGE_POST_FINAL,
                reason=(
                    "The interaction score exceeded the configured "
                    "negative limit."
                ),
                rule_name="score_limit",
            ),
        )

    return ()


# -----------------------------------------------------------------------------
# 12.11. Default rules and profile
# -----------------------------------------------------------------------------

DEFAULT_SCORE_ADJUSTMENT_RULES: Final[
    Tuple[ScoreAdjustmentRule, ...]
] = (
    ScoreAdjustmentRule(
        name="poor_geometry_penalty",
        evaluator=_poor_geometry_penalty_rule,
        priority=100,
        stage=ADJUSTMENT_STAGE_FINAL,
        description=(
            "Penalizes poor, unknown or incomplete geometry."
        ),
    ),
    ScoreAdjustmentRule(
        name="unknown_classification_penalty",
        evaluator=_unknown_classification_penalty_rule,
        priority=90,
        stage=ADJUSTMENT_STAGE_FINAL,
        description=(
            "Penalizes unresolved interaction strength or classification."
        ),
    ),
    ScoreAdjustmentRule(
        name="steric_penalty",
        evaluator=_steric_penalty_rule,
        interaction_families=frozenset(
            {
                SCORE_FAMILY_STERIC,
            }
        ),
        priority=110,
        stage=ADJUSTMENT_STAGE_FINAL,
        description=(
            "Applies additional penalties to severe steric clashes."
        ),
    ),
    ScoreAdjustmentRule(
        name="duplicate_retention",
        evaluator=_duplicate_retention_rule,
        priority=120,
        stage=ADJUSTMENT_STAGE_PRE_FINAL,
        description=(
            "Reduces the retained score of duplicate interactions."
        ),
    ),
    ScoreAdjustmentRule(
        name="score_limit",
        evaluator=_score_limit_rule,
        priority=10,
        stage=ADJUSTMENT_STAGE_POST_FINAL,
        description=(
            "Applies configured absolute interaction-score limits."
        ),
    ),
)


DEFAULT_SCORE_ADJUSTMENT_PROFILE: Final[
    ScoreAdjustmentProfile
] = ScoreAdjustmentProfile(
    rules=DEFAULT_SCORE_ADJUSTMENT_RULES,
)


# -----------------------------------------------------------------------------
# 12.12. Adjustment resolution
# -----------------------------------------------------------------------------

def resolve_score_adjustments(
    score: InteractionScore,
    *,
    profile: ScoreAdjustmentProfile = (
        DEFAULT_SCORE_ADJUSTMENT_PROFILE
    ),
    strict: Optional[bool] = None,
) -> Tuple[ScoreAdjustment, ...]:
    """
    Resolve all applicable penalties and corrections.
    """

    validate_interaction_score(
        score,
        validate_consistency=False,
    )
    validate_score_adjustment_profile(
        profile
    )

    strict_mode = (
        profile.strict
        if strict is None
        else bool(strict)
    )

    context = ScoreAdjustmentContext.from_interaction_score(
        score
    )

    context_metadata = dict(context.metadata)
    context_metadata["_adjustment_profile"] = profile

    context = replace(
        context,
        metadata=context_metadata,
    )

    adjustments: List[ScoreAdjustment] = []
    seen_ids: Set[str] = set()

    for rule in profile.rules:
        resolved = rule.evaluate(
            score,
            context,
        )

        if not resolved:
            continue

        for adjustment in resolved:
            if (
                profile.prevent_duplicate_adjustments
                and adjustment.adjustment_id
                in seen_ids
            ):
                if strict_mode:
                    raise DuplicateScoreAdjustmentError(
                        "Duplicate score adjustment "
                        f"{adjustment.adjustment_id!r}."
                    )

                continue

            adjustments.append(adjustment)
            seen_ids.add(
                adjustment.adjustment_id
            )

        if (
            rule.stop_after_match
            and resolved
        ):
            break

    adjustments.sort(
        key=lambda adjustment: (
            _adjustment_stage_order(
                adjustment.stage
            ),
            adjustment.rule_name,
            adjustment.adjustment_id,
        )
    )

    return tuple(adjustments)


def resolve_score_adjustment_collection(
    scores: Iterable[InteractionScore],
    *,
    profile: ScoreAdjustmentProfile = (
        DEFAULT_SCORE_ADJUSTMENT_PROFILE
    ),
    strict: Optional[bool] = None,
    skip_errors: bool = False,
) -> Mapping[str, Tuple[ScoreAdjustment, ...]]:
    """
    Resolve adjustments for multiple InteractionScore objects.
    """

    results: Dict[
        str,
        Tuple[ScoreAdjustment, ...],
    ] = {}

    for score in scores:
        try:
            adjustments = resolve_score_adjustments(
                score,
                profile=profile,
                strict=strict,
            )
        except (
            ScoringError,
            TypeError,
            ValueError,
            AttributeError,
        ):
            if skip_errors:
                continue

            raise

        results[score.interaction_id] = adjustments

    return MappingProxyType(results)


# -----------------------------------------------------------------------------
# 12.13. Adjustment application
# -----------------------------------------------------------------------------

def apply_score_adjustments(
    value: Number,
    adjustments: Iterable[ScoreAdjustment],
) -> float:
    """
    Apply adjustments deterministically to a numeric value.
    """

    current = float(
        _coerce_finite_score_value(
            value,
            name="score adjustment input",
        )
    )

    normalized = tuple(adjustments)

    for adjustment in normalized:
        validate_score_adjustment(
            adjustment
        )
        current = adjustment.apply(current)

    return float(current)


def calculate_adjustment_totals(
    adjustments: Iterable[ScoreAdjustment],
    *,
    input_score: Number,
) -> Mapping[str, float]:
    """
    Calculate total penalty, bonus and correction effects.
    """

    current = float(
        _coerce_finite_score_value(
            input_score,
            name="adjustment total input score",
        )
    )

    penalty_total = 0.0
    bonus_total = 0.0
    correction_delta = 0.0

    for adjustment in adjustments:
        before = current
        current = adjustment.apply(
            current
        )
        delta = current - before

        if adjustment.kind == ADJUSTMENT_KIND_PENALTY:
            penalty_total += max(
                0.0,
                -delta,
            )

        elif adjustment.kind == ADJUSTMENT_KIND_BONUS:
            bonus_total += max(
                0.0,
                delta,
            )

        else:
            correction_delta += delta

    return MappingProxyType(
        {
            "input_score": float(input_score),
            "output_score": float(current),
            "penalty_total": float(
                penalty_total
            ),
            "bonus_total": float(
                bonus_total
            ),
            "correction_delta": float(
                correction_delta
            ),
            "total_delta": float(
                current - float(input_score)
            ),
        }
    )


def apply_adjustments_to_interaction_score(
    score: InteractionScore,
    *,
    profile: ScoreAdjustmentProfile = (
        DEFAULT_SCORE_ADJUSTMENT_PROFILE
    ),
    strict: Optional[bool] = None,
) -> InteractionScore:
    """
    Resolve and apply penalties and corrections to an InteractionScore.
    """

    validate_interaction_score(
        score,
        validate_consistency=False,
    )

    adjustments = resolve_score_adjustments(
        score,
        profile=profile,
        strict=strict,
    )

    current_score = float(
        score.final_score
    )
    added_penalty = 0.0
    added_bonus = 0.0
    correction_delta = 0.0

    for adjustment in adjustments:
        before = current_score
        current_score = adjustment.apply(
            current_score
        )
        delta = current_score - before

        if adjustment.kind == ADJUSTMENT_KIND_PENALTY:
            added_penalty += max(
                0.0,
                -delta,
            )

        elif adjustment.kind == ADJUSTMENT_KIND_BONUS:
            added_bonus += max(
                0.0,
                delta,
            )

        else:
            correction_delta += delta

    metadata = dict(score.metadata)

    previous_adjustments = metadata.get(
        "score_adjustments",
        (),
    )

    serialized_adjustments = tuple(
        adjustment.to_dict(
            include_metadata=True
        )
        for adjustment in adjustments
    )

    if isinstance(
        previous_adjustments,
        Sequence,
    ) and not isinstance(
        previous_adjustments,
        (
            str,
            bytes,
            bytearray,
        ),
    ):
        complete_adjustments = (
            tuple(previous_adjustments)
            + serialized_adjustments
        )
    else:
        complete_adjustments = serialized_adjustments

    metadata["score_adjustments"] = complete_adjustments
    metadata["pre_adjustment_final_score"] = (
        score.final_score
    )
    metadata["correction_delta"] = float(
        correction_delta
    )
    metadata["post_adjustment_final_score"] = (
        current_score
    )

    adjustment_component_types = {
        f"score_{ADJUSTMENT_KIND_CORRECTION}",
        f"score_{ADJUSTMENT_KIND_CAP}",
        f"score_{ADJUSTMENT_KIND_FLOOR}",
        f"score_{ADJUSTMENT_KIND_REPLACEMENT}",
    }

    components = tuple(
        component
        for component in score.components
        if (
            component.component_type
            not in adjustment_component_types
            or not (
                isinstance(
                    component.metadata,
                    Mapping,
                )
                and component.metadata.get(
                    "adjustment_id"
                )
            )
        )
    )

    components = components + tuple(
        adjustment.to_component()
        for adjustment in adjustments
    )

    return replace(
        score,
        penalty_score=float(
            score.penalty_score
            + added_penalty
        ),
        bonus_score=float(
            score.bonus_score
            + added_bonus
        ),
        final_score=float(
            current_score
        ),
        components=components,
        metadata=metadata,
    )


# -----------------------------------------------------------------------------
# 12.14. Complete score pipeline through adjustments
# -----------------------------------------------------------------------------

def interaction_score_with_adjustments(
    data: ExtractedInteractionData,
    *,
    base_weight_profile: BaseWeightProfile = (
        DEFAULT_BASE_WEIGHT_PROFILE
    ),
    multiplier_profile: InteractionMultiplierProfile = (
        DEFAULT_INTERACTION_MULTIPLIER_PROFILE
    ),
    geometry_profile: GeometryQualityProfile = (
        DEFAULT_GEOMETRY_QUALITY_PROFILE
    ),
    family_profile: FamilyScoringProfile = (
        DEFAULT_COMPLETE_FAMILY_SCORING_PROFILE
    ),
    adjustment_profile: ScoreAdjustmentProfile = (
        DEFAULT_SCORE_ADJUSTMENT_PROFILE
    ),
    scoring_config: Optional[ScoringConfig] = None,
    weight_overrides: Optional[
        Mapping[Any, Number]
    ] = None,
    strength_overrides: Optional[
        Mapping[Any, Number]
    ] = None,
    classification_overrides: Optional[
        Mapping[Any, Number]
    ] = None,
    strict_weights: Optional[bool] = None,
    strict_strength: Optional[bool] = None,
    strict_classification: Optional[bool] = None,
    strict_geometry: Optional[bool] = None,
    strict_family: Optional[bool] = None,
    strict_adjustments: Optional[bool] = None,
    preserve_components: bool = True,
) -> InteractionScore:
    """
    Score one interaction through penalties and corrections.
    """

    score = interaction_score_with_family_scoring(
        data,
        base_weight_profile=base_weight_profile,
        multiplier_profile=multiplier_profile,
        geometry_profile=geometry_profile,
        family_profile=family_profile,
        scoring_config=scoring_config,
        weight_overrides=weight_overrides,
        strength_overrides=strength_overrides,
        classification_overrides=(
            classification_overrides
        ),
        strict_weights=strict_weights,
        strict_strength=strict_strength,
        strict_classification=(
            strict_classification
        ),
        strict_geometry=strict_geometry,
        strict_family=strict_family,
        preserve_components=preserve_components,
    )

    return apply_adjustments_to_interaction_score(
        score,
        profile=adjustment_profile,
        strict=strict_adjustments,
    )


def interactions_with_adjustments(
    interactions: Iterable[ExtractedInteractionData],
    *,
    base_weight_profile: BaseWeightProfile = (
        DEFAULT_BASE_WEIGHT_PROFILE
    ),
    multiplier_profile: InteractionMultiplierProfile = (
        DEFAULT_INTERACTION_MULTIPLIER_PROFILE
    ),
    geometry_profile: GeometryQualityProfile = (
        DEFAULT_GEOMETRY_QUALITY_PROFILE
    ),
    family_profile: FamilyScoringProfile = (
        DEFAULT_COMPLETE_FAMILY_SCORING_PROFILE
    ),
    adjustment_profile: ScoreAdjustmentProfile = (
        DEFAULT_SCORE_ADJUSTMENT_PROFILE
    ),
    scoring_config: Optional[ScoringConfig] = None,
    weight_overrides: Optional[
        Mapping[Any, Number]
    ] = None,
    strength_overrides: Optional[
        Mapping[Any, Number]
    ] = None,
    classification_overrides: Optional[
        Mapping[Any, Number]
    ] = None,
    strict_weights: Optional[bool] = None,
    strict_strength: Optional[bool] = None,
    strict_classification: Optional[bool] = None,
    strict_geometry: Optional[bool] = None,
    strict_family: Optional[bool] = None,
    strict_adjustments: Optional[bool] = None,
    preserve_components: bool = True,
    skip_errors: bool = False,
) -> Tuple[InteractionScore, ...]:
    """
    Score multiple extracted interactions through the adjustment stage.
    """

    scores: List[InteractionScore] = []

    for interaction in interactions:
        try:
            score = interaction_score_with_adjustments(
                interaction,
                base_weight_profile=base_weight_profile,
                multiplier_profile=multiplier_profile,
                geometry_profile=geometry_profile,
                family_profile=family_profile,
                adjustment_profile=adjustment_profile,
                scoring_config=scoring_config,
                weight_overrides=weight_overrides,
                strength_overrides=strength_overrides,
                classification_overrides=(
                    classification_overrides
                ),
                strict_weights=strict_weights,
                strict_strength=strict_strength,
                strict_classification=(
                    strict_classification
                ),
                strict_geometry=strict_geometry,
                strict_family=strict_family,
                strict_adjustments=(
                    strict_adjustments
                ),
                preserve_components=preserve_components,
            )
        except (
            ScoringError,
            TypeError,
            ValueError,
            AttributeError,
        ):
            if skip_errors:
                continue

            raise

        scores.append(score)

    return sort_interaction_scores(
        scores
    )


def extract_recognize_and_apply_adjustments(
    source: Any,
    *,
    container_name: Optional[str] = None,
    pose_id: Optional[str] = None,
    model_id: Optional[str] = None,
    ligand_id: Optional[str] = None,
    recognition_config: InteractionRecognitionConfig = (
        DEFAULT_INTERACTION_RECOGNITION_CONFIG
    ),
    recognition_rules: Iterable[
        InteractionRecognitionRule
    ] = (),
    base_weight_profile: BaseWeightProfile = (
        DEFAULT_BASE_WEIGHT_PROFILE
    ),
    multiplier_profile: InteractionMultiplierProfile = (
        DEFAULT_INTERACTION_MULTIPLIER_PROFILE
    ),
    geometry_profile: GeometryQualityProfile = (
        DEFAULT_GEOMETRY_QUALITY_PROFILE
    ),
    family_profile: FamilyScoringProfile = (
        DEFAULT_COMPLETE_FAMILY_SCORING_PROFILE
    ),
    adjustment_profile: ScoreAdjustmentProfile = (
        DEFAULT_SCORE_ADJUSTMENT_PROFILE
    ),
    scoring_config: Optional[ScoringConfig] = None,
    preserve_references: bool = True,
    skip_errors: bool = False,
) -> Tuple[InteractionScore, ...]:
    """
    Run extraction, recognition and scoring through corrections.
    """

    extracted = extract_and_recognize_interactions(
        source,
        container_name=container_name,
        pose_id=pose_id,
        model_id=model_id,
        ligand_id=ligand_id,
        config=recognition_config,
        custom_rules=recognition_rules,
        preserve_references=preserve_references,
        skip_errors=skip_errors,
    )

    return interactions_with_adjustments(
        extracted,
        base_weight_profile=base_weight_profile,
        multiplier_profile=multiplier_profile,
        geometry_profile=geometry_profile,
        family_profile=family_profile,
        adjustment_profile=adjustment_profile,
        scoring_config=scoring_config,
        skip_errors=skip_errors,
    )


# -----------------------------------------------------------------------------
# 12.15. Summary helpers
# -----------------------------------------------------------------------------

def summarize_score_adjustments(
    adjustments: Iterable[ScoreAdjustment],
) -> Mapping[str, Any]:
    """
    Summarize resolved penalties and corrections.
    """

    normalized = tuple(
        validate_score_adjustment(
            adjustment
        )
        for adjustment in adjustments
    )

    kind_counts: Dict[str, int] = {}
    category_counts: Dict[str, int] = {}
    source_counts: Dict[str, int] = {}
    stage_counts: Dict[str, int] = {}

    nominal_penalty = 0.0
    nominal_bonus = 0.0

    for adjustment in normalized:
        kind_counts[adjustment.kind] = (
            kind_counts.get(
                adjustment.kind,
                0,
            )
            + 1
        )

        category_counts[adjustment.category] = (
            category_counts.get(
                adjustment.category,
                0,
            )
            + 1
        )

        source_counts[adjustment.source] = (
            source_counts.get(
                adjustment.source,
                0,
            )
            + 1
        )

        stage_counts[adjustment.stage] = (
            stage_counts.get(
                adjustment.stage,
                0,
            )
            + 1
        )

        if adjustment.kind == ADJUSTMENT_KIND_PENALTY:
            nominal_penalty += abs(
                adjustment.value
            )

        elif adjustment.kind == ADJUSTMENT_KIND_BONUS:
            nominal_bonus += abs(
                adjustment.value
            )

    return MappingProxyType(
        {
            "count": len(normalized),
            "kind_counts": MappingProxyType(
                kind_counts
            ),
            "category_counts": MappingProxyType(
                category_counts
            ),
            "source_counts": MappingProxyType(
                source_counts
            ),
            "stage_counts": MappingProxyType(
                stage_counts
            ),
            "nominal_penalty": float(
                nominal_penalty
            ),
            "nominal_bonus": float(
                nominal_bonus
            ),
        }
    )


def summarize_adjusted_scores(
    scores: Iterable[InteractionScore],
) -> Mapping[str, Any]:
    """
    Summarize adjusted InteractionScore objects.
    """

    normalized = tuple(scores)

    final_scores = [
        score.final_score
        for score in normalized
    ]
    penalties = [
        score.penalty_score
        for score in normalized
    ]
    bonuses = [
        score.bonus_score
        for score in normalized
    ]

    adjusted_count = sum(
        1
        for score in normalized
        if score.metadata.get(
            "score_adjustments"
        )
    )

    return MappingProxyType(
        {
            "count": len(normalized),
            "adjusted_count": adjusted_count,
            "total_final_score": float(
                sum(final_scores)
            ),
            "total_penalty_score": float(
                sum(penalties)
            ),
            "total_bonus_score": float(
                sum(bonuses)
            ),
            "mean_final_score": (
                0.0
                if not final_scores
                else float(
                    sum(final_scores)
                    / len(final_scores)
                )
            ),
            "minimum_final_score": (
                None
                if not final_scores
                else min(final_scores)
            ),
            "maximum_final_score": (
                None
                if not final_scores
                else max(final_scores)
            ),
        }
    )


# -----------------------------------------------------------------------------
# 12.16. Validation
# -----------------------------------------------------------------------------

def validate_score_adjustment(
    adjustment: ScoreAdjustment,
) -> ScoreAdjustment:
    """
    Validate and return one score adjustment.
    """

    if not isinstance(
        adjustment,
        ScoreAdjustment,
    ):
        raise InvalidScoreAdjustmentError(
            "Expected a ScoreAdjustment instance."
        )

    _coerce_finite_score_value(
        adjustment.value,
        name="ScoreAdjustment.value",
    )

    return adjustment


def validate_score_adjustment_rule(
    rule: ScoreAdjustmentRule,
) -> ScoreAdjustmentRule:
    """
    Validate and return one adjustment rule.
    """

    if not isinstance(
        rule,
        ScoreAdjustmentRule,
    ):
        raise InvalidScoreAdjustmentError(
            "Expected a ScoreAdjustmentRule instance."
        )

    if not callable(rule.evaluator):
        raise InvalidScoreAdjustmentError(
            "Adjustment rule evaluator is not callable."
        )

    return rule


def validate_score_adjustment_profile(
    profile: ScoreAdjustmentProfile,
) -> ScoreAdjustmentProfile:
    """
    Validate and return an adjustment profile.
    """

    if not isinstance(
        profile,
        ScoreAdjustmentProfile,
    ):
        raise InvalidScoreAdjustmentError(
            "Expected a ScoreAdjustmentProfile instance."
        )

    for rule in profile.rules:
        validate_score_adjustment_rule(
            rule
        )

    return profile


def validate_adjusted_interaction_score(
    score: InteractionScore,
) -> InteractionScore:
    """
    Validate an InteractionScore after adjustments.
    """

    validate_interaction_score(
        score,
        validate_consistency=False,
    )

    if not math.isfinite(
        score.final_score
    ):
        raise InvalidScoreAdjustmentError(
            "Adjusted final score must be finite."
        )

    if score.penalty_score < 0.0:
        raise InvalidScoreAdjustmentError(
            "Adjusted penalty score cannot be negative."
        )

    if score.bonus_score < 0.0:
        raise InvalidScoreAdjustmentError(
            "Adjusted bonus score cannot be negative."
        )

    return score


# -----------------------------------------------------------------------------
# 12.17. Explainability
# -----------------------------------------------------------------------------

def explain_score_adjustment(
    adjustment: ScoreAdjustment,
    *,
    input_score: Optional[Number] = None,
) -> ScoreExplanation:
    """
    Create a structured explanation for one adjustment.
    """

    validate_score_adjustment(
        adjustment
    )

    output_score: Optional[float]
    delta: Optional[float]

    if input_score is None:
        output_score = None
        delta = None
    else:
        normalized_input = float(
            _coerce_finite_score_value(
                input_score,
                name="adjustment explanation input",
            )
        )

        output_score = adjustment.apply(
            normalized_input
        )
        delta = (
            output_score
            - normalized_input
        )

    if adjustment.kind == ADJUSTMENT_KIND_PENALTY:
        severity = EXPLANATION_SEVERITY_WARNING

    elif adjustment.kind == ADJUSTMENT_KIND_BONUS:
        severity = EXPLANATION_SEVERITY_SUCCESS

    elif adjustment.status == ADJUSTMENT_STATUS_INVALID:
        severity = EXPLANATION_SEVERITY_ERROR

    else:
        severity = EXPLANATION_SEVERITY_INFO

    return ScoreExplanation(
        explanation_id=(
            f"score_adjustment:"
            f"{adjustment.adjustment_id}"
        ),
        title=(
            f"Score adjustment: "
            f"{adjustment.category}"
        ),
        message=adjustment.reason,
        scope=EXPLANATION_SCOPE_INTERACTION,
        severity=severity,
        level=EXPLANATION_LEVEL_STANDARD,
        value=(
            output_score
            if output_score is not None
            else adjustment.value
        ),
        reference_value=(
            None
            if input_score is None
            else float(input_score)
        ),
        tags=(
            "score_adjustment",
            adjustment.kind,
            adjustment.category,
            adjustment.operation,
            adjustment.stage,
        ),
        metadata={
            "adjustment_id": adjustment.adjustment_id,
            "rule_name": adjustment.rule_name,
            "source": adjustment.source,
            "delta": delta,
            "output_score": output_score,
        },
    )


def explain_score_adjustments(
    adjustments: Iterable[ScoreAdjustment],
    *,
    input_score: Number,
) -> ScoreExplanation:
    """
    Create a combined explanation for multiple adjustments.
    """

    normalized_input = float(
        _coerce_finite_score_value(
            input_score,
            name="adjustments explanation input",
        )
    )

    current = normalized_input
    children: List[ScoreExplanation] = []

    for adjustment in adjustments:
        explanation = explain_score_adjustment(
            adjustment,
            input_score=current,
        )
        children.append(explanation)
        current = adjustment.apply(
            current
        )

    return ScoreExplanation(
        explanation_id="score_adjustments",
        title="Penalties and corrections",
        message=(
            "Resolved penalties and corrections were applied in "
            "deterministic stage and rule order."
        ),
        scope=EXPLANATION_SCOPE_INTERACTION,
        severity=EXPLANATION_SEVERITY_INFO,
        level=EXPLANATION_LEVEL_STANDARD,
        value=current,
        reference_value=normalized_input,
        tags=(
            "score_adjustments",
            "penalties",
            "corrections",
        ),
        children=tuple(children),
        metadata={
            "adjustment_count": len(children),
            "total_delta": (
                current - normalized_input
            ),
        },
    )


# -----------------------------------------------------------------------------
# 12.18. Section consistency validation
# -----------------------------------------------------------------------------

def _validate_section_12_penalties_and_corrections() -> None:
    """
    Validate penalty and correction behavior during module import.
    """

    penalty = ScoreAdjustment(
        adjustment_id="test:penalty",
        kind=ADJUSTMENT_KIND_PENALTY,
        category=PENALTY_CATEGORY_GEOMETRY,
        operation=ADJUSTMENT_OPERATION_SUBTRACT,
        value=0.25,
        source=ADJUSTMENT_SOURCE_RULE,
    )

    if (
        abs(
            penalty.apply(2.0)
            - 1.75
        )
        > SCORE_COMPARISON_TOLERANCE
    ):
        raise RuntimeError(
            "Penalty application validation failed."
        )

    correction = ScoreAdjustment(
        adjustment_id="test:correction",
        kind=ADJUSTMENT_KIND_CORRECTION,
        category=CORRECTION_CATEGORY_NORMALIZATION,
        operation=ADJUSTMENT_OPERATION_MULTIPLY,
        value=0.5,
        source=ADJUSTMENT_SOURCE_RULE,
    )

    if (
        abs(
            correction.apply(2.0)
            - 1.0
        )
        > SCORE_COMPARISON_TOLERANCE
    ):
        raise RuntimeError(
            "Correction application validation failed."
        )

    data = ExtractedInteractionData(
        interaction_id="unknown_geometry_1",
        interaction_type="hydrogen_bond",
        interaction_family="hydrogen_bond",
        strength="unknown",
        classification="unknown",
        geometry_quality="unknown",
        atom_pair=(
            "A:10:N",
            "L:1:O",
        ),
        residue_pair=(
            "A:10:LYS",
            "L:1:LIG",
        ),
    )

    score = interaction_score_with_family_scoring(
        data,
        base_weight_profile=BaseWeightProfile(
            interaction_weights={
                "hydrogen_bond": 2.0,
            },
            family_weights={},
        ),
        multiplier_profile=InteractionMultiplierProfile(
            strength_multipliers={
                "unknown": 1.0,
            },
            classification_multipliers={
                "unknown": 1.0,
            },
        ),
        geometry_profile=GeometryQualityProfile(
            multipliers={
                "unknown": 1.0,
            },
            rules_by_type={},
            trust_explicit_quality=True,
        ),
        family_profile=FamilyScoringProfile(
            family_multipliers={
                "hydrogen_bond": 1.0,
            },
            family_adjustments={
                "hydrogen_bond": 0.0,
            },
            rules=(),
        ),
    )

    adjusted = apply_adjustments_to_interaction_score(
        score,
        profile=DEFAULT_SCORE_ADJUSTMENT_PROFILE,
    )

    if adjusted.final_score >= score.final_score:
        raise RuntimeError(
            "Unknown-data penalty validation failed."
        )

    if adjusted.penalty_score <= score.penalty_score:
        raise RuntimeError(
            "Penalty accumulation validation failed."
        )

    clash_data = ExtractedInteractionData(
        interaction_id="clash_1",
        interaction_type="clash",
        interaction_family="steric",
        strength="strong",
        classification="conventional",
        geometry_quality="poor",
        distance=1.8,
    )

    clash_score = interaction_score_with_family_scoring(
        clash_data,
        base_weight_profile=BaseWeightProfile(
            interaction_weights={
                "clash": -2.0,
            },
            family_weights={},
        ),
        multiplier_profile=InteractionMultiplierProfile(
            strength_multipliers={
                "strong": 1.0,
            },
            classification_multipliers={
                "conventional": 1.0,
            },
        ),
        geometry_profile=GeometryQualityProfile(
            multipliers={
                "poor": 1.0,
            },
            rules_by_type={},
            trust_explicit_quality=True,
        ),
        family_profile=FamilyScoringProfile(
            family_multipliers={
                "steric": 1.0,
            },
            family_adjustments={
                "steric": 0.0,
            },
            rules=(),
        ),
    )

    adjusted_clash = apply_adjustments_to_interaction_score(
        clash_score,
        profile=DEFAULT_SCORE_ADJUSTMENT_PROFILE,
    )

    if adjusted_clash.final_score >= clash_score.final_score:
        raise RuntimeError(
            "Steric penalty validation failed."
        )

    cap = ScoreAdjustment(
        adjustment_id="test:cap",
        kind=ADJUSTMENT_KIND_CAP,
        category=CORRECTION_CATEGORY_SCORE_CAP,
        operation=ADJUSTMENT_OPERATION_MINIMUM,
        value=5.0,
    )

    if cap.apply(10.0) != 5.0:
        raise RuntimeError(
            "Score-cap validation failed."
        )

    explanation = explain_score_adjustments(
        (
            penalty,
            correction,
        ),
        input_score=2.0,
    )

    if len(explanation.children) != 2:
        raise RuntimeError(
            "Adjustment explanation validation failed."
        )

    validate_score_adjustment(
        penalty
    )
    validate_score_adjustment_rule(
        DEFAULT_SCORE_ADJUSTMENT_RULES[0]
    )
    validate_score_adjustment_profile(
        DEFAULT_SCORE_ADJUSTMENT_PROFILE
    )
    validate_adjusted_interaction_score(
        adjusted
    )


_validate_section_12_penalties_and_corrections()


