def normalize_collection_scoring_status(
    value: Any,
    *,
    default: str = COLLECTION_SCORING_STATUS_FAILED,
) -> str:
    """
    Normalize a collection-scoring status.
    """

    normalized = _normalize_scoring_name(value)

    if normalized in COLLECTION_SCORING_STATUSES:
        return normalized

    return _COLLECTION_SCORING_STATUS_ALIASES.get(
        normalized,
        default,
    )


