def normalize_pose_scoring_status(
    value: Any,
    *,
    default: str = POSE_SCORING_STATUS_FAILED,
) -> str:
    """
    Normalize a pose-scoring status.
    """

    normalized = _normalize_scoring_name(value)

    if normalized in POSE_SCORING_STATUSES:
        return normalized

    return _POSE_SCORING_STATUS_ALIASES.get(
        normalized,
        default,
    )


def normalize_pose_aggregation_mode(
    value: Any,
    *,
    default: str = DEFAULT_POSE_AGGREGATION_MODE,
) -> str:
    """
    Normalize a pose aggregation mode.
    """

    normalized = _normalize_scoring_name(value)

    if normalized in POSE_AGGREGATION_MODES:
        return normalized

    return _POSE_AGGREGATION_ALIASES.get(
        normalized,
        default,
    )


def normalize_pose_normalization_mode(
    value: Any,
    *,
    default: str = DEFAULT_POSE_NORMALIZATION_MODE,
) -> str:
    """
    Normalize a pose normalization mode.
    """

    normalized = _normalize_scoring_name(value)

    if normalized in POSE_NORMALIZATION_MODES:
        return normalized

    return _POSE_NORMALIZATION_ALIASES.get(
        normalized,
        default,
    )


def normalize_pose_correction_operation(
    value: Any,
    *,
    default: str = POSE_CORRECTION_NONE,
) -> str:
    """
    Normalize a pose-level correction operation.
    """

    normalized = _normalize_scoring_name(value)

    if normalized in POSE_CORRECTION_OPERATIONS:
        return normalized

    return _POSE_CORRECTION_OPERATION_ALIASES.get(
        normalized,
        default,
    )


# -----------------------------------------------------------------------------
# 16.3. Exceptions
# -----------------------------------------------------------------------------

class PoseScoringError(ScoringError):
    """
    Base exception for total pose scoring.
    """


class PoseScoringInputError(PoseScoringError):
    """
    Raised when pose-scoring input is invalid.
    """


class PoseAggregationError(PoseScoringError):
    """
    Raised when pose-level aggregation fails.
    """


class PoseNormalizationError(PoseScoringError):
    """
    Raised when pose-score normalization fails.
    """


class PoseCorrectionError(PoseScoringError):
    """
    Raised when a pose-level correction cannot be applied.
    """


class PoseScoringValidationError(PoseScoringError):
    """
    Raised when a pose-scoring result is inconsistent.
    """


# -----------------------------------------------------------------------------
# 16.4. PoseScoreCorrection
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class PoseScoreCorrection:
    """
    Immutable correction applied after pose aggregation.
    """

    name: str
    operation: str
    value: float

    reason: str = ""
    source: str = "pose_scoring"
    priority: int = 100
    enabled: bool = True

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize correction values.
        """

        name = _coerce_identifier(self.name)

        if not name:
            raise PoseCorrectionError(
                "PoseScoreCorrection.name cannot be empty."
            )

        operation = normalize_pose_correction_operation(
            self.operation
        )

        value = float(
            _coerce_finite_score_value(
                self.value,
                name="PoseScoreCorrection.value",
            )
        )

        object.__setattr__(
            self,
            "name",
            name,
        )
        object.__setattr__(
            self,
            "operation",
            operation,
        )
        object.__setattr__(
            self,
            "value",
            value,
        )
        object.__setattr__(
            self,
            "reason",
            _coerce_optional_text(self.reason),
        )
        object.__setattr__(
            self,
            "source",
            _coerce_identifier(self.source),
        )
        object.__setattr__(
            self,
            "priority",
            int(self.priority),
        )
        object.__setattr__(
            self,
            "enabled",
            bool(self.enabled),
        )
        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(self.metadata),
        )

    def apply(
        self,
        score: Number,
    ) -> float:
        """
        Apply this correction to a numerical pose score.
        """

        current = float(
            _coerce_finite_score_value(
                score,
                name="pose score",
            )
        )

        if not self.enabled:
            return current

        if self.operation == POSE_CORRECTION_NONE:
            return current

        if self.operation == POSE_CORRECTION_ADD:
            return current + self.value

        if self.operation == POSE_CORRECTION_SUBTRACT:
            return current - self.value

        if self.operation == POSE_CORRECTION_MULTIPLY:
            return current * self.value

        if self.operation == POSE_CORRECTION_CAP:
            return min(current, self.value)

        if self.operation == POSE_CORRECTION_FLOOR:
            return max(current, self.value)

        if self.operation == POSE_CORRECTION_REPLACE:
            return self.value

        raise PoseCorrectionError(
            f"Unsupported pose correction operation: "
            f"{self.operation!r}."
        )

    def delta(
        self,
        score: Number,
    ) -> float:
        """
        Return the score difference caused by this correction.
        """

        initial = float(score)

        return self.apply(initial) - initial

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
    ) -> Dict[str, Any]:
        """
        Return a serializable correction representation.
        """

        result: Dict[str, Any] = {
            "name": self.name,
            "operation": self.operation,
            "value": self.value,
            "reason": self.reason,
            "source": self.source,
            "priority": self.priority,
            "enabled": self.enabled,
        }

        if include_metadata:
            result["metadata"] = dict(self.metadata)

        return result


# -----------------------------------------------------------------------------
# 16.5. PoseScoringOptions
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class PoseScoringOptions:
    """
    Immutable configuration for total pose scoring.
    """

    aggregation_mode: str = DEFAULT_POSE_AGGREGATION_MODE
    normalization_mode: str = DEFAULT_POSE_NORMALIZATION_MODE
    normalization_factor: float = (
        DEFAULT_POSE_NORMALIZATION_FACTOR
    )

    family_weights: Mapping[str, float] = field(
        default_factory=lambda: MappingProxyType({})
    )
    type_weights: Mapping[str, float] = field(
        default_factory=lambda: MappingProxyType({})
    )

    corrections: Tuple[PoseScoreCorrection, ...] = field(
        default_factory=tuple
    )

    require_interactions: bool = (
        DEFAULT_POSE_REQUIRE_INTERACTIONS
    )
    include_residue_aggregation: bool = (
        DEFAULT_POSE_INCLUDE_RESIDUE_AGGREGATION
    )
    preserve_collection_result: bool = (
        DEFAULT_POSE_PRESERVE_COLLECTION_RESULT
    )
    validate_result: bool = (
        DEFAULT_POSE_VALIDATE_RESULT
    )

    heavy_atom_count: Optional[int] = None
    ligand_atom_count: Optional[int] = None

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize pose-scoring options.
        """

        aggregation_mode = normalize_pose_aggregation_mode(
            self.aggregation_mode
        )
        normalization_mode = normalize_pose_normalization_mode(
            self.normalization_mode
        )

        normalization_factor = float(
            _coerce_finite_score_value(
                self.normalization_factor,
                name="PoseScoringOptions.normalization_factor",
            )
        )

        if normalization_factor <= 0.0:
            raise PoseNormalizationError(
                "normalization_factor must be greater than zero."
            )

        family_weights = _normalize_pose_weight_mapping(
            self.family_weights,
            key_normalizer=canonical_interaction_family,
        )
        type_weights = _normalize_pose_weight_mapping(
            self.type_weights,
            key_normalizer=lambda value: normalize_interaction_type(
                value,
                preserve_unknown=True,
            ),
        )

        corrections: List[PoseScoreCorrection] = []

        for correction in self.corrections:
            if not isinstance(
                correction,
                PoseScoreCorrection,
            ):
                raise PoseScoringInputError(
                    "corrections must contain only "
                    "PoseScoreCorrection instances."
                )

            corrections.append(correction)

        corrections.sort(
            key=lambda correction: (
                correction.priority,
                correction.name,
            )
        )

        heavy_atom_count = _normalize_optional_positive_count(
            self.heavy_atom_count,
            field_name="heavy_atom_count",
        )
        ligand_atom_count = _normalize_optional_positive_count(
            self.ligand_atom_count,
            field_name="ligand_atom_count",
        )

        object.__setattr__(
            self,
            "aggregation_mode",
            aggregation_mode,
        )
        object.__setattr__(
            self,
            "normalization_mode",
            normalization_mode,
        )
        object.__setattr__(
            self,
            "normalization_factor",
            normalization_factor,
        )
        object.__setattr__(
            self,
            "family_weights",
            family_weights,
        )
        object.__setattr__(
            self,
            "type_weights",
            type_weights,
        )
        object.__setattr__(
            self,
            "corrections",
            tuple(corrections),
        )
        object.__setattr__(
            self,
            "heavy_atom_count",
            heavy_atom_count,
        )
        object.__setattr__(
            self,
            "ligand_atom_count",
            ligand_atom_count,
        )

        for field_name in (
            "require_interactions",
            "include_residue_aggregation",
            "preserve_collection_result",
            "validate_result",
        ):
            object.__setattr__(
                self,
                field_name,
                bool(getattr(self, field_name)),
            )

        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(self.metadata),
        )

    def with_updates(
        self,
        **changes: Any,
    ) -> "PoseScoringOptions":
        """
        Return a validated options copy.
        """

        return replace(self, **changes)

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
    ) -> Dict[str, Any]:
        """
        Return a mutable dictionary representation.
        """

        result: Dict[str, Any] = {
            "aggregation_mode": self.aggregation_mode,
            "normalization_mode": self.normalization_mode,
            "normalization_factor": self.normalization_factor,
            "family_weights": dict(self.family_weights),
            "type_weights": dict(self.type_weights),
            "corrections": [
                correction.to_dict(
                    include_metadata=include_metadata
                )
                for correction in self.corrections
            ],
            "require_interactions": self.require_interactions,
            "include_residue_aggregation": (
                self.include_residue_aggregation
            ),
            "preserve_collection_result": (
                self.preserve_collection_result
            ),
            "validate_result": self.validate_result,
            "heavy_atom_count": self.heavy_atom_count,
            "ligand_atom_count": self.ligand_atom_count,
        }

        if include_metadata:
            result["metadata"] = dict(self.metadata)

        return result


def _normalize_pose_weight_mapping(
    values: Mapping[str, Any],
    *,
    key_normalizer: Callable[[Any], str],
) -> Mapping[str, float]:
    """
    Normalize a pose weighting mapping.
    """

    normalized: Dict[str, float] = {}

    for raw_key, raw_value in values.items():
        key = key_normalizer(raw_key)

        value = float(
            _coerce_finite_score_value(
                raw_value,
                name=f"pose weight for {key!r}",
            )
        )

        if value < 0.0:
            raise PoseScoringInputError(
                "Pose scoring weights cannot be negative."
            )

        normalized[key] = value

    return MappingProxyType(
        dict(
            sorted(normalized.items())
        )
    )


def _normalize_optional_positive_count(
    value: Optional[Any],
    *,
    field_name: str,
) -> Optional[int]:
    """
    Normalize an optional strictly positive count.
    """

    if value is None:
        return None

    normalized = int(value)

    if normalized <= 0:
        raise PoseScoringInputError(
            f"{field_name} must be greater than zero."
        )

    return normalized


DEFAULT_POSE_SCORING_OPTIONS: Final[
    PoseScoringOptions
] = PoseScoringOptions()


