# -----------------------------------------------------------------------------
# 16.7. Pose score components
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class PoseScoreComponent:
    """
    Aggregated score component for one family or interaction type.
    """

    key: str
    component_kind: str

    interaction_count: int

    raw_score: float
    weighted_score: float
    final_score: float

    weight: float = 1.0

    favorable_score: float = 0.0
    unfavorable_score: float = 0.0
    penalty_score: float = 0.0
    bonus_score: float = 0.0

    interaction_ids: Tuple[str, ...] = field(
        default_factory=tuple
    )

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize pose component values.
        """

        key = _coerce_identifier(self.key)

        if not key:
            raise PoseScoringValidationError(
                "PoseScoreComponent.key cannot be empty."
            )

        interaction_count = int(self.interaction_count)

        if interaction_count < 0:
            raise PoseScoringValidationError(
                "interaction_count cannot be negative."
            )

        for field_name in (
            "raw_score",
            "weighted_score",
            "final_score",
            "weight",
            "favorable_score",
            "unfavorable_score",
            "penalty_score",
            "bonus_score",
        ):
            object.__setattr__(
                self,
                field_name,
                float(
                    _coerce_finite_score_value(
                        getattr(self, field_name),
                        name=f"PoseScoreComponent.{field_name}",
                    )
                ),
            )

        object.__setattr__(
            self,
            "key",
            key,
        )
        object.__setattr__(
            self,
            "component_kind",
            _normalize_scoring_name(
                self.component_kind
            ),
        )
        object.__setattr__(
            self,
            "interaction_count",
            interaction_count,
        )
        object.__setattr__(
            self,
            "interaction_ids",
            tuple(
                _coerce_identifier(value)
                for value in self.interaction_ids
                if _coerce_identifier(value)
            ),
        )
        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(self.metadata),
        )

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
    ) -> Dict[str, Any]:
        """
        Return a serializable component representation.
        """

        result: Dict[str, Any] = {
            "key": self.key,
            "component_kind": self.component_kind,
            "interaction_count": self.interaction_count,
            "raw_score": self.raw_score,
            "weighted_score": self.weighted_score,
            "final_score": self.final_score,
            "weight": self.weight,
            "favorable_score": self.favorable_score,
            "unfavorable_score": self.unfavorable_score,
            "penalty_score": self.penalty_score,
            "bonus_score": self.bonus_score,
            "interaction_ids": list(self.interaction_ids),
        }

        if include_metadata:
            result["metadata"] = dict(self.metadata)

        return result


