# -----------------------------------------------------------------------------
# 18.3. Exceptions
# -----------------------------------------------------------------------------

class DiversityError(ScoringError):
    """
    Base exception for pose diversity analysis.
    """


class DiversityInputError(DiversityError):
    """
    Raised when diversity-analysis input is invalid.
    """


class FingerprintError(DiversityError):
    """
    Raised when a pose fingerprint cannot be constructed.
    """


class FingerprintCompatibilityError(DiversityError):
    """
    Raised when incompatible fingerprints are compared.
    """


class SimilarityMetricError(DiversityError):
    """
    Raised when a similarity metric cannot be calculated.
    """


class DistanceMetricError(DiversityError):
    """
    Raised when a distance metric cannot be calculated.
    """


class RepresentativeSelectionError(DiversityError):
    """
    Raised when representative-pose selection fails.
    """


class DiversityValidationError(DiversityError):
    """
    Raised when a diversity-analysis result is inconsistent.
    """


# -----------------------------------------------------------------------------
# 18.4. Fingerprint options
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class FingerprintOptions:
    """
    Immutable configuration for pose fingerprint generation.
    """

    kind: str = DEFAULT_FINGERPRINT_KIND
    value_mode: str = DEFAULT_FINGERPRINT_VALUE_MODE

    include_ligand_residues: bool = (
        DEFAULT_INCLUDE_LIGAND_RESIDUES
    )
    include_unknown_residues: bool = (
        DEFAULT_INCLUDE_UNKNOWN_RESIDUES
    )
    include_zero_values: bool = DEFAULT_INCLUDE_ZERO_VALUES

    normalize_values: bool = (
        DEFAULT_NORMALIZE_FINGERPRINT_VALUES
    )

    hotspot_limit: Optional[int] = None
    score_threshold: float = 0.0

    family_weights: Mapping[str, float] = field(
        default_factory=lambda: MappingProxyType({})
    )
    type_weights: Mapping[str, float] = field(
        default_factory=lambda: MappingProxyType({})
    )

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize fingerprint-generation options.
        """

        kind = normalize_fingerprint_kind(self.kind)
        value_mode = normalize_fingerprint_value_mode(
            self.value_mode
        )

        hotspot_limit = (
            None
            if self.hotspot_limit is None
            else int(self.hotspot_limit)
        )

        if hotspot_limit is not None and hotspot_limit < 1:
            raise DiversityInputError(
                "hotspot_limit must be positive or None."
            )

        score_threshold = float(
            _coerce_finite_score_value(
                self.score_threshold,
                name="FingerprintOptions.score_threshold",
            )
        )

        family_weights = _normalize_diversity_weight_mapping(
            self.family_weights,
            key_normalizer=canonical_interaction_family,
        )
        type_weights = _normalize_diversity_weight_mapping(
            self.type_weights,
            key_normalizer=lambda value: normalize_interaction_type(
                value,
                preserve_unknown=True,
            ),
        )

        object.__setattr__(self, "kind", kind)
        object.__setattr__(
            self,
            "value_mode",
            value_mode,
        )
        object.__setattr__(
            self,
            "hotspot_limit",
            hotspot_limit,
        )
        object.__setattr__(
            self,
            "score_threshold",
            score_threshold,
        )
        object.__setattr__(
            self,
            "family_weights",
            family_weights,
        )
        object.__setattr__(
            self,
            "type_weights",
            type_weights,
        )

        for field_name in (
            "include_ligand_residues",
            "include_unknown_residues",
            "include_zero_values",
            "normalize_values",
        ):
            object.__setattr__(
                self,
                field_name,
                bool(getattr(self, field_name)),
            )

        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(self.metadata),
        )

    def with_updates(
        self,
        **changes: Any,
    ) -> "FingerprintOptions":
        """
        Return a validated copy.
        """

        return replace(self, **changes)

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
    ) -> Dict[str, Any]:
        """
        Return a serializable options representation.
        """

        result: Dict[str, Any] = {
            "kind": self.kind,
            "value_mode": self.value_mode,
            "include_ligand_residues": (
                self.include_ligand_residues
            ),
            "include_unknown_residues": (
                self.include_unknown_residues
            ),
            "include_zero_values": self.include_zero_values,
            "normalize_values": self.normalize_values,
            "hotspot_limit": self.hotspot_limit,
            "score_threshold": self.score_threshold,
            "family_weights": dict(self.family_weights),
            "type_weights": dict(self.type_weights),
        }

        if include_metadata:
            result["metadata"] = dict(self.metadata)

        return result


def _normalize_diversity_weight_mapping(
    values: Mapping[str, Any],
    *,
    key_normalizer: Callable[[Any], str],
) -> Mapping[str, float]:
    """
    Normalize family or interaction-type weights.
    """

    normalized: Dict[str, float] = {}

    for raw_key, raw_value in values.items():
        key = key_normalizer(raw_key)

        if not key:
            continue

        value = float(
            _coerce_finite_score_value(
                raw_value,
                name=f"fingerprint weight for {key!r}",
            )
        )

        if value < 0.0:
            raise DiversityInputError(
                "Fingerprint weights cannot be negative."
            )

        normalized[key] = value

    return MappingProxyType(
        dict(sorted(normalized.items()))
    )


DEFAULT_FINGERPRINT_OPTIONS: Final[
    FingerprintOptions
] = FingerprintOptions()


# -----------------------------------------------------------------------------
# 18.5. Diversity options
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class DiversityOptions:
    """
    Immutable configuration for cross-pose diversity analysis.
    """

    fingerprint_options: FingerprintOptions = (
        DEFAULT_FINGERPRINT_OPTIONS
    )

    similarity_metric: str = DEFAULT_SIMILARITY_METRIC
    distance_metric: str = DEFAULT_DISTANCE_METRIC

    aggregation_mode: str = (
        DEFAULT_DIVERSITY_AGGREGATION_MODE
    )
    representative_selection_method: str = (
        DEFAULT_REPRESENTATIVE_SELECTION_METHOD
    )

    representative_count: Optional[int] = None
    epsilon: float = DEFAULT_DIVERSITY_EPSILON

    preserve_pose_results: bool = (
        DEFAULT_PRESERVE_POSE_RESULTS
    )
    validate_result: bool = (
        DEFAULT_DIVERSITY_VALIDATE_RESULT
    )

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize diversity-analysis options.
        """

        if not isinstance(
            self.fingerprint_options,
            FingerprintOptions,
        ):
            raise DiversityInputError(
                "fingerprint_options must be a FingerprintOptions."
            )

        similarity_metric = normalize_similarity_metric(
            self.similarity_metric
        )
        distance_metric = normalize_distance_metric(
            self.distance_metric
        )
        aggregation_mode = normalize_diversity_aggregation_mode(
            self.aggregation_mode
        )
        representative_selection_method = (
            normalize_representative_selection_method(
                self.representative_selection_method
            )
        )

        representative_count = (
            None
            if self.representative_count is None
            else int(self.representative_count)
        )

        if (
            representative_count is not None
            and representative_count < 1
        ):
            raise DiversityInputError(
                "representative_count must be positive or None."
            )

        epsilon = float(
            _coerce_finite_score_value(
                self.epsilon,
                name="DiversityOptions.epsilon",
            )
        )

        if epsilon <= 0.0:
            raise DiversityInputError(
                "epsilon must be greater than zero."
            )

        object.__setattr__(
            self,
            "similarity_metric",
            similarity_metric,
        )
        object.__setattr__(
            self,
            "distance_metric",
            distance_metric,
        )
        object.__setattr__(
            self,
            "aggregation_mode",
            aggregation_mode,
        )
        object.__setattr__(
            self,
            "representative_selection_method",
            representative_selection_method,
        )
        object.__setattr__(
            self,
            "representative_count",
            representative_count,
        )
        object.__setattr__(
            self,
            "epsilon",
            epsilon,
        )
        object.__setattr__(
            self,
            "preserve_pose_results",
            bool(self.preserve_pose_results),
        )
        object.__setattr__(
            self,
            "validate_result",
            bool(self.validate_result),
        )
        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(self.metadata),
        )

    def with_updates(
        self,
        **changes: Any,
    ) -> "DiversityOptions":
        """
        Return a validated options copy.
        """

        return replace(self, **changes)

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
    ) -> Dict[str, Any]:
        """
        Return a serializable options representation.
        """

        result: Dict[str, Any] = {
            "fingerprint_options": (
                self.fingerprint_options.to_dict(
                    include_metadata=include_metadata
                )
            ),
            "similarity_metric": self.similarity_metric,
            "distance_metric": self.distance_metric,
            "aggregation_mode": self.aggregation_mode,
            "representative_selection_method": (
                self.representative_selection_method
            ),
            "representative_count": (
                self.representative_count
            ),
            "epsilon": self.epsilon,
            "preserve_pose_results": (
                self.preserve_pose_results
            ),
            "validate_result": self.validate_result,
        }

        if include_metadata:
            result["metadata"] = dict(self.metadata)

        return result


DEFAULT_DIVERSITY_OPTIONS: Final[
    DiversityOptions
] = DiversityOptions()


# -----------------------------------------------------------------------------
# 18.6. PoseFingerprint
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class PoseFingerprint:
    """
    Sparse immutable fingerprint describing one docking pose.
    """

    pose_id: str
    model_id: str
    ligand_id: str

    kind: str
    value_mode: str

    values: Mapping[str, float]

    feature_count: int
    active_feature_count: int
    total_value: float
    vector_norm: float

    pose_score: Optional[float] = None

    pose_result: Optional[PoseScoringResult] = field(
        default=None,
        compare=False,
        hash=False,
        repr=False,
    )

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize and freeze the fingerprint.
        """

        normalized_values: Dict[str, float] = {}

        for raw_key, raw_value in self.values.items():
            key = _coerce_identifier(raw_key)

            if not key:
                continue

            value = float(
                _coerce_finite_score_value(
                    raw_value,
                    name=f"fingerprint feature {key!r}",
                )
            )

            normalized_values[key] = value

        normalized_values = dict(
            sorted(normalized_values.items())
        )

        feature_count = int(self.feature_count)
        active_feature_count = int(
            self.active_feature_count
        )

        if feature_count < 0:
            raise DiversityValidationError(
                "feature_count cannot be negative."
            )

        if active_feature_count < 0:
            raise DiversityValidationError(
                "active_feature_count cannot be negative."
            )

        if active_feature_count > feature_count:
            raise DiversityValidationError(
                "active_feature_count cannot exceed feature_count."
            )

        total_value = float(
            _coerce_finite_score_value(
                self.total_value,
                name="PoseFingerprint.total_value",
            )
        )
        vector_norm = float(
            _coerce_finite_score_value(
                self.vector_norm,
                name="PoseFingerprint.vector_norm",
            )
        )

        if vector_norm < 0.0:
            raise DiversityValidationError(
                "vector_norm cannot be negative."
            )

        pose_score = (
            None
            if self.pose_score is None
            else float(
                _coerce_finite_score_value(
                    self.pose_score,
                    name="PoseFingerprint.pose_score",
                )
            )
        )

        if (
            self.pose_result is not None
            and not isinstance(
                self.pose_result,
                PoseScoringResult,
            )
        ):
            raise DiversityValidationError(
                "pose_result must be a PoseScoringResult or None."
            )

        object.__setattr__(
            self,
            "pose_id",
            _coerce_identifier(self.pose_id),
        )
        object.__setattr__(
            self,
            "model_id",
            _coerce_identifier(self.model_id),
        )
        object.__setattr__(
            self,
            "ligand_id",
            _coerce_identifier(self.ligand_id),
        )
        object.__setattr__(
            self,
            "kind",
            normalize_fingerprint_kind(self.kind),
        )
        object.__setattr__(
            self,
            "value_mode",
            normalize_fingerprint_value_mode(
                self.value_mode
            ),
        )
        object.__setattr__(
            self,
            "values",
            MappingProxyType(normalized_values),
        )
        object.__setattr__(
            self,
            "feature_count",
            feature_count,
        )
        object.__setattr__(
            self,
            "active_feature_count",
            active_feature_count,
        )
        object.__setattr__(
            self,
            "total_value",
            total_value,
        )
        object.__setattr__(
            self,
            "vector_norm",
            vector_norm,
        )
        object.__setattr__(
            self,
            "pose_score",
            pose_score,
        )
        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(self.metadata),
        )

    @property
    def features(self) -> Tuple[str, ...]:
        """
        Return feature names in deterministic order.
        """

        return tuple(self.values)

    @property
    def active_features(self) -> Tuple[str, ...]:
        """
        Return non-zero feature names.
        """

        return tuple(
            key
            for key, value in self.values.items()
            if abs(value) > DEFAULT_DIVERSITY_EPSILON
        )

    @property
    def empty(self) -> bool:
        """
        Return whether the fingerprint has no active features.
        """

        return self.active_feature_count == 0

    def value(
        self,
        feature: str,
        default: float = 0.0,
    ) -> float:
        """
        Return a feature value.
        """

        return float(
            self.values.get(
                _coerce_identifier(feature),
                default,
            )
        )

    def to_dense_vector(
        self,
        vocabulary: Sequence[str],
    ) -> Tuple[float, ...]:
        """
        Convert the sparse fingerprint to a dense vector.
        """

        return tuple(
            float(self.values.get(feature, 0.0))
            for feature in vocabulary
        )

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
        include_pose_result: bool = False,
    ) -> Dict[str, Any]:
        """
        Return a serializable fingerprint representation.
        """

        result: Dict[str, Any] = {
            "pose_id": self.pose_id,
            "model_id": self.model_id,
            "ligand_id": self.ligand_id,
            "kind": self.kind,
            "value_mode": self.value_mode,
            "values": dict(self.values),
            "features": list(self.features),
            "active_features": list(self.active_features),
            "feature_count": self.feature_count,
            "active_feature_count": (
                self.active_feature_count
            ),
            "total_value": self.total_value,
            "vector_norm": self.vector_norm,
            "pose_score": self.pose_score,
            "empty": self.empty,
        }

        if include_pose_result:
            result["pose_result"] = (
                None
                if self.pose_result is None
                else self.pose_result.to_dict(
                    include_metadata=include_metadata,
                    include_collection_result=False,
                )
            )

        if include_metadata:
            result["metadata"] = dict(self.metadata)

        return result


# -----------------------------------------------------------------------------
# 18.7. Pairwise diversity result
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class PosePairDiversity:
    """
    Pairwise similarity and distance between two pose fingerprints.
    """

    pose_id_a: str
    pose_id_b: str

    similarity_metric: str
    distance_metric: str

    similarity: float
    distance: float

    shared_feature_count: int
    union_feature_count: int
    exclusive_feature_count_a: int
    exclusive_feature_count_b: int

    shared_features: Tuple[str, ...] = field(
        default_factory=tuple
    )
    exclusive_features_a: Tuple[str, ...] = field(
        default_factory=tuple
    )
    exclusive_features_b: Tuple[str, ...] = field(
        default_factory=tuple
    )

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize pairwise diversity values.
        """

        for field_name in (
            "similarity",
            "distance",
        ):
            object.__setattr__(
                self,
                field_name,
                float(
                    _coerce_finite_score_value(
                        getattr(self, field_name),
                        name=f"PosePairDiversity.{field_name}",
                    )
                ),
            )

        for field_name in (
            "shared_feature_count",
            "union_feature_count",
            "exclusive_feature_count_a",
            "exclusive_feature_count_b",
        ):
            value = int(getattr(self, field_name))

            if value < 0:
                raise DiversityValidationError(
                    f"{field_name} cannot be negative."
                )

            object.__setattr__(
                self,
                field_name,
                value,
            )

        object.__setattr__(
            self,
            "pose_id_a",
            _coerce_identifier(self.pose_id_a),
        )
        object.__setattr__(
            self,
            "pose_id_b",
            _coerce_identifier(self.pose_id_b),
        )
        object.__setattr__(
            self,
            "similarity_metric",
            normalize_similarity_metric(
                self.similarity_metric
            ),
        )
        object.__setattr__(
            self,
            "distance_metric",
            normalize_distance_metric(
                self.distance_metric
            ),
        )
        object.__setattr__(
            self,
            "shared_features",
            tuple(sorted(set(self.shared_features))),
        )
        object.__setattr__(
            self,
            "exclusive_features_a",
            tuple(
                sorted(set(self.exclusive_features_a))
            ),
        )
        object.__setattr__(
            self,
            "exclusive_features_b",
            tuple(
                sorted(set(self.exclusive_features_b))
            ),
        )
        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(self.metadata),
        )

    @property
    def identical(self) -> bool:
        """
        Return whether the pair has zero distance.
        """

        return (
            abs(self.distance)
            <= DEFAULT_DIVERSITY_EPSILON
        )

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
    ) -> Dict[str, Any]:
        """
        Return a serializable pair representation.
        """

        result: Dict[str, Any] = {
            "pose_id_a": self.pose_id_a,
            "pose_id_b": self.pose_id_b,
            "similarity_metric": self.similarity_metric,
            "distance_metric": self.distance_metric,
            "similarity": self.similarity,
            "distance": self.distance,
            "identical": self.identical,
            "shared_feature_count": (
                self.shared_feature_count
            ),
            "union_feature_count": self.union_feature_count,
            "exclusive_feature_count_a": (
                self.exclusive_feature_count_a
            ),
            "exclusive_feature_count_b": (
                self.exclusive_feature_count_b
            ),
            "shared_features": list(self.shared_features),
            "exclusive_features_a": list(
                self.exclusive_features_a
            ),
            "exclusive_features_b": list(
                self.exclusive_features_b
            ),
        }

        if include_metadata:
            result["metadata"] = dict(self.metadata)

        return result


# -----------------------------------------------------------------------------
# 18.8. Per-pose diversity summary
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class PoseDiversityScore:
    """
    Diversity summary of one pose relative to all other poses.
    """

    pose_id: str
    model_id: str
    ligand_id: str

    mean_similarity: float
    mean_distance: float

    minimum_distance: float
    maximum_distance: float
    median_distance: float

    nearest_pose_id: str
    nearest_pose_distance: float

    farthest_pose_id: str
    farthest_pose_distance: float

    diversity_rank: Optional[int] = None
    representative: bool = False
    representative_order: Optional[int] = None

    pose_score: Optional[float] = None

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize per-pose diversity values.
        """

        for field_name in (
            "mean_similarity",
            "mean_distance",
            "minimum_distance",
            "maximum_distance",
            "median_distance",
            "nearest_pose_distance",
            "farthest_pose_distance",
        ):
            object.__setattr__(
                self,
                field_name,
                float(
                    _coerce_finite_score_value(
                        getattr(self, field_name),
                        name=f"PoseDiversityScore.{field_name}",
                    )
                ),
            )

        diversity_rank = (
            None
            if self.diversity_rank is None
            else int(self.diversity_rank)
        )

        if (
            diversity_rank is not None
            and diversity_rank < 1
        ):
            raise DiversityValidationError(
                "diversity_rank must be positive or None."
            )

        representative_order = (
            None
            if self.representative_order is None
            else int(self.representative_order)
        )

        if (
            representative_order is not None
            and representative_order < 1
        ):
            raise DiversityValidationError(
                "representative_order must be positive or None."
            )

        pose_score = (
            None
            if self.pose_score is None
            else float(
                _coerce_finite_score_value(
                    self.pose_score,
                    name="PoseDiversityScore.pose_score",
                )
            )
        )

        object.__setattr__(
            self,
            "pose_id",
            _coerce_identifier(self.pose_id),
        )
        object.__setattr__(
            self,
            "model_id",
            _coerce_identifier(self.model_id),
        )
        object.__setattr__(
            self,
            "ligand_id",
            _coerce_identifier(self.ligand_id),
        )
        object.__setattr__(
            self,
            "nearest_pose_id",
            _coerce_identifier(
                self.nearest_pose_id
            ),
        )
        object.__setattr__(
            self,
            "farthest_pose_id",
            _coerce_identifier(
                self.farthest_pose_id
            ),
        )
        object.__setattr__(
            self,
            "diversity_rank",
            diversity_rank,
        )
        object.__setattr__(
            self,
            "representative",
            bool(self.representative),
        )
        object.__setattr__(
            self,
            "representative_order",
            representative_order,
        )
        object.__setattr__(
            self,
            "pose_score",
            pose_score,
        )
        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(self.metadata),
        )

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
    ) -> Dict[str, Any]:
        """
        Return a serializable per-pose diversity summary.
        """

        result: Dict[str, Any] = {
            "pose_id": self.pose_id,
            "model_id": self.model_id,
            "ligand_id": self.ligand_id,
            "mean_similarity": self.mean_similarity,
            "mean_distance": self.mean_distance,
            "minimum_distance": self.minimum_distance,
            "maximum_distance": self.maximum_distance,
            "median_distance": self.median_distance,
            "nearest_pose_id": self.nearest_pose_id,
            "nearest_pose_distance": (
                self.nearest_pose_distance
            ),
            "farthest_pose_id": self.farthest_pose_id,
            "farthest_pose_distance": (
                self.farthest_pose_distance
            ),
            "diversity_rank": self.diversity_rank,
            "representative": self.representative,
            "representative_order": (
                self.representative_order
            ),
            "pose_score": self.pose_score,
        }

        if include_metadata:
            result["metadata"] = dict(self.metadata)

        return result


# -----------------------------------------------------------------------------
# 18.9. Diversity summary
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class DiversitySummary:
    """
    Global summary of a pose-diversity analysis.
    """

    pose_count: int
    pair_count: int
    feature_count: int

    mean_similarity: float
    mean_distance: float

    minimum_distance: float
    maximum_distance: float
    median_distance: float

    identical_pair_count: int
    unique_fingerprint_count: int

    most_central_pose_id: str = ""
    most_diverse_pose_id: str = ""
    most_similar_pair: Tuple[str, str] = field(
        default_factory=tuple
    )
    most_dissimilar_pair: Tuple[str, str] = field(
        default_factory=tuple
    )

    representative_pose_ids: Tuple[str, ...] = field(
        default_factory=tuple
    )

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize global diversity-summary values.
        """

        for field_name in (
            "pose_count",
            "pair_count",
            "feature_count",
            "identical_pair_count",
            "unique_fingerprint_count",
        ):
            value = int(getattr(self, field_name))

            if value < 0:
                raise DiversityValidationError(
                    f"{field_name} cannot be negative."
                )

            object.__setattr__(
                self,
                field_name,
                value,
            )

        for field_name in (
            "mean_similarity",
            "mean_distance",
            "minimum_distance",
            "maximum_distance",
            "median_distance",
        ):
            object.__setattr__(
                self,
                field_name,
                float(
                    _coerce_finite_score_value(
                        getattr(self, field_name),
                        name=f"DiversitySummary.{field_name}",
                    )
                ),
            )

        object.__setattr__(
            self,
            "most_central_pose_id",
            _coerce_identifier(
                self.most_central_pose_id
            ),
        )
        object.__setattr__(
            self,
            "most_diverse_pose_id",
            _coerce_identifier(
                self.most_diverse_pose_id
            ),
        )
        object.__setattr__(
            self,
            "most_similar_pair",
            tuple(
                _coerce_identifier(value)
                for value in self.most_similar_pair
            ),
        )
        object.__setattr__(
            self,
            "most_dissimilar_pair",
            tuple(
                _coerce_identifier(value)
                for value in self.most_dissimilar_pair
            ),
        )
        object.__setattr__(
            self,
            "representative_pose_ids",
            tuple(
                _coerce_identifier(value)
                for value in self.representative_pose_ids
            ),
        )
        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(self.metadata),
        )

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
    ) -> Dict[str, Any]:
        """
        Return a serializable summary.
        """

        result: Dict[str, Any] = {
            "pose_count": self.pose_count,
            "pair_count": self.pair_count,
            "feature_count": self.feature_count,
            "mean_similarity": self.mean_similarity,
            "mean_distance": self.mean_distance,
            "minimum_distance": self.minimum_distance,
            "maximum_distance": self.maximum_distance,
            "median_distance": self.median_distance,
            "identical_pair_count": (
                self.identical_pair_count
            ),
            "unique_fingerprint_count": (
                self.unique_fingerprint_count
            ),
            "most_central_pose_id": (
                self.most_central_pose_id
            ),
            "most_diverse_pose_id": (
                self.most_diverse_pose_id
            ),
            "most_similar_pair": list(
                self.most_similar_pair
            ),
            "most_dissimilar_pair": list(
                self.most_dissimilar_pair
            ),
            "representative_pose_ids": list(
                self.representative_pose_ids
            ),
        }

        if include_metadata:
            result["metadata"] = dict(self.metadata)

        return result


# -----------------------------------------------------------------------------
# 18.10. PoseDiversityResult
# -----------------------------------------------------------------------------

@dataclass(frozen=True, slots=True)
class PoseDiversityResult:
    """
    Complete diversity-analysis result for multiple docking poses.
    """

    status: str

    fingerprints: Tuple[PoseFingerprint, ...]
    pairs: Tuple[PosePairDiversity, ...]
    pose_scores: Tuple[PoseDiversityScore, ...]

    similarity_matrix: Tuple[Tuple[float, ...], ...]
    distance_matrix: Tuple[Tuple[float, ...], ...]

    vocabulary: Tuple[str, ...]
    summary: DiversitySummary

    similarity_metric: str
    distance_metric: str

    message: str = ""

    metadata: Mapping[str, Any] = field(
        default_factory=lambda: _EMPTY_METADATA,
        compare=False,
        hash=False,
        repr=False,
    )

    def __post_init__(self) -> None:
        """
        Normalize a complete diversity result.
        """

        fingerprints = tuple(self.fingerprints)
        pairs = tuple(self.pairs)
        pose_scores = tuple(self.pose_scores)

        for fingerprint in fingerprints:
            if not isinstance(
                fingerprint,
                PoseFingerprint,
            ):
                raise DiversityValidationError(
                    "fingerprints must contain PoseFingerprint objects."
                )

        for pair in pairs:
            if not isinstance(pair, PosePairDiversity):
                raise DiversityValidationError(
                    "pairs must contain PosePairDiversity objects."
                )

        for pose_score in pose_scores:
            if not isinstance(
                pose_score,
                PoseDiversityScore,
            ):
                raise DiversityValidationError(
                    "pose_scores must contain PoseDiversityScore objects."
                )

        if not isinstance(self.summary, DiversitySummary):
            raise DiversityValidationError(
                "summary must be a DiversitySummary."
            )

        similarity_matrix = tuple(
            tuple(float(value) for value in row)
            for row in self.similarity_matrix
        )
        distance_matrix = tuple(
            tuple(float(value) for value in row)
            for row in self.distance_matrix
        )

        object.__setattr__(
            self,
            "status",
            normalize_diversity_status(self.status),
        )
        object.__setattr__(
            self,
            "fingerprints",
            fingerprints,
        )
        object.__setattr__(
            self,
            "pairs",
            pairs,
        )
        object.__setattr__(
            self,
            "pose_scores",
            pose_scores,
        )
        object.__setattr__(
            self,
            "similarity_matrix",
            similarity_matrix,
        )
        object.__setattr__(
            self,
            "distance_matrix",
            distance_matrix,
        )
        object.__setattr__(
            self,
            "vocabulary",
            tuple(sorted(set(self.vocabulary))),
        )
        object.__setattr__(
            self,
            "similarity_metric",
            normalize_similarity_metric(
                self.similarity_metric
            ),
        )
        object.__setattr__(
            self,
            "distance_metric",
            normalize_distance_metric(
                self.distance_metric
            ),
        )
        object.__setattr__(
            self,
            "message",
            _coerce_optional_text(self.message),
        )
        object.__setattr__(
            self,
            "metadata",
            _freeze_result_metadata(self.metadata),
        )

    @property
    def pose_ids(self) -> Tuple[str, ...]:
        """
        Return pose identifiers in matrix order.
        """

        return tuple(
            fingerprint.pose_id
            for fingerprint in self.fingerprints
        )

    @property
    def representatives(self) -> Tuple[PoseDiversityScore, ...]:
        """
        Return selected representative poses.
        """

        return tuple(
            pose_score
            for pose_score in self.pose_scores
            if pose_score.representative
        )

    def to_dict(
        self,
        *,
        include_metadata: bool = True,
        include_pose_results: bool = False,
    ) -> Dict[str, Any]:
        """
        Return a serializable diversity-analysis result.
        """

        result: Dict[str, Any] = {
            "status": self.status,
            "message": self.message,
            "pose_ids": list(self.pose_ids),
            "similarity_metric": self.similarity_metric,
            "distance_metric": self.distance_metric,
            "vocabulary": list(self.vocabulary),
            "fingerprints": [
                fingerprint.to_dict(
                    include_metadata=include_metadata,
                    include_pose_result=include_pose_results,
                )
                for fingerprint in self.fingerprints
            ],
            "pairs": [
                pair.to_dict(
                    include_metadata=include_metadata
                )
                for pair in self.pairs
            ],
            "pose_scores": [
                pose_score.to_dict(
                    include_metadata=include_metadata
                )
                for pose_score in self.pose_scores
            ],
            "similarity_matrix": [
                list(row)
                for row in self.similarity_matrix
            ],
            "distance_matrix": [
                list(row)
                for row in self.distance_matrix
            ],
            "summary": self.summary.to_dict(
                include_metadata=include_metadata
            ),
        }

        if include_metadata:
            result["metadata"] = dict(self.metadata)

        return result


# -----------------------------------------------------------------------------
# 18.11. Fingerprint feature construction
# -----------------------------------------------------------------------------

def interaction_fingerprint_feature(
    score: InteractionScore,
) -> str:
    """
    Build a stable feature identifier for one interaction.
    """

    residue_pair = tuple(
        sorted(
            residue
            for residue in score.residue_pair
            if residue
        )
    )

    residue_fragment = (
        "|".join(residue_pair)
        if residue_pair
        else "unknown_pair"
    )

    return (
        f"interaction:"
        f"{score.interaction_family}:"
        f"{score.interaction_type}:"
        f"{residue_fragment}"
    )


def residue_fingerprint_feature(
    residue: ResidueIdentity,
) -> str:
    """
    Build a stable feature identifier for one residue.
    """

    return f"residue:{residue.residue_id}"


def family_fingerprint_feature(
    interaction_family: str,
) -> str:
    """
    Build a family-level fingerprint feature.
    """

    return (
        "family:"
        f"{canonical_interaction_family(interaction_family)}"
    )


def type_fingerprint_feature(
    interaction_type: str,
) -> str:
    """
    Build an interaction-type fingerprint feature.
    """

    return (
        "type:"
        f"{normalize_interaction_type(interaction_type, preserve_unknown=True)}"
    )


def hotspot_fingerprint_feature(
    residue_score: ResidueScore,
) -> str:
    """
    Build a hotspot-level fingerprint feature.
    """

    return f"hotspot:{residue_score.residue_id}"


def interaction_fingerprint_value(
    score: InteractionScore,
    *,
    options: FingerprintOptions,
) -> float:
    """
    Resolve one interaction's fingerprint contribution.
    """

    mode = options.value_mode

    if mode == FINGERPRINT_VALUE_BINARY:
        return 1.0

    if mode == FINGERPRINT_VALUE_COUNT:
        return 1.0

    if mode == FINGERPRINT_VALUE_SCORE:
        return float(score.final_score)

    if mode == FINGERPRINT_VALUE_ABSOLUTE_SCORE:
        return abs(float(score.final_score))

    if mode == FINGERPRINT_VALUE_WEIGHTED_SCORE:
        family_weight = options.family_weights.get(
            score.interaction_family,
            1.0,
        )
        type_weight = options.type_weights.get(
            score.interaction_type,
            1.0,
        )

        return float(
            score.final_score
            * family_weight
            * type_weight
        )

    raise FingerprintError(
        f"Unsupported fingerprint value mode: {mode!r}."
    )


def aggregate_fingerprint_feature_value(
    current: float,
    contribution: float,
    *,
    value_mode: str,
) -> float:
    """
    Aggregate repeated contributions to the same feature.
    """

    normalized_mode = normalize_fingerprint_value_mode(
        value_mode
    )

    if normalized_mode == FINGERPRINT_VALUE_BINARY:
        return 1.0

    return current + contribution


def include_score_in_fingerprint(
    score: InteractionScore,
    *,
    options: FingerprintOptions,
) -> bool:
    """
    Return whether an interaction score passes the threshold.
    """

    threshold = abs(options.score_threshold)

    if threshold <= DEFAULT_DIVERSITY_EPSILON:
        return True

    if (
        options.value_mode
        == FINGERPRINT_VALUE_ABSOLUTE_SCORE
    ):
        return abs(score.final_score) >= threshold

    return abs(score.final_score) >= threshold


def include_residue_in_fingerprint(
    residue: ResidueIdentity,
    *,
    options: FingerprintOptions,
) -> bool:
    """
    Return whether a residue should contribute to a fingerprint.
    """

    side = normalize_residue_side(residue.side)

    if (
        side == RESIDUE_SIDE_LIGAND
        and not options.include_ligand_residues
    ):
        return False

    if (
        side == RESIDUE_SIDE_UNKNOWN
        and not options.include_unknown_residues
    ):
        return False

    return True


# -----------------------------------------------------------------------------
# 18.12. Fingerprint generation
# -----------------------------------------------------------------------------

def build_pose_fingerprint_values(
    pose_result: PoseScoringResult,
    *,
    options: FingerprintOptions = (
        DEFAULT_FINGERPRINT_OPTIONS
    ),
) -> Mapping[str, float]:
    """
    Build sparse fingerprint feature values for one pose.
    """

    validate_pose_scoring_result(pose_result)
    validate_fingerprint_options(options)

    features: Dict[str, float] = {}

    def add_feature(
        feature: str,
        contribution: float,
    ) -> None:
        normalized_feature = _coerce_identifier(feature)

        if not normalized_feature:
            return

        if (
            not options.include_zero_values
            and abs(contribution)
            <= DEFAULT_DIVERSITY_EPSILON
        ):
            return

        current = features.get(normalized_feature, 0.0)

        features[normalized_feature] = (
            aggregate_fingerprint_feature_value(
                current,
                contribution,
                value_mode=options.value_mode,
            )
        )

    scores = tuple(
        score
        for score in pose_result.scores
        if include_score_in_fingerprint(
            score,
            options=options,
        )
    )

    if options.kind in {
        FINGERPRINT_KIND_INTERACTION,
        FINGERPRINT_KIND_COMBINED,
    }:
        for score in scores:
            add_feature(
                interaction_fingerprint_feature(score),
                interaction_fingerprint_value(
                    score,
                    options=options,
                ),
            )

    if options.kind in {
        FINGERPRINT_KIND_FAMILY,
        FINGERPRINT_KIND_COMBINED,
    }:
        for score in scores:
            add_feature(
                family_fingerprint_feature(
                    score.interaction_family
                ),
                interaction_fingerprint_value(
                    score,
                    options=options,
                ),
            )

    if options.kind in {
        FINGERPRINT_KIND_TYPE,
        FINGERPRINT_KIND_COMBINED,
    }:
        for score in scores:
            add_feature(
                type_fingerprint_feature(
                    score.interaction_type
                ),
                interaction_fingerprint_value(
                    score,
                    options=options,
                ),
            )

    if options.kind in {
        FINGERPRINT_KIND_RESIDUE,
        FINGERPRINT_KIND_COMBINED,
    }:
        residue_result = pose_result.residue_result

        if residue_result is None:
            residue_result = aggregate_scores_by_residue(
                scores,
                options=ResidueAggregationOptions(
                    include_ligand_residues=(
                        options.include_ligand_residues
                    ),
                    include_unknown_residues=(
                        options.include_unknown_residues
                    ),
                ),
            )

        for residue_score in residue_result.residues:
            residue = residue_score.residue

            if not include_residue_in_fingerprint(
                residue,
                options=options,
            ):
                continue

            if options.value_mode == FINGERPRINT_VALUE_BINARY:
                value = 1.0

            elif options.value_mode == FINGERPRINT_VALUE_COUNT:
                value = float(
                    residue_score.interaction_count
                )

            elif options.value_mode == FINGERPRINT_VALUE_SCORE:
                value = float(residue_score.final_score)

            elif (
                options.value_mode
                == FINGERPRINT_VALUE_ABSOLUTE_SCORE
            ):
                value = abs(
                    float(residue_score.final_score)
                )

            else:
                value = float(residue_score.final_score)

            add_feature(
                residue_fingerprint_feature(residue),
                value,
            )

    if options.kind in {
        FINGERPRINT_KIND_HOTSPOT,
        FINGERPRINT_KIND_COMBINED,
    }:
        residue_result = pose_result.residue_result

        if residue_result is None:
            residue_result = aggregate_scores_by_residue(
                scores,
                options=ResidueAggregationOptions(
                    include_ligand_residues=(
                        options.include_ligand_residues
                    ),
                    include_unknown_residues=(
                        options.include_unknown_residues
                    ),
                ),
            )

        hotspots = residue_result.hotspots

        if options.hotspot_limit is not None:
            hotspots = hotspots[:options.hotspot_limit]

        for hotspot in hotspots:
            if not include_residue_in_fingerprint(
                hotspot.residue,
                options=options,
            ):
                continue

            if options.value_mode == FINGERPRINT_VALUE_BINARY:
                value = 1.0

            elif options.value_mode == FINGERPRINT_VALUE_COUNT:
                value = float(hotspot.interaction_count)

            elif options.value_mode == FINGERPRINT_VALUE_SCORE:
                value = float(hotspot.final_score)

            elif (
                options.value_mode
                == FINGERPRINT_VALUE_ABSOLUTE_SCORE
            ):
                value = abs(float(hotspot.final_score))

            else:
                value = float(hotspot.final_score)

            add_feature(
                hotspot_fingerprint_feature(hotspot),
                value,
            )

    if options.normalize_values and features:
        norm = math.sqrt(
            sum(
                value * value
                for value in features.values()
            )
        )

        if norm > DEFAULT_DIVERSITY_EPSILON:
            features = {
                feature: value / norm
                for feature, value in features.items()
            }

    if not options.include_zero_values:
        features = {
            feature: value
            for feature, value in features.items()
            if abs(value) > DEFAULT_DIVERSITY_EPSILON
        }

    return MappingProxyType(
        dict(sorted(features.items()))
    )


def build_pose_fingerprint(
    pose_result: PoseScoringResult,
    *,
    options: FingerprintOptions = (
        DEFAULT_FINGERPRINT_OPTIONS
    ),
    preserve_pose_result: bool = (
        DEFAULT_PRESERVE_POSE_RESULTS
    ),
) -> PoseFingerprint:
    """
    Build a sparse fingerprint for one scored pose.
    """

    values = build_pose_fingerprint_values(
        pose_result,
        options=options,
    )

    active_feature_count = sum(
        abs(value) > DEFAULT_DIVERSITY_EPSILON
        for value in values.values()
    )

    vector_norm = math.sqrt(
        sum(
            value * value
            for value in values.values()
        )
    )

    fingerprint = PoseFingerprint(
        pose_id=pose_result.pose_id,
        model_id=pose_result.model_id,
        ligand_id=pose_result.ligand_id,
        kind=options.kind,
        value_mode=options.value_mode,
        values=values,
        feature_count=len(values),
        active_feature_count=active_feature_count,
        total_value=float(sum(values.values())),
        vector_norm=float(vector_norm),
        pose_score=pose_result.final_score,
        pose_result=(
            pose_result
            if preserve_pose_result
            else None
        ),
        metadata={
            "interaction_count": (
                pose_result.summary.interaction_count
            ),
            "residue_count": (
                pose_result.summary.residue_count
            ),
            "hotspot_count": (
                pose_result.summary.hotspot_count
            ),
        },
    )

    validate_pose_fingerprint(fingerprint)

    return fingerprint


def build_pose_fingerprints(
    pose_results: Iterable[PoseScoringResult],
    *,
    options: FingerprintOptions = (
        DEFAULT_FINGERPRINT_OPTIONS
    ),
    preserve_pose_results: bool = (
        DEFAULT_PRESERVE_POSE_RESULTS
    ),
) -> Tuple[PoseFingerprint, ...]:
    """
    Build deterministic fingerprints for multiple poses.
    """

    normalized_pose_results = (
        materialize_pose_scoring_results(
            pose_results
        )
    )

    fingerprints = tuple(
        build_pose_fingerprint(
            pose_result,
            options=options,
            preserve_pose_result=preserve_pose_results,
        )
        for pose_result in normalized_pose_results
    )

    return tuple(
        sorted(
            fingerprints,
            key=lambda fingerprint: (
                fingerprint.pose_id,
                fingerprint.model_id,
                fingerprint.ligand_id,
            ),
        )
    )


# -----------------------------------------------------------------------------
# 18.13. Fingerprint vocabulary and dense vectors
# -----------------------------------------------------------------------------

def build_fingerprint_vocabulary(
    fingerprints: Iterable[PoseFingerprint],
) -> Tuple[str, ...]:
    """
    Build the union of all fingerprint features.
    """

    vocabulary: Set[str] = set()

    for fingerprint in fingerprints:
        validate_pose_fingerprint(fingerprint)
        vocabulary.update(fingerprint.values)

    return tuple(sorted(vocabulary))


def align_fingerprint_vectors(
    fingerprint_a: PoseFingerprint,
    fingerprint_b: PoseFingerprint,
    *,
    vocabulary: Optional[Sequence[str]] = None,
) -> Tuple[
    Tuple[str, ...],
    Tuple[float, ...],
    Tuple[float, ...],
]:
    """
    Align two sparse fingerprints to the same dense vocabulary.
    """

    validate_pose_fingerprint(fingerprint_a)
    validate_pose_fingerprint(fingerprint_b)

    if vocabulary is None:
        resolved_vocabulary = tuple(
            sorted(
                set(fingerprint_a.values)
                | set(fingerprint_b.values)
            )
        )
    else:
        resolved_vocabulary = tuple(vocabulary)

    return (
        resolved_vocabulary,
        fingerprint_a.to_dense_vector(
            resolved_vocabulary
        ),
        fingerprint_b.to_dense_vector(
            resolved_vocabulary
        ),
    )


def fingerprint_active_feature_set(
    fingerprint: PoseFingerprint,
    *,
    epsilon: float = DEFAULT_DIVERSITY_EPSILON,
) -> FrozenSet[str]:
    """
    Return active binary features of a fingerprint.
    """

    return frozenset(
        feature
        for feature, value in fingerprint.values.items()
        if abs(value) > epsilon
    )


# -----------------------------------------------------------------------------
# 18.14. Similarity metrics
# -----------------------------------------------------------------------------

def jaccard_similarity(
    fingerprint_a: PoseFingerprint,
    fingerprint_b: PoseFingerprint,
    *,
    epsilon: float = DEFAULT_DIVERSITY_EPSILON,
) -> float:
    """
    Calculate binary Jaccard similarity.
    """

    features_a = fingerprint_active_feature_set(
        fingerprint_a,
        epsilon=epsilon,
    )
    features_b = fingerprint_active_feature_set(
        fingerprint_b,
        epsilon=epsilon,
    )

    union = features_a | features_b

    if not union:
        return 1.0

    intersection = features_a & features_b

    return len(intersection) / len(union)


def dice_similarity(
    fingerprint_a: PoseFingerprint,
    fingerprint_b: PoseFingerprint,
    *,
    epsilon: float = DEFAULT_DIVERSITY_EPSILON,
) -> float:
    """
    Calculate the Sørensen–Dice similarity coefficient.
    """

    features_a = fingerprint_active_feature_set(
        fingerprint_a,
        epsilon=epsilon,
    )
    features_b = fingerprint_active_feature_set(
        fingerprint_b,
        epsilon=epsilon,
    )

    denominator = len(features_a) + len(features_b)

    if denominator == 0:
        return 1.0

    return (
        2.0
        * len(features_a & features_b)
        / denominator
    )


def overlap_similarity(
    fingerprint_a: PoseFingerprint,
    fingerprint_b: PoseFingerprint,
    *,
    epsilon: float = DEFAULT_DIVERSITY_EPSILON,
) -> float:
    """
    Calculate the overlap coefficient.
    """

    features_a = fingerprint_active_feature_set(
        fingerprint_a,
        epsilon=epsilon,
    )
    features_b = fingerprint_active_feature_set(
        fingerprint_b,
        epsilon=epsilon,
    )

    minimum_size = min(
        len(features_a),
        len(features_b),
    )

    if minimum_size == 0:
        return (
            1.0
            if not features_a and not features_b
            else 0.0
        )

    return (
        len(features_a & features_b)
        / minimum_size
    )


def cosine_similarity(
    fingerprint_a: PoseFingerprint,
    fingerprint_b: PoseFingerprint,
    *,
    epsilon: float = DEFAULT_DIVERSITY_EPSILON,
) -> float:
    """
    Calculate cosine similarity between numerical fingerprints.
    """

    _, vector_a, vector_b = align_fingerprint_vectors(
        fingerprint_a,
        fingerprint_b,
    )

    dot_product = sum(
        value_a * value_b
        for value_a, value_b
        in zip(vector_a, vector_b)
    )
    norm_a = math.sqrt(
        sum(value * value for value in vector_a)
    )
    norm_b = math.sqrt(
        sum(value * value for value in vector_b)
    )

    denominator = norm_a * norm_b

    if denominator <= epsilon:
        return (
            1.0
            if norm_a <= epsilon and norm_b <= epsilon
            else 0.0
        )

    similarity = dot_product / denominator

    return max(-1.0, min(1.0, similarity))


def tanimoto_similarity(
    fingerprint_a: PoseFingerprint,
    fingerprint_b: PoseFingerprint,
    *,
    epsilon: float = DEFAULT_DIVERSITY_EPSILON,
) -> float:
    """
    Calculate continuous Tanimoto similarity.
    """

    _, vector_a, vector_b = align_fingerprint_vectors(
        fingerprint_a,
        fingerprint_b,
    )

    dot_product = sum(
        value_a * value_b
        for value_a, value_b
        in zip(vector_a, vector_b)
    )
    squared_norm_a = sum(
        value * value
        for value in vector_a
    )
    squared_norm_b = sum(
        value * value
        for value in vector_b
    )

    denominator = (
        squared_norm_a
        + squared_norm_b
        - dot_product
    )

    if abs(denominator) <= epsilon:
        return (
            1.0
            if squared_norm_a <= epsilon
            and squared_norm_b <= epsilon
            else 0.0
        )

    return dot_product / denominator


def fingerprint_similarity(
    fingerprint_a: PoseFingerprint,
    fingerprint_b: PoseFingerprint,
    *,
    metric: str = DEFAULT_SIMILARITY_METRIC,
    epsilon: float = DEFAULT_DIVERSITY_EPSILON,
) -> float:
    """
    Calculate similarity using the selected metric.
    """

    normalized_metric = normalize_similarity_metric(
        metric
    )

    if normalized_metric == SIMILARITY_JACCARD:
        return jaccard_similarity(
            fingerprint_a,
            fingerprint_b,
            epsilon=epsilon,
        )

    if normalized_metric == SIMILARITY_DICE:
        return dice_similarity(
            fingerprint_a,
            fingerprint_b,
            epsilon=epsilon,
        )

    if normalized_metric == SIMILARITY_COSINE:
        return cosine_similarity(
            fingerprint_a,
            fingerprint_b,
            epsilon=epsilon,
        )

    if normalized_metric == SIMILARITY_OVERLAP:
        return overlap_similarity(
            fingerprint_a,
            fingerprint_b,
            epsilon=epsilon,
        )

    if normalized_metric == SIMILARITY_TANIMOTO:
        return tanimoto_similarity(
            fingerprint_a,
            fingerprint_b,
            epsilon=epsilon,
        )

    raise SimilarityMetricError(
        f"Unsupported similarity metric: {normalized_metric!r}."
    )


# -----------------------------------------------------------------------------
# 18.15. Distance metrics
# -----------------------------------------------------------------------------

def hamming_distance(
    fingerprint_a: PoseFingerprint,
    fingerprint_b: PoseFingerprint,
    *,
    epsilon: float = DEFAULT_DIVERSITY_EPSILON,
) -> float:
    """
    Calculate normalized binary Hamming distance.
    """

    vocabulary, vector_a, vector_b = (
        align_fingerprint_vectors(
            fingerprint_a,
            fingerprint_b,
        )
    )

    if not vocabulary:
        return 0.0

    mismatch_count = sum(
        (
            abs(value_a) > epsilon
        )
        != (
            abs(value_b) > epsilon
        )
        for value_a, value_b
        in zip(vector_a, vector_b)
    )

    return mismatch_count / len(vocabulary)


def euclidean_distance(
    fingerprint_a: PoseFingerprint,
    fingerprint_b: PoseFingerprint,
) -> float:
    """
    Calculate Euclidean distance between numerical fingerprints.
    """

    _, vector_a, vector_b = align_fingerprint_vectors(
        fingerprint_a,
        fingerprint_b,
    )

    return math.sqrt(
        sum(
            (value_a - value_b) ** 2
            for value_a, value_b
            in zip(vector_a, vector_b)
        )
    )


def manhattan_distance(
    fingerprint_a: PoseFingerprint,
    fingerprint_b: PoseFingerprint,
) -> float:
    """
    Calculate Manhattan distance between numerical fingerprints.
    """

    _, vector_a, vector_b = align_fingerprint_vectors(
        fingerprint_a,
        fingerprint_b,
    )

    return sum(
        abs(value_a - value_b)
        for value_a, value_b
        in zip(vector_a, vector_b)
    )


def fingerprint_distance(
    fingerprint_a: PoseFingerprint,
    fingerprint_b: PoseFingerprint,
    *,
    distance_metric: str = DEFAULT_DISTANCE_METRIC,
    similarity_metric: str = DEFAULT_SIMILARITY_METRIC,
    epsilon: float = DEFAULT_DIVERSITY_EPSILON,
) -> float:
    """
    Calculate fingerprint distance using the selected metric.
    """

    normalized_distance_metric = normalize_distance_metric(
        distance_metric
    )

    if normalized_distance_metric == DISTANCE_COMPLEMENT:
        similarity = fingerprint_similarity(
            fingerprint_a,
            fingerprint_b,
            metric=similarity_metric,
            epsilon=epsilon,
        )

        if (
            normalize_similarity_metric(similarity_metric)
            == SIMILARITY_COSINE
        ):
            return (1.0 - similarity) / 2.0

        return 1.0 - similarity

    if normalized_distance_metric == DISTANCE_HAMMING:
        return hamming_distance(
            fingerprint_a,
            fingerprint_b,
            epsilon=epsilon,
        )

    if normalized_distance_metric == DISTANCE_EUCLIDEAN:
        return euclidean_distance(
            fingerprint_a,
            fingerprint_b,
        )

    if normalized_distance_metric == DISTANCE_MANHATTAN:
        return manhattan_distance(
            fingerprint_a,
            fingerprint_b,
        )

    raise DistanceMetricError(
        f"Unsupported distance metric: "
        f"{normalized_distance_metric!r}."
    )


# -----------------------------------------------------------------------------
# 18.16. Pairwise analysis
# -----------------------------------------------------------------------------

def compare_pose_fingerprints(
    fingerprint_a: PoseFingerprint,
    fingerprint_b: PoseFingerprint,
    *,
    similarity_metric: str = DEFAULT_SIMILARITY_METRIC,
    distance_metric: str = DEFAULT_DISTANCE_METRIC,
    epsilon: float = DEFAULT_DIVERSITY_EPSILON,
) -> PosePairDiversity:
    """
    Compare two pose fingerprints.
    """

    features_a = fingerprint_active_feature_set(
        fingerprint_a,
        epsilon=epsilon,
    )
    features_b = fingerprint_active_feature_set(
        fingerprint_b,
        epsilon=epsilon,
    )

    shared_features = tuple(
        sorted(features_a & features_b)
    )
    exclusive_features_a = tuple(
        sorted(features_a - features_b)
    )
    exclusive_features_b = tuple(
        sorted(features_b - features_a)
    )

    similarity = fingerprint_similarity(
        fingerprint_a,
        fingerprint_b,
        metric=similarity_metric,
        epsilon=epsilon,
    )
    distance = fingerprint_distance(
        fingerprint_a,
        fingerprint_b,
        distance_metric=distance_metric,
        similarity_metric=similarity_metric,
        epsilon=epsilon,
    )

    return PosePairDiversity(
        pose_id_a=fingerprint_a.pose_id,
        pose_id_b=fingerprint_b.pose_id,
        similarity_metric=similarity_metric,
        distance_metric=distance_metric,
        similarity=similarity,
        distance=distance,
        shared_feature_count=len(shared_features),
        union_feature_count=len(
            features_a | features_b
        ),
        exclusive_feature_count_a=len(
            exclusive_features_a
        ),
        exclusive_feature_count_b=len(
            exclusive_features_b
        ),
        shared_features=shared_features,
        exclusive_features_a=exclusive_features_a,
        exclusive_features_b=exclusive_features_b,
    )


def compute_pairwise_pose_diversity(
    fingerprints: Sequence[PoseFingerprint],
    *,
    similarity_metric: str = DEFAULT_SIMILARITY_METRIC,
    distance_metric: str = DEFAULT_DISTANCE_METRIC,
    epsilon: float = DEFAULT_DIVERSITY_EPSILON,
) -> Tuple[PosePairDiversity, ...]:
    """
    Calculate all unique pose-pair comparisons.
    """

    pairs: List[PosePairDiversity] = []

    for index_a in range(len(fingerprints)):
        for index_b in range(
            index_a + 1,
            len(fingerprints),
        ):
            pairs.append(
                compare_pose_fingerprints(
                    fingerprints[index_a],
                    fingerprints[index_b],
                    similarity_metric=similarity_metric,
                    distance_metric=distance_metric,
                    epsilon=epsilon,
                )
            )

    return tuple(pairs)


# -----------------------------------------------------------------------------
# 18.17. Similarity and distance matrices
# -----------------------------------------------------------------------------

def compute_diversity_matrices(
    fingerprints: Sequence[PoseFingerprint],
    *,
    similarity_metric: str = DEFAULT_SIMILARITY_METRIC,
    distance_metric: str = DEFAULT_DISTANCE_METRIC,
    epsilon: float = DEFAULT_DIVERSITY_EPSILON,
) -> Tuple[
    Tuple[Tuple[float, ...], ...],
    Tuple[Tuple[float, ...], ...],
]:
    """
    Calculate symmetric similarity and distance matrices.
    """

    count = len(fingerprints)

    similarity_rows: List[List[float]] = [
        [0.0] * count
        for _ in range(count)
    ]
    distance_rows: List[List[float]] = [
        [0.0] * count
        for _ in range(count)
    ]

    for index in range(count):
        similarity_rows[index][index] = 1.0
        distance_rows[index][index] = 0.0

    for index_a in range(count):
        for index_b in range(index_a + 1, count):
            similarity = fingerprint_similarity(
                fingerprints[index_a],
                fingerprints[index_b],
                metric=similarity_metric,
                epsilon=epsilon,
            )
            distance = fingerprint_distance(
                fingerprints[index_a],
                fingerprints[index_b],
                distance_metric=distance_metric,
                similarity_metric=similarity_metric,
                epsilon=epsilon,
            )

            similarity_rows[index_a][index_b] = similarity
            similarity_rows[index_b][index_a] = similarity

            distance_rows[index_a][index_b] = distance
            distance_rows[index_b][index_a] = distance

    return (
        tuple(
            tuple(row)
            for row in similarity_rows
        ),
        tuple(
            tuple(row)
            for row in distance_rows
        ),
    )


def diversity_matrix_mapping(
    pose_ids: Sequence[str],
    matrix: Sequence[Sequence[float]],
) -> Mapping[str, Mapping[str, float]]:
    """
    Convert a square matrix into an immutable nested mapping.
    """

    if len(pose_ids) != len(matrix):
        raise DiversityInputError(
            "pose_ids and matrix dimensions differ."
        )

    result: Dict[str, Mapping[str, float]] = {}

    for row_index, pose_id in enumerate(pose_ids):
        row = matrix[row_index]

        if len(row) != len(pose_ids):
            raise DiversityInputError(
                "The supplied matrix is not square."
            )

        result[pose_id] = MappingProxyType(
            {
                target_pose_id: float(row[column_index])
                for column_index, target_pose_id
                in enumerate(pose_ids)
            }
        )

    return MappingProxyType(result)


# -----------------------------------------------------------------------------
# 18.18. Per-pose diversity scoring
# -----------------------------------------------------------------------------

def rank_pose_diversity_scores(
    pose_scores: Sequence[PoseDiversityScore],
    *,
    epsilon: float = DEFAULT_DIVERSITY_EPSILON,
) -> Tuple[PoseDiversityScore, ...]:
    """
    Rank poses by decreasing mean distance.
    """

    ordered = sorted(
        pose_scores,
        key=lambda score: (
            -score.mean_distance,
            score.pose_id,
        ),
    )

    ranked: List[PoseDiversityScore] = []
    current_rank = 1

    for index, score in enumerate(ordered):
        if index == 0:
            current_rank = 1

        else:
            previous = ordered[index - 1]

            if (
                abs(
                    score.mean_distance
                    - previous.mean_distance
                )
                > epsilon
            ):
                current_rank = index + 1

        ranked.append(
            replace(
                score,
                diversity_rank=current_rank,
            )
        )

    return tuple(ranked)


def build_pose_diversity_scores(
    fingerprints: Sequence[PoseFingerprint],
    similarity_matrix: Sequence[Sequence[float]],
    distance_matrix: Sequence[Sequence[float]],
    *,
    epsilon: float = DEFAULT_DIVERSITY_EPSILON,
) -> Tuple[PoseDiversityScore, ...]:
    """
    Build per-pose diversity summaries.
    """

    count = len(fingerprints)

    if count == 0:
        return ()

    results: List[PoseDiversityScore] = []

    for index, fingerprint in enumerate(fingerprints):
        other_indices = tuple(
            other_index
            for other_index in range(count)
            if other_index != index
        )

        if not other_indices:
            similarities = (1.0,)
            distances = (0.0,)
            nearest_index = index
            farthest_index = index

        else:
            similarities = tuple(
                float(similarity_matrix[index][other_index])
                for other_index in other_indices
            )
            distances = tuple(
                float(distance_matrix[index][other_index])
                for other_index in other_indices
            )

            nearest_index = min(
                other_indices,
                key=lambda other_index: (
                    distance_matrix[index][other_index],
                    fingerprints[other_index].pose_id,
                ),
            )
            farthest_index = max(
                other_indices,
                key=lambda other_index: (
                    distance_matrix[index][other_index],
                    fingerprints[other_index].pose_id,
                ),
            )

        results.append(
            PoseDiversityScore(
                pose_id=fingerprint.pose_id,
                model_id=fingerprint.model_id,
                ligand_id=fingerprint.ligand_id,
                mean_similarity=float(
                    statistics.fmean(similarities)
                ),
                mean_distance=float(
                    statistics.fmean(distances)
                ),
                minimum_distance=float(min(distances)),
                maximum_distance=float(max(distances)),
                median_distance=float(
                    statistics.median(distances)
                ),
                nearest_pose_id=(
                    fingerprints[nearest_index].pose_id
                ),
                nearest_pose_distance=float(
                    distance_matrix[index][nearest_index]
                ),
                farthest_pose_id=(
                    fingerprints[farthest_index].pose_id
                ),
                farthest_pose_distance=float(
                    distance_matrix[index][farthest_index]
                ),
                pose_score=fingerprint.pose_score,
            )
        )

    return rank_pose_diversity_scores(
        results,
        epsilon=epsilon,
    )


# -----------------------------------------------------------------------------
# 18.19. Representative-pose selection
# -----------------------------------------------------------------------------

def select_central_pose_index(
    distance_matrix: Sequence[Sequence[float]],
    pose_ids: Sequence[str],
) -> int:
    """
    Return the pose index with the lowest mean distance.
    """

    if not distance_matrix:
        raise RepresentativeSelectionError(
            "Cannot select a central pose from an empty matrix."
        )

    mean_distances = tuple(
        statistics.fmean(row)
        for row in distance_matrix
    )

    return min(
        range(len(mean_distances)),
        key=lambda index: (
            mean_distances[index],
            pose_ids[index],
        ),
    )


def select_highest_score_pose_index(
    fingerprints: Sequence[PoseFingerprint],
) -> int:
    """
    Return the index of the highest-scoring pose.
    """

    if not fingerprints:
        raise RepresentativeSelectionError(
            "Cannot select a pose from an empty collection."
        )

    return max(
        range(len(fingerprints)),
        key=lambda index: (
            (
                fingerprints[index].pose_score
                if fingerprints[index].pose_score is not None
                else -math.inf
            ),
            fingerprints[index].pose_id,
        ),
    )


def select_farthest_unselected_index(
    selected_indices: Sequence[int],
    candidate_indices: Sequence[int],
    distance_matrix: Sequence[Sequence[float]],
    pose_ids: Sequence[str],
) -> int:
    """
    Select the candidate maximizing its minimum distance to selected poses.
    """

    if not selected_indices:
        raise RepresentativeSelectionError(
            "At least one selected pose is required."
        )

    if not candidate_indices:
        raise RepresentativeSelectionError(
            "At least one candidate pose is required."
        )

    return max(
        candidate_indices,
        key=lambda candidate_index: (
            min(
                distance_matrix[candidate_index][selected_index]
                for selected_index in selected_indices
            ),
            pose_ids[candidate_index],
        ),
    )


def select_representative_pose_indices(
    fingerprints: Sequence[PoseFingerprint],
    distance_matrix: Sequence[Sequence[float]],
    *,
    count: int,
    method: str = DEFAULT_REPRESENTATIVE_SELECTION_METHOD,
) -> Tuple[int, ...]:
    """
    Select representative pose indices deterministically.
    """

    pose_count = len(fingerprints)

    if pose_count == 0:
        return ()

    normalized_count = min(
        max(1, int(count)),
        pose_count,
    )
    normalized_method = (
        normalize_representative_selection_method(
            method
        )
    )
    pose_ids = tuple(
        fingerprint.pose_id
        for fingerprint in fingerprints
    )

    if normalized_method == REPRESENTATIVE_SELECTION_CENTRAL:
        first_index = select_central_pose_index(
            distance_matrix,
            pose_ids,
        )

    elif (
        normalized_method
        == REPRESENTATIVE_SELECTION_HIGHEST_SCORE
    ):
        first_index = select_highest_score_pose_index(
            fingerprints
        )

    elif normalized_method in {
        REPRESENTATIVE_SELECTION_MAX_MIN,
        REPRESENTATIVE_SELECTION_FARTHEST_FIRST,
    }:
        first_index = select_central_pose_index(
            distance_matrix,
            pose_ids,
        )

    else:
        raise RepresentativeSelectionError(
            f"Unsupported representative selection method: "
            f"{normalized_method!r}."
        )

    selected: List[int] = [first_index]

    while len(selected) < normalized_count:
        candidates = tuple(
            index
            for index in range(pose_count)
            if index not in selected
        )

        next_index = select_farthest_unselected_index(
            selected,
            candidates,
            distance_matrix,
            pose_ids,
        )

        selected.append(next_index)

    return tuple(selected)


def mark_representative_pose_scores(
    pose_scores: Sequence[PoseDiversityScore],
    *,
    selected_pose_ids: Sequence[str],
) -> Tuple[PoseDiversityScore, ...]:
    """
    Mark selected representative poses and their selection order.
    """

    selection_order = {
        pose_id: index + 1
        for index, pose_id
        in enumerate(selected_pose_ids)
    }

    return tuple(
        replace(
            pose_score,
            representative=(
                pose_score.pose_id in selection_order
            ),
            representative_order=selection_order.get(
                pose_score.pose_id
            ),
        )
        for pose_score in pose_scores
    )


# -----------------------------------------------------------------------------
# 18.20. Global diversity summary
# -----------------------------------------------------------------------------

def aggregate_diversity_values(
    values: Sequence[float],
    *,
    mode: str = DEFAULT_DIVERSITY_AGGREGATION_MODE,
) -> float:
    """
    Aggregate pairwise diversity values.
    """

    if not values:
        return 0.0

    normalized_mode = normalize_diversity_aggregation_mode(
        mode
    )

    if normalized_mode == DIVERSITY_AGGREGATION_MEAN:
        return float(statistics.fmean(values))

    if normalized_mode == DIVERSITY_AGGREGATION_MEDIAN:
        return float(statistics.median(values))

    if normalized_mode == DIVERSITY_AGGREGATION_MINIMUM:
        return float(min(values))

    if normalized_mode == DIVERSITY_AGGREGATION_MAXIMUM:
        return float(max(values))

    raise DiversityInputError(
        f"Unsupported diversity aggregation mode: "
        f"{normalized_mode!r}."
    )


def fingerprint_signature(
    fingerprint: PoseFingerprint,
    *,
    epsilon: float = DEFAULT_DIVERSITY_EPSILON,
) -> Tuple[Tuple[str, float], ...]:
    """
    Return a deterministic hashable fingerprint signature.
    """

    return tuple(
        (
            feature,
            0.0
            if abs(value) <= epsilon
            else float(value),
        )
        for feature, value in fingerprint.values.items()
    )


def build_diversity_summary(
    fingerprints: Sequence[PoseFingerprint],
    pairs: Sequence[PosePairDiversity],
    pose_scores: Sequence[PoseDiversityScore],
    vocabulary: Sequence[str],
    *,
    aggregation_mode: str = (
        DEFAULT_DIVERSITY_AGGREGATION_MODE
    ),
    epsilon: float = DEFAULT_DIVERSITY_EPSILON,
) -> DiversitySummary:
    """
    Build a global diversity-analysis summary.
    """

    similarities = tuple(
        pair.similarity
        for pair in pairs
    )
    distances = tuple(
        pair.distance
        for pair in pairs
    )

    if pairs:
        most_similar_pair_result = min(
            pairs,
            key=lambda pair: (
                pair.distance,
                pair.pose_id_a,
                pair.pose_id_b,
            ),
        )
        most_dissimilar_pair_result = max(
            pairs,
            key=lambda pair: (
                pair.distance,
                pair.pose_id_a,
                pair.pose_id_b,
            ),
        )

        most_similar_pair = (
            most_similar_pair_result.pose_id_a,
            most_similar_pair_result.pose_id_b,
        )
        most_dissimilar_pair = (
            most_dissimilar_pair_result.pose_id_a,
            most_dissimilar_pair_result.pose_id_b,
        )

    else:
        most_similar_pair = ()
        most_dissimilar_pair = ()

    most_central_pose_id = (
        min(
            pose_scores,
            key=lambda score: (
                score.mean_distance,
                score.pose_id,
            ),
        ).pose_id
        if pose_scores
        else ""
    )
    most_diverse_pose_id = (
        max(
            pose_scores,
            key=lambda score: (
                score.mean_distance,
                score.pose_id,
            ),
        ).pose_id
        if pose_scores
        else ""
    )

    signatures = {
        fingerprint_signature(
            fingerprint,
            epsilon=epsilon,
        )
        for fingerprint in fingerprints
    }

    return DiversitySummary(
        pose_count=len(fingerprints),
        pair_count=len(pairs),
        feature_count=len(vocabulary),
        mean_similarity=(
            aggregate_diversity_values(
                similarities,
                mode=aggregation_mode,
            )
            if similarities
            else 1.0
        ),
        mean_distance=(
            aggregate_diversity_values(
                distances,
                mode=aggregation_mode,
            )
            if distances
            else 0.0
        ),
        minimum_distance=(
            float(min(distances))
            if distances
            else 0.0
        ),
        maximum_distance=(
            float(max(distances))
            if distances
            else 0.0
        ),
        median_distance=(
            float(statistics.median(distances))
            if distances
            else 0.0
        ),
        identical_pair_count=sum(
            pair.distance <= epsilon
            for pair in pairs
        ),
        unique_fingerprint_count=len(signatures),
        most_central_pose_id=most_central_pose_id,
        most_diverse_pose_id=most_diverse_pose_id,
        most_similar_pair=most_similar_pair,
        most_dissimilar_pair=most_dissimilar_pair,
        representative_pose_ids=tuple(
            score.pose_id
            for score in sorted(
                (
                    score
                    for score in pose_scores
                    if score.representative
                ),
                key=lambda score: (
                    score.representative_order
                    if score.representative_order is not None
                    else math.inf,
                    score.pose_id,
                ),
            )
        ),
    )


# -----------------------------------------------------------------------------
# 18.21. Main diversity API
# -----------------------------------------------------------------------------

def compute_pose_diversity(
    pose_results: Iterable[PoseScoringResult],
    *,
    options: DiversityOptions = DEFAULT_DIVERSITY_OPTIONS,
) -> PoseDiversityResult:
    """
    Compute cross-pose fingerprint diversity.

    This function:
    1. generates pose fingerprints;
    2. aligns the feature vocabulary;
    3. computes pairwise similarity and distance;
    4. creates symmetric matrices;
    5. calculates per-pose diversity;
    6. selects representative poses.
    """

    validate_diversity_options(options)

    normalized_pose_results = (
        materialize_pose_scoring_results(
            pose_results
        )
    )

    if not normalized_pose_results:
        empty_summary = DiversitySummary(
            pose_count=0,
            pair_count=0,
            feature_count=0,
            mean_similarity=0.0,
            mean_distance=0.0,
            minimum_distance=0.0,
            maximum_distance=0.0,
            median_distance=0.0,
            identical_pair_count=0,
            unique_fingerprint_count=0,
        )

        return PoseDiversityResult(
            status=DIVERSITY_STATUS_EMPTY,
            fingerprints=(),
            pairs=(),
            pose_scores=(),
            similarity_matrix=(),
            distance_matrix=(),
            vocabulary=(),
            summary=empty_summary,
            similarity_metric=options.similarity_metric,
            distance_metric=options.distance_metric,
            message="No pose-scoring results were supplied.",
            metadata={
                "options": options.to_dict(
                    include_metadata=True
                ),
            },
        )

    for pose_result in normalized_pose_results:
        validate_pose_scoring_result(pose_result)

    fingerprints = build_pose_fingerprints(
        normalized_pose_results,
        options=options.fingerprint_options,
        preserve_pose_results=(
            options.preserve_pose_results
        ),
    )

    vocabulary = build_fingerprint_vocabulary(
        fingerprints
    )

    pairs = compute_pairwise_pose_diversity(
        fingerprints,
        similarity_metric=options.similarity_metric,
        distance_metric=options.distance_metric,
        epsilon=options.epsilon,
    )

    similarity_matrix, distance_matrix = (
        compute_diversity_matrices(
            fingerprints,
            similarity_metric=options.similarity_metric,
            distance_metric=options.distance_metric,
            epsilon=options.epsilon,
        )
    )

    pose_scores = build_pose_diversity_scores(
        fingerprints,
        similarity_matrix,
        distance_matrix,
        epsilon=options.epsilon,
    )

    representative_count = (
        options.representative_count
        if options.representative_count is not None
        else min(
            len(fingerprints),
            max(
                1,
                int(
                    math.ceil(
                        math.sqrt(len(fingerprints))
                    )
                ),
            ),
        )
    )

    selected_indices = select_representative_pose_indices(
        fingerprints,
        distance_matrix,
        count=representative_count,
        method=(
            options.representative_selection_method
        ),
    )

    selected_pose_ids = tuple(
        fingerprints[index].pose_id
        for index in selected_indices
    )

    pose_scores = mark_representative_pose_scores(
        pose_scores,
        selected_pose_ids=selected_pose_ids,
    )

    summary = build_diversity_summary(
        fingerprints,
        pairs,
        pose_scores,
        vocabulary,
        aggregation_mode=options.aggregation_mode,
        epsilon=options.epsilon,
    )

    failed_or_empty_pose_count = sum(
        pose_result.status
        in {
            POSE_SCORING_STATUS_FAILED,
            POSE_SCORING_STATUS_EMPTY,
        }
        for pose_result in normalized_pose_results
    )
    partial_pose_count = sum(
        pose_result.status
        == POSE_SCORING_STATUS_PARTIAL
        for pose_result in normalized_pose_results
    )

    if (
        len(fingerprints) > 1
        and summary.unique_fingerprint_count == 1
    ):
        status = DIVERSITY_STATUS_DEGENERATE
        message = (
            "All poses produced equivalent fingerprints under the "
            "selected fingerprint configuration."
        )

    elif failed_or_empty_pose_count or partial_pose_count:
        status = DIVERSITY_STATUS_PARTIAL
        message = (
            "Pose diversity was calculated, but at least one input "
            "pose was partial, empty or failed."
        )

    else:
        status = DIVERSITY_STATUS_COMPLETE
        message = "Pose diversity was calculated successfully."

    result = PoseDiversityResult(
        status=status,
        fingerprints=fingerprints,
        pairs=pairs,
        pose_scores=pose_scores,
        similarity_matrix=similarity_matrix,
        distance_matrix=distance_matrix,
        vocabulary=vocabulary,
        summary=summary,
        similarity_metric=options.similarity_metric,
        distance_metric=options.distance_metric,
        message=message,
        metadata={
            "fingerprint_kind": (
                options.fingerprint_options.kind
            ),
            "fingerprint_value_mode": (
                options.fingerprint_options.value_mode
            ),
            "representative_selection_method": (
                options.representative_selection_method
            ),
            "representative_count": (
                representative_count
            ),
            "partial_pose_count": partial_pose_count,
            "failed_or_empty_pose_count": (
                failed_or_empty_pose_count
            ),
        },
    )

    if options.validate_result:
        validate_pose_diversity_result(result)

    return result


def compute_diversity_matrix(
    pose_results: Iterable[PoseScoringResult],
    *,
    options: DiversityOptions = DEFAULT_DIVERSITY_OPTIONS,
) -> Tuple[Tuple[float, ...], ...]:
    """
    Compute and return only the pose distance matrix.
    """

    return compute_pose_diversity(
        pose_results,
        options=options,
    ).distance_matrix


def rank_diverse_poses(
    pose_results: Iterable[PoseScoringResult],
    *,
    options: DiversityOptions = DEFAULT_DIVERSITY_OPTIONS,
) -> Tuple[PoseDiversityScore, ...]:
    """
    Compute diversity and return poses ordered by diversity rank.
    """

    return compute_pose_diversity(
        pose_results,
        options=options,
    ).pose_scores


def select_representative_poses(
    pose_results: Iterable[PoseScoringResult],
    *,
    count: int,
    options: DiversityOptions = DEFAULT_DIVERSITY_OPTIONS,
) -> Tuple[PoseScoringResult, ...]:
    """
    Select representative PoseScoringResult objects.
    """

    adjusted_options = options.with_updates(
        representative_count=count,
        preserve_pose_results=True,
    )

    result = compute_pose_diversity(
        pose_results,
        options=adjusted_options,
    )

    representatives: List[PoseScoringResult] = []

    for pose_score in sorted(
        result.representatives,
        key=lambda score: (
            score.representative_order
            if score.representative_order is not None
            else math.inf,
            score.pose_id,
        ),
    ):
        matching_fingerprint = next(
            (
                fingerprint
                for fingerprint in result.fingerprints
                if fingerprint.pose_id == pose_score.pose_id
            ),
            None,
        )

        if (
            matching_fingerprint is not None
            and matching_fingerprint.pose_result is not None
        ):
            representatives.append(
                matching_fingerprint.pose_result
            )

    return tuple(representatives)


# -----------------------------------------------------------------------------
# 18.22. Lookup helpers
# -----------------------------------------------------------------------------

def get_pose_fingerprint(
    result: PoseDiversityResult,
    pose_id: str,
) -> Optional[PoseFingerprint]:
    """
    Return the first fingerprint matching a pose identifier.
    """

    validate_pose_diversity_result(result)

    normalized_pose_id = _coerce_identifier(pose_id)

    for fingerprint in result.fingerprints:
        if fingerprint.pose_id == normalized_pose_id:
            return fingerprint

    return None


def get_pose_diversity_score(
    result: PoseDiversityResult,
    pose_id: str,
) -> Optional[PoseDiversityScore]:
    """
    Return the first diversity score matching a pose identifier.
    """

    validate_pose_diversity_result(result)

    normalized_pose_id = _coerce_identifier(pose_id)

    for pose_score in result.pose_scores:
        if pose_score.pose_id == normalized_pose_id:
            return pose_score

    return None


def get_pose_pair_diversity(
    result: PoseDiversityResult,
    pose_id_a: str,
    pose_id_b: str,
) -> Optional[PosePairDiversity]:
    """
    Return the pairwise result for two pose identifiers.
    """

    validate_pose_diversity_result(result)

    normalized_a = _coerce_identifier(pose_id_a)
    normalized_b = _coerce_identifier(pose_id_b)

    for pair in result.pairs:
        if {
            pair.pose_id_a,
            pair.pose_id_b,
        } == {
            normalized_a,
            normalized_b,
        }:
            return pair

    return None


def representative_pose_scores(
    result: PoseDiversityResult,
) -> Tuple[PoseDiversityScore, ...]:
    """
    Return representative poses in selection order.
    """

    validate_pose_diversity_result(result)

    return tuple(
        sorted(
            result.representatives,
            key=lambda score: (
                score.representative_order
                if score.representative_order is not None
                else math.inf,
                score.pose_id,
            ),
        )
    )


# -----------------------------------------------------------------------------
# 18.23. Compact summaries
# -----------------------------------------------------------------------------

def summarize_pose_fingerprint(
    fingerprint: PoseFingerprint,
) -> Mapping[str, Any]:
    """
    Return a compact immutable fingerprint summary.
    """

    validate_pose_fingerprint(fingerprint)

    return MappingProxyType(
        {
            "pose_id": fingerprint.pose_id,
            "kind": fingerprint.kind,
            "value_mode": fingerprint.value_mode,
            "feature_count": fingerprint.feature_count,
            "active_feature_count": (
                fingerprint.active_feature_count
            ),
            "total_value": fingerprint.total_value,
            "vector_norm": fingerprint.vector_norm,
            "pose_score": fingerprint.pose_score,
            "active_features": (
                fingerprint.active_features
            ),
        }
    )


def summarize_pose_diversity_result(
    result: PoseDiversityResult,
) -> Mapping[str, Any]:
    """
    Return a compact immutable diversity summary.
    """

    validate_pose_diversity_result(result)

    return MappingProxyType(
        {
            "status": result.status,
            "pose_count": result.summary.pose_count,
            "pair_count": result.summary.pair_count,
            "feature_count": (
                result.summary.feature_count
            ),
            "mean_similarity": (
                result.summary.mean_similarity
            ),
            "mean_distance": result.summary.mean_distance,
            "minimum_distance": (
                result.summary.minimum_distance
            ),
            "maximum_distance": (
                result.summary.maximum_distance
            ),
            "unique_fingerprint_count": (
                result.summary.unique_fingerprint_count
            ),
            "identical_pair_count": (
                result.summary.identical_pair_count
            ),
            "most_central_pose_id": (
                result.summary.most_central_pose_id
            ),
            "most_diverse_pose_id": (
                result.summary.most_diverse_pose_id
            ),
            "representative_pose_ids": (
                result.summary.representative_pose_ids
            ),
            "pose_ranking": tuple(
                {
                    "rank": pose_score.diversity_rank,
                    "pose_id": pose_score.pose_id,
                    "mean_distance": (
                        pose_score.mean_distance
                    ),
                    "representative": (
                        pose_score.representative
                    ),
                    "representative_order": (
                        pose_score.representative_order
                    ),
                }
                for pose_score in result.pose_scores
            ),
        }
    )


# -----------------------------------------------------------------------------
# 18.24. Serialization
# -----------------------------------------------------------------------------

def pose_fingerprint_to_dict(
    fingerprint: PoseFingerprint,
    *,
    include_metadata: bool = True,
    include_pose_result: bool = False,
) -> Dict[str, Any]:
    """
    Convert one fingerprint to a dictionary.
    """

    validate_pose_fingerprint(fingerprint)

    return fingerprint.to_dict(
        include_metadata=include_metadata,
        include_pose_result=include_pose_result,
    )


def pose_pair_diversity_to_dict(
    pair: PosePairDiversity,
    *,
    include_metadata: bool = True,
) -> Dict[str, Any]:
    """
    Convert one pairwise comparison to a dictionary.
    """

    validate_pose_pair_diversity(pair)

    return pair.to_dict(
        include_metadata=include_metadata
    )


def pose_diversity_result_to_dict(
    result: PoseDiversityResult,
    *,
    include_metadata: bool = True,
    include_pose_results: bool = False,
) -> Dict[str, Any]:
    """
    Convert a complete diversity result to a dictionary.
    """

    validate_pose_diversity_result(result)

    return result.to_dict(
        include_metadata=include_metadata,
        include_pose_results=include_pose_results,
    )


def serialize_pose_diversity_result(
    result: PoseDiversityResult,
    *,
    indent: Optional[int] = 2,
    sort_keys: bool = True,
    include_metadata: bool = True,
    include_pose_results: bool = False,
) -> str:
    """
    Serialize a pose-diversity result as JSON.
    """

    return json.dumps(
        pose_diversity_result_to_dict(
            result,
            include_metadata=include_metadata,
            include_pose_results=include_pose_results,
        ),
        indent=indent,
        sort_keys=sort_keys,
        ensure_ascii=False,
        default=str,
    )


# -----------------------------------------------------------------------------
# 18.25. Validation
# -----------------------------------------------------------------------------

def validate_fingerprint_options(
    options: FingerprintOptions,
) -> FingerprintOptions:
    """
    Validate fingerprint options.
    """

    if not isinstance(options, FingerprintOptions):
        raise DiversityValidationError(
            "Expected FingerprintOptions."
        )

    if (
        options.hotspot_limit is not None
        and options.hotspot_limit < 1
    ):
        raise DiversityValidationError(
            "hotspot_limit must be positive or None."
        )

    return options


def validate_diversity_options(
    options: DiversityOptions,
) -> DiversityOptions:
    """
    Validate diversity-analysis options.
    """

    if not isinstance(options, DiversityOptions):
        raise DiversityValidationError(
            "Expected DiversityOptions."
        )

    validate_fingerprint_options(
        options.fingerprint_options
    )

    if options.epsilon <= 0.0:
        raise DiversityValidationError(
            "Diversity epsilon must be positive."
        )

    return options


def validate_pose_fingerprint(
    fingerprint: PoseFingerprint,
) -> PoseFingerprint:
    """
    Validate one pose fingerprint.
    """

    if not isinstance(fingerprint, PoseFingerprint):
        raise DiversityValidationError(
            "Expected PoseFingerprint."
        )

    if fingerprint.feature_count != len(
        fingerprint.values
    ):
        raise DiversityValidationError(
            "Fingerprint feature_count is inconsistent."
        )

    calculated_active_count = sum(
        abs(value) > DEFAULT_DIVERSITY_EPSILON
        for value in fingerprint.values.values()
    )

    if (
        fingerprint.active_feature_count
        != calculated_active_count
    ):
        raise DiversityValidationError(
            "Fingerprint active_feature_count is inconsistent."
        )

    calculated_norm = math.sqrt(
        sum(
            value * value
            for value in fingerprint.values.values()
        )
    )

    if (
        abs(calculated_norm - fingerprint.vector_norm)
        > SCORE_COMPARISON_TOLERANCE
    ):
        raise DiversityValidationError(
            "Fingerprint vector_norm is inconsistent."
        )

    if fingerprint.pose_result is not None:
        validate_pose_scoring_result(
            fingerprint.pose_result
        )

    return fingerprint


def validate_pose_pair_diversity(
    pair: PosePairDiversity,
) -> PosePairDiversity:
    """
    Validate one pairwise diversity record.
    """

    if not isinstance(pair, PosePairDiversity):
        raise DiversityValidationError(
            "Expected PosePairDiversity."
        )

    if (
        pair.shared_feature_count
        != len(pair.shared_features)
    ):
        raise DiversityValidationError(
            "Pair shared_feature_count is inconsistent."
        )

    if (
        pair.exclusive_feature_count_a
        != len(pair.exclusive_features_a)
    ):
        raise DiversityValidationError(
            "Pair exclusive_feature_count_a is inconsistent."
        )

    if (
        pair.exclusive_feature_count_b
        != len(pair.exclusive_features_b)
    ):
        raise DiversityValidationError(
            "Pair exclusive_feature_count_b is inconsistent."
        )

    expected_union_count = (
        pair.shared_feature_count
        + pair.exclusive_feature_count_a
        + pair.exclusive_feature_count_b
    )

    if pair.union_feature_count != expected_union_count:
        raise DiversityValidationError(
            "Pair union_feature_count is inconsistent."
        )

    return pair


def validate_pose_diversity_score(
    score: PoseDiversityScore,
) -> PoseDiversityScore:
    """
    Validate one per-pose diversity summary.
    """

    if not isinstance(score, PoseDiversityScore):
        raise DiversityValidationError(
            "Expected PoseDiversityScore."
        )

    if score.minimum_distance > score.maximum_distance:
        raise DiversityValidationError(
            "minimum_distance cannot exceed maximum_distance."
        )

    if (
        score.representative_order is not None
        and not score.representative
    ):
        raise DiversityValidationError(
            "representative_order requires representative=True."
        )

    return score


def validate_diversity_summary(
    summary: DiversitySummary,
) -> DiversitySummary:
    """
    Validate a global diversity summary.
    """

    if not isinstance(summary, DiversitySummary):
        raise DiversityValidationError(
            "Expected DiversitySummary."
        )

    expected_pair_count = (
        summary.pose_count
        * (summary.pose_count - 1)
        // 2
    )

    if summary.pair_count != expected_pair_count:
        raise DiversityValidationError(
            "Diversity pair_count is inconsistent."
        )

    if (
        summary.unique_fingerprint_count
        > summary.pose_count
    ):
        raise DiversityValidationError(
            "unique_fingerprint_count cannot exceed pose_count."
        )

    return summary


def validate_square_diversity_matrix(
    matrix: Sequence[Sequence[float]],
    *,
    expected_size: int,
    diagonal_value: float,
    epsilon: float = DEFAULT_DIVERSITY_EPSILON,
) -> None:
    """
    Validate a symmetric square diversity matrix.
    """

    if len(matrix) != expected_size:
        raise DiversityValidationError(
            "Matrix row count is inconsistent."
        )

    for row in matrix:
        if len(row) != expected_size:
            raise DiversityValidationError(
                "Matrix is not square."
            )

    for row_index in range(expected_size):
        if (
            abs(
                matrix[row_index][row_index]
                - diagonal_value
            )
            > epsilon
        ):
            raise DiversityValidationError(
                "Matrix diagonal is inconsistent."
            )

        for column_index in range(expected_size):
            if (
                abs(
                    matrix[row_index][column_index]
                    - matrix[column_index][row_index]
                )
                > epsilon
            ):
                raise DiversityValidationError(
                    "Matrix is not symmetric."
                )


def validate_pose_diversity_result(
    result: PoseDiversityResult,
) -> PoseDiversityResult:
    """
    Validate a complete pose-diversity result.
    """

    if not isinstance(result, PoseDiversityResult):
        raise DiversityValidationError(
            "Expected PoseDiversityResult."
        )

    for fingerprint in result.fingerprints:
        validate_pose_fingerprint(fingerprint)

    for pair in result.pairs:
        validate_pose_pair_diversity(pair)

    for pose_score in result.pose_scores:
        validate_pose_diversity_score(pose_score)

    validate_diversity_summary(result.summary)

    pose_count = len(result.fingerprints)

    if result.summary.pose_count != pose_count:
        raise DiversityValidationError(
            "Summary pose_count is inconsistent."
        )

    if len(result.pose_scores) != pose_count:
        raise DiversityValidationError(
            "pose_scores count is inconsistent."
        )

    if len(result.pairs) != result.summary.pair_count:
        raise DiversityValidationError(
            "Pair collection count is inconsistent."
        )

    validate_square_diversity_matrix(
        result.similarity_matrix,
        expected_size=pose_count,
        diagonal_value=1.0,
    )
    validate_square_diversity_matrix(
        result.distance_matrix,
        expected_size=pose_count,
        diagonal_value=0.0,
    )

    calculated_vocabulary = (
        build_fingerprint_vocabulary(
            result.fingerprints
        )
    )

    if result.vocabulary != calculated_vocabulary:
        raise DiversityValidationError(
            "Fingerprint vocabulary is inconsistent."
        )

    representative_pose_ids = tuple(
        score.pose_id
        for score in sorted(
            (
                score
                for score in result.pose_scores
                if score.representative
            ),
            key=lambda score: (
                score.representative_order
                if score.representative_order is not None
                else math.inf,
                score.pose_id,
            ),
        )
    )

    if (
        result.summary.representative_pose_ids
        != representative_pose_ids
    ):
        raise DiversityValidationError(
            "Representative pose identifiers are inconsistent."
        )

    return result


# -----------------------------------------------------------------------------
# 18.26. Section consistency validation
# -----------------------------------------------------------------------------

def _validate_section_18_diversity_part_1() -> None:
    """
    Validate Section 18 Part 1 during module import.
    """

    fingerprint_a = PoseFingerprint(
        pose_id="pose_a",
        model_id="model",
        ligand_id="ligand",
        kind=FINGERPRINT_KIND_RESIDUE,
        value_mode=FINGERPRINT_VALUE_BINARY,
        values={
            "residue:A:10:LYS": 1.0,
            "residue:A:20:VAL": 1.0,
        },
        feature_count=2,
        active_feature_count=2,
        total_value=2.0,
        vector_norm=math.sqrt(2.0),
        pose_score=3.0,
    )

    fingerprint_b = PoseFingerprint(
        pose_id="pose_b",
        model_id="model",
        ligand_id="ligand",
        kind=FINGERPRINT_KIND_RESIDUE,
        value_mode=FINGERPRINT_VALUE_BINARY,
        values={
            "residue:A:10:LYS": 1.0,
            "residue:A:30:PHE": 1.0,
        },
        feature_count=2,
        active_feature_count=2,
        total_value=2.0,
        vector_norm=math.sqrt(2.0),
        pose_score=2.0,
    )

    fingerprint_c = PoseFingerprint(
        pose_id="pose_c",
        model_id="model",
        ligand_id="ligand",
        kind=FINGERPRINT_KIND_RESIDUE,
        value_mode=FINGERPRINT_VALUE_BINARY,
        values={
            "residue:A:40:ASP": 1.0,
        },
        feature_count=1,
        active_feature_count=1,
        total_value=1.0,
        vector_norm=1.0,
        pose_score=1.0,
    )

    expected_jaccard = 1.0 / 3.0

    if (
        abs(
            jaccard_similarity(
                fingerprint_a,
                fingerprint_b,
            )
            - expected_jaccard
        )
        > SCORE_COMPARISON_TOLERANCE
    ):
        raise RuntimeError(
            "Jaccard similarity validation failed."
        )

    if (
        abs(
            dice_similarity(
                fingerprint_a,
                fingerprint_b,
            )
            - 0.5
        )
        > SCORE_COMPARISON_TOLERANCE
    ):
        raise RuntimeError(
            "Dice similarity validation failed."
        )

    if (
        abs(
            overlap_similarity(
                fingerprint_a,
                fingerprint_b,
            )
            - 0.5
        )
        > SCORE_COMPARISON_TOLERANCE
    ):
        raise RuntimeError(
            "Overlap similarity validation failed."
        )

    if (
        abs(
            cosine_similarity(
                fingerprint_a,
                fingerprint_b,
            )
            - 0.5
        )
        > SCORE_COMPARISON_TOLERANCE
    ):
        raise RuntimeError(
            "Cosine similarity validation failed."
        )

    pair = compare_pose_fingerprints(
        fingerprint_a,
        fingerprint_b,
    )

    if pair.shared_feature_count != 1:
        raise RuntimeError(
            "Pair shared-feature validation failed."
        )

    fingerprints = (
        fingerprint_a,
        fingerprint_b,
        fingerprint_c,
    )

    similarity_matrix, distance_matrix = (
        compute_diversity_matrices(fingerprints)
    )

    if len(similarity_matrix) != 3:
        raise RuntimeError(
            "Similarity-matrix validation failed."
        )

    if similarity_matrix[0][0] != 1.0:
        raise RuntimeError(
            "Similarity diagonal validation failed."
        )

    if distance_matrix[0][0] != 0.0:
        raise RuntimeError(
            "Distance diagonal validation failed."
        )

    pairs = compute_pairwise_pose_diversity(
        fingerprints
    )

    if len(pairs) != 3:
        raise RuntimeError(
            "Pairwise count validation failed."
        )

    pose_scores = build_pose_diversity_scores(
        fingerprints,
        similarity_matrix,
        distance_matrix,
    )

    if len(pose_scores) != 3:
        raise RuntimeError(
            "Per-pose diversity validation failed."
        )

    selected_indices = (
        select_representative_pose_indices(
            fingerprints,
            distance_matrix,
            count=2,
            method=REPRESENTATIVE_SELECTION_MAX_MIN,
        )
    )

    if len(selected_indices) != 2:
        raise RuntimeError(
            "Representative-selection validation failed."
        )

    selected_pose_ids = tuple(
        fingerprints[index].pose_id
        for index in selected_indices
    )

    marked_scores = mark_representative_pose_scores(
        pose_scores,
        selected_pose_ids=selected_pose_ids,
    )

    summary = build_diversity_summary(
        fingerprints,
        pairs,
        marked_scores,
        build_fingerprint_vocabulary(
            fingerprints
        ),
    )

    result = PoseDiversityResult(
        status=DIVERSITY_STATUS_COMPLETE,
        fingerprints=fingerprints,
        pairs=pairs,
        pose_scores=marked_scores,
        similarity_matrix=similarity_matrix,
        distance_matrix=distance_matrix,
        vocabulary=build_fingerprint_vocabulary(
            fingerprints
        ),
        summary=summary,
        similarity_metric=SIMILARITY_JACCARD,
        distance_metric=DISTANCE_COMPLEMENT,
        message="Synthetic diversity validation.",
    )

    validate_fingerprint_options(
        DEFAULT_FINGERPRINT_OPTIONS
    )
    validate_diversity_options(
        DEFAULT_DIVERSITY_OPTIONS
    )

    for fingerprint in fingerprints:
        validate_pose_fingerprint(fingerprint)

    for pair_result in pairs:
        validate_pose_pair_diversity(pair_result)

    for pose_score in marked_scores:
        validate_pose_diversity_score(pose_score)

    validate_diversity_summary(summary)
    validate_pose_diversity_result(result)

    serialized = serialize_pose_diversity_result(
        result
    )

    if "pose_a" not in serialized:
        raise RuntimeError(
            "Diversity serialization validation failed."
        )


_validate_section_18_diversity_part_1()


